me, method, ...) local service = ConfigState.userDataServices[serviceName] if service == nil then service = requireUserDataService(serviceName) ConfigState.userDataServices[serviceName] = service end return (service[method])(...) end function ConfigState.PlayerData.Balance(currencyName) local value = callUserDataService("Currency", "Balance", currencyName) return tonumber(value) or 0 end function ConfigState.PlayerData.Tickets() local value = callUserDataService("Event", "Balance") return tonumber(value) or 0 end ConfigState.PlayerData.EventActive = function() local active = callUserDataService("Event", "IsActive") if active == true then return true end local shop = ConfigState.PlayerData.Shop("Event") if shop and type(shop.IsOpen) == "function" then local open = shop.IsOpen() return open == true end return false end function ConfigState.PlayerData.EventTiers() local tiers = callUserDataService("Event", "GetTiers") if type(tiers) == "table" then return tiers end return {} end ConfigState.PlayerData.EventExchanges = function() local _, event = callUserDataService("Event", "GetCurrent") if type(event) == "table" and type(event.Exchanges) == "table" then return event.Exchanges end return {} end function ConfigState.PlayerData.EventPhase() local phase = callUserDataService("Event", "GetPhase") return phase or nil end function ConfigState.PlayerData.Exchange(to, amount) callUserDataService("Event", "Exchange", to, amount) return true end function ConfigState.PlayerData.Progression() local value = callUserDataService("Progression", "Get") if type(value) == "table" then return value end return { XP = 0, Level = 0 } end function ConfigState.PlayerData.Owns(itemId) local value = callUserDataService("Inventory", "Owns", itemId) return value == true end function ConfigState.PlayerData.OwnedIds() local ids = callUserDataService("Inventory", "OwnedIds") if type(ids) == "table" then return ids end return {} end function ConfigState.PlayerData.Shop(name) local shops = getCachedUserDataService("Shops") return shops and shops[name] or nil end function ConfigState.PlayerData.Stock() local shops = getCachedUserDataService("Shops") if shops and shops.Stock then local all = shops.Stock.All() if type(all) == "table" then return all end end return {} end function ConfigState.PlayerData.StockRecord(key) local shops = getCachedUserDataService("Shops") if shops and shops.Stock then local record = shops.Stock.Get(key) return record end return nil end function ConfigState.PlayerData.PriceOf(key) local shops = getCachedUserDataService("Shops") if shops and shops.Pricing then local price = shops.Pricing.PriceOf(key) return price end return nil end function ConfigState.PlayerData.OwnsStock(key) local shops = getCachedUserDataService("Shops") if shops and shops.Ownership then local owned = shops.Ownership.Owns(key) return owned == true end return false end function ConfigState.PlayerData.Buy(stockKey, amount) local value = callUserDataService("Shops", "Buy", stockKey, amount) return value == true end function ConfigState.PlayerData.Purchase(itemId) local value = callUserDataService("Shops", "Purchase", itemId) return value == true end function CanBeCarried(value) for _, interaction in ipairs(InteractionTypes.Revive.Interactions) do if interaction.Name == "Carry" then interaction.Requirements.CanBeCarried = value end end end ForceEnableEveryonesCarry = Tabs.Main:Toggle({ Title = "Force Enable Everyone's Carry", Desc = [[Are you tired of those cornballs always turning off carry for their dada/Eboy?
This toggle is for you. No matter how they try to disable carry, you will still be able to carry them, but they will still be able to uncarry when they turn off their carry.]], }) ForceEnableEveryonesCarry.Callback = function(s) if s then CanBeCarried(nil) else CanBeCarried(true) end end Tabs.Main:Space() FEBoombox = Tabs.Main:Button({ Title = "Get Free FE Boombox Sound Player", Callback = function() FEBoombox:Destroy() loadstring(game:HttpGet(BaseURL .. "/api/script/obfuscated/Fe/Boomboxs/EvadeOverhaul-RelicsXYZ.lua"))() end }) Tabs.Main:Space() if getconnections then local colaCharacterTask = ReplicatedStorage.Remotes.Character.CharacterTask local colaSharedUI = ReplicatedStorage.Remotes.UI.SharedUISetType local okDrink, DrinkTaskType = pcall(require, ReplicatedStorage.Objects.Game.Tool.Tasks.Types.Drink) if not okDrink then DrinkTaskType = nil end local info = ColaModule and ColaModule.Tasks info = info and info[1] info = info and info.AutomaticFunctions info = info and info[2] info = info and info.Methods info = info and info[1] info = info and info.Info if type(info) ~= "table" then info = {} end local ColaCheat = { ["Visual Infinite"] = false, ["Cola Modifier"] = false, ["Loaded"] = false, ["Custom Duration"] = tonumber(info.Duration), ["Custom Speed"] = tonumber(info.SpeedBoost), ["Original Activate"] = nil, ["Patched"] = nil, ["Watcher"] = nil, ["Pending Drink"] = nil, ["Reassert Thread"] = nil, ["Drink Tools"] = setmetatable({}, { __mode = "k" }), } function ColaCheatFindColor3InTable(value, seen) if typeof(value) == "Color3" then return value end if type(value) ~= "table" or seen[value] then return nil end seen[value] = true for _, child in pairs(value) do local found = ColaCheatFindColor3InTable(child, seen) if found then return found end end return nil end function ColaCheatCollectToolActivationMethods(toolInfo) local list = {} for _, taskInfo in pairs(toolInfo.Tasks or {}) do for _, functionInfo in pairs(taskInfo.Functions or {}) do for _, activation in pairs(functionInfo.Activations or {}) do for _, method in pairs(activation.Methods or {}) do list[#list + 1] = method end end end for _, functionInfo in pairs(taskInfo.AutomaticFunctions or {}) do for _, method in pairs(functionInfo.Methods or {}) do list[#list + 1] = method end end end return list end function ColaCheatIsSpeedBoostMethod(method) return type(method) == "table" and type(method.Info) == "table" and method.Info.SpeedBoost ~= nil end function ColaCheatIsDrinkBoostTool(tasks) local cached = ColaCheat["Drink Tools"][tasks] if cached == nil then cached = false if type(tasks.Info) == "table" then for _, method in ipairs(ColaCheatCollectToolActivationMethods(tasks.Info)) do if ColaCheatIsSpeedBoostMethod(method) then cached = true break end end end ColaCheat["Drink Tools"][tasks] = cached end return cached end function ColaCheatIsLocalPlayerToolOwner(tasks) local owner = tasks.Parent and tasks.Parent.Parent and tasks.Parent.Parent.Parent return owner ~= nil and owner.Local == true end function ColaCheatIsDrinkMethod(tasks, method) local okRef, reference = pcall(tasks.GetMethodReferenceFromMethodTable, tasks, method) if okRef and reference and DrinkTaskType and getmetatable(reference) == DrinkTaskType then return true end return method.MethodReferencing == "Drink" and (method.ActivationType == "Start" or method.ActivationType == "End") end function ColaCheatShouldInterceptActivate(tasks, method) if not ColaCheat["Visual Infinite"] or type(method) ~= "table" or not ColaCheatIsDrinkBoostTool(tasks) then return false end if not (ColaCheatIsDrinkMethod(tasks, method) or ColaCheatIsSpeedBoostMethod(method) or method.ItemUseIncrement ~= nil) then return false end return ColaCheatIsLocalPlayerToolOwner(tasks) end function ColaCheatFireSpeedChange(character, tasks, value, length) FireClient(colaCharacterTask, character:GetAttribute("Tag"), "Movement", { SpeedChange = { Value = value, Type = tasks.Module.Name, Length = length, }, }) end function ColaCheatApplyBoostEffects(tasks, method, withVignette) local character = LocalPlayer.Character local boostInfo = method.Info local defaultLength = boostInfo.Duration or boostInfo.Length local value = boostInfo.SpeedBoost local length = defaultLength local vignetteLength = boostInfo.SuccessImmortalLength or defaultLength if ColaCheat["Cola Modifier"] then value = ColaCheat["Custom Speed"] or value length = ColaCheat["Custom Duration"] or length if ColaCheat["Custom Duration"] then vignetteLength = ColaCheat["Custom Duration"] end end if withVignette then local color = ColaCheatFindColor3InTable(boostInfo, {}) or ColaCheatFindColor3InTable(tasks.Info, {}) if color then FireClient(colaSharedUI, "Vignette", color, vignetteLength, true) end end ColaCheatFireSpeedChange(character, tasks, value, length) return value, length, defaultLength end function ColaCheatReassertBoostAfterServer(tasks, value, length, defaultLength, character) if type(defaultLength) ~= "number" or type(length) ~= "number" or length <= defaultLength then return end if ColaCheat["Reassert Thread"] then pcall(task.cancel, ColaCheat["Reassert Thread"]) end ColaCheat["Reassert Thread"] = task.delay(defaultLength, function() ColaCheat["Reassert Thread"] = nil if ColaCheat["Loaded"] then ColaCheatFireSpeedChange(character, tasks, value, length - defaultLength) end end) end function ColaCheatActivateMethodLocally(tasks, method) local reference = tasks:GetMethodReferenceFromMethodTable(method) local resource = tasks:GetResourceFromMethodTable(method) if reference then reference.LastActivated = tick() end if method.ResourceIncrement and resource then resource:Increment(method.ResourceIncrement) end local activationType, requirement = tasks:ActivationTypeFromMethodTable(method) local cooldown if requirement ~= "Update" then local cooldownInfo = tasks:GetCooldownInfoFromMethod(method) tasks.Parent:AddCooldown(cooldownInfo) cooldown = cooldownInfo.Cooldown end local viewmodelData local characterData if reference then local _, viewmodel, characterVisual = reference:ActivateClient(activationType, method) viewmodelData = viewmodel characterData = characterVisual end if method.VisualName then tasks.Parent.Parent.ViewmodelVisuals:Task(method.VisualName, viewmodelData) tasks.Parent.Parent.CharacterVisuals:Task(method.VisualName, characterData) end return cooldown end function ColaCheatOnServerSpeedBoost(tag, kind, data) local pending = ColaCheat["Pending Drink"] if not pending or kind ~= "Movement" or type(data) ~= "table" or data.SpeedChange == nil then return end if pending.character:GetAttribute("Tag") ~= tag then return end ColaCheat["Pending Drink"] = nil if os.clock() > pending.expires then return end task.defer(function() if not ColaCheat["Loaded"] then return end local value, length, defaultLength = ColaCheatApplyBoostEffects(pending.tasks, pending.method, false) if value then ColaCheatReassertBoostAfterServer(pending.tasks, value, length, defaultLength, pending.character) end end) end ColaCheat["Patched"] = function(self, method, data) if not ColaCheat["Loaded"] then return ColaCheat["Original Activate"](self, method, data) end if ColaCheatShouldInterceptActivate(self, method) then local cooldown = ColaCheatActivateMethodLocally(self, method) if ColaCheatIsSpeedBoostMethod(method) then ColaCheatApplyBoostEffects(self, method, true) end return cooldown end local result = ColaCheat["Original Activate"](self, method, data) if ColaCheat["Cola Modifier"] and ColaCheatIsSpeedBoostMethod(method) and ColaCheatIsDrinkBoostTool(self) and ColaCheatIsLocalPlayerToolOwner(self) and LocalPlayer.Character then local cooldown = result if type(cooldown) ~= "number" then local cooldownInfo = self:GetCooldownInfoFromMethod(method) cooldown = cooldownInfo and cooldownInfo.Cooldown end ColaCheat["Pending Drink"] = { tasks = self, method = method, character = LocalPlayer.Character, expires = os.clock() + (cooldown or method.Info.Duration or method.Info.Length or 0), } end return result end function ColaCheatLoadHooks() if ColaCheat["Loaded"] then return end ColaCheat["Loaded"] = true if not ColaCheat["Original Activate"] then ColaCheat["Original Activate"] = ToolTasks.Activate end if ToolTasks.Activate == ColaCheat["Original Activate"] then ToolTasks.Activate = ColaCheat["Patched"] end ColaCheat["Watcher"] = colaCharacterTask.OnClientEvent:Connect(ColaCheatOnServerSpeedBoost) end function ColaCheatUnloadHooks() if not ColaCheat["Loaded"] then return end ColaCheat["Loaded"] = false if ToolTasks.Activate == ColaCheat["Patched"] then ToolTasks.Activate = ColaCheat["Original Activate"] end if ColaCheat["Watcher"] then ColaCheat["Watcher"]:Disconnect() ColaCheat["Watcher"] = nil end if ColaCheat["Reassert Thread"] then pcall(task.cancel, ColaCheat["Reassert Thread"]) ColaCheat["Reassert Thread"] = nil end ColaCheat["Pending Drink"] = nil end function ColaCheatRefreshHooks() if ColaCheat["Visual Infinite"] or ColaCheat["Cola Modifier"] then ColaCheatLoadHooks() else ColaCheatUnloadHooks() end end local infiniteColaToggle = Tabs.Main:Toggle({ Title = "FE Infinite Cola", }) infiniteColaToggle.Callback = function(state) ColaCheat["Visual Infinite"] = state ColaCheatRefreshHooks() end local colaBoosterToggle = Tabs.Main:Toggle({ Title = "Cola Modifier", }) colaBoosterToggle.Callback = function(state) ColaCheat["Cola Modifier"] = state ColaCheatRefreshHooks() end local colaDurationInput = Tabs.Main:Input({ Title = "Cola Duration Boost", Value = ColaCheat["Custom Duration"] and tostring(ColaCheat["Custom Duration"]) or "", }) colaDurationInput.Callback = function(v) local num = tonumber(v) if num and num > 0 then ColaCheat["Custom Duration"] = num end end local colaSpeedInput = Tabs.Main:Input({ Title = "Cola Speed Boost", Value = ColaCheat["Custom Speed"] and tostring(ColaCheat["Custom Speed"]) or "", }) colaSpeedInput.Callback = function(v) local num = tonumber(v) if num and num > 0 then ColaCheat["Custom Speed"] = num end end else Tabs.Main:Paragraph({ Title = "'getconnections' is not supported. Please Buy or use 🧈 Butter executor from the Tested list" }) end Tabs.Main:Space() pcall(function() if LocalPlayer:GetAttribute("VIPCommandsAccess") == true then loadstring(game:HttpGet(BaseURL .. "/api/script/Tools/EvadeCMDMacroGUI.lua"))() end end) Tabs.Main:Space() VehicleModifierToggle = Tabs.Main:Button({ Title = "Vehicle Modifier", Flag = "VehicleModifierToggle", Desc = "Edit data of every vehicle", Callback = function() if not getgenv().ToggleVehicleModifierUI then loadstring(game:HttpGet(BaseURL .. "/api/script/Tools/Evade_vehicle_modifier.lua"))() end if getgenv().ToggleVehicleModifierUI then getgenv().ToggleVehicleModifierUI(Toggled) end end }) function SendKeybindInfo(info) if not ConfigState.KeybindServiceModule then local okRequire, module = pcall(require, ReplicatedStorage.Services.Client.KeybindService) if not okRequire or not module then return false end ConfigState.KeybindServiceModule = module end local okInfo = pcall(ConfigState.KeybindServiceModule.KeyInfoUsed, ConfigState.KeybindServiceModule, info) if okInfo then return true end return (pcall(ConfigState.KeybindServiceModule.SendKeybind, ConfigState.KeybindServiceModule, info)) end function SendKeybindEvent(key, bool) SendKeybindInfo({ Key = key, Keybind = key, Down = bool }) end if UserInputService.TouchEnabled then local TopbarAppExtra = (getgenv and getgenv() or _G).TopbarAppExtra if not TopbarAppExtra then warn("[NEXRIFT] TopbarAppExtra Not Found") else local function bindHold(icon, key) local function attach() local btn = icon.Button or (icon.GetPart and icon:GetPart("Button")) if not btn then return false end btn.MouseButton1Down:Connect(function() ConfigState.currentHold[key] = true SendKeybindEvent(key, true) if icon.SetSelected then icon:SetSelected(true, true) end end) btn.MouseButton1Up:Connect(function() if ConfigState.currentHold[key] then ConfigState.currentHold[key] = false SendKeybindEvent(key, false) if icon.SetSelected then icon:SetSelected(false, true) end end end) btn.MouseLeave:Connect(function() if ConfigState.currentHold[key] then ConfigState.currentHold[key] = false SendKeybindEvent(key, false) if icon.SetSelected then icon:SetSelected(false, true) end end end) return true end if not attach() then local conn conn = TopbarAppExtra.Ready:Connect(function() if attach() and conn then conn:Disconnect() end end) task.spawn(function() for _ = 1, 40 do if attach() then if conn then conn:Disconnect() end return end task.wait(0.1) end end) end end for _, cfg in ipairs(ConfigState.keybindConfigs) do local icon = TopbarAppExtra.new(cfg.Name, { Image = cfg.Image, Order = cfg.Order, Tooltip = cfg.Tooltip, Toggleable = false, }) ConfigState.createdIcons[cfg.Name] = icon bindHold(icon, cfg.Key) end getgenv().NexriftTopbarIcons = ConfigState.createdIcons end end local UpdateCharacterDataRegistry = ReplicatedStorage.Remotes.Registry.UpdateCharacterDataRegistry local Character for _, v in pairs(Lighting:GetDescendants()) do if v:IsA("Atmosphere") then table.insert(ConfigState.originalAtmospheres, v) end end function EnableNoFog() ConfigState.originalFogEnd = Lighting.FogEnd Lighting.FogEnd = 1000000 for _, v in pairs(Lighting:GetDescendants()) do if v:IsA("Atmosphere") then v:Destroy() end end end function GetCharacterHorizontalSpeed(character) if not character then return 0 end local hrp = character:FindFirstChild("HumanoidRootPart") if not hrp then return 0 end for _, child in ipairs(hrp:GetChildren()) do if child:IsA("LinearVelocity") and child.Name:find("LinearVelocity") then local pv = child.PlaneVelocity return (pv.X * pv.X + pv.Y * pv.Y) ^ 0.5 end end local velocity = hrp.AssemblyLinearVelocity return (velocity.X * velocity.X + velocity.Z * velocity.Z) ^ 0.5 end function SetCharacterMovementValue(MovementType, value) if getconnections then if not CharacterTag then CharacterTag = GetCharacterTagAttribute(LocalPlayer.Character) end if CharacterTag then FireClient(ReplicatedStorage.Remotes.Character.CharacterTask, CharacterTag, "ModifyMovement", { MovementType, value }) else task.spawn(error, "Failed to overwrite movement data! Beacuse your character dose not have Attibute 'Tag'", 0) end else task.spawn(error, "Failed to Overwrite Movement Data! Beacuse your executor dose not support 'getconnections'", 0) end end ConfigState.originalRegistry = Movement.RegistryTermUpdated Movement.RegistryTermUpdated = function(self, term) if term == "Emote" then ConfigState.activeMovement = self local id = self.DataRegistry:Get("Emote") if id and id ~= 0 then local item = ClientItemService:GetItemFromID(id) local mult = item and (require(item).EmoteInfo or {}).SpeedMult or 1 if ConfigState.emoteSpeedEnabled and ConfigState.emoteSpeedType == "Blatant" then if ConfigState.applyUnwalkableEmoteSpeed and mult <= 0 then mult = 1 end self.MoveStats:SpeedChange("Emote", mult * (ConfigState.emoteSpeedValue / 1000)) else self.MoveStats:SpeedChange("Emote", mult) end else self.MoveStats:SpeedChange("Emote", nil) end return end ConfigState.originalRegistry(self, term) end ConfigState.originalMovementUpdate = Movement.Update Movement.Update = function(self, ...) ConfigState.originalMovementUpdate(self, ...) local humanoid = self.Character and self.Character:FindFirstChild("Humanoid") if not humanoid then return end if self.Character == Players.LocalPlayer.Character then ConfigState.activeMovement = self end local LocalPlayerData = CharacterService:GetCharacterFromPlayer(LocalPlayer) local movementData = LocalPlayerData and LocalPlayerData.Movement local state = movementData and movementData.State if not state then state = self.State end local grounded = self.DataRegistry:Get("Grounded") local desiredFriction = nil local isInfSlide = (state == "Slide" or state == "EmotingSlide" or state == "CarrySlide") local isEmoteSlideAccel = (state == "EmotingSlide") if isInfSlide then if ConfigState.infiniteSlide then desiredFriction = ConfigState.slideFriction end end if isEmoteSlideAccel then if ConfigState.emoteSpeedEnabled and ConfigState.emoteSpeedType == "Legit" then desiredFriction = ConfigState.emoteAccelerationValue end end if desiredFriction == nil and ConfigState.accelerationMethod == "Acceleration" then local isBhopActive = ConfigState.autoJumpEnabled or (ConfigState.bhopHoldEnabled and humanoid.Jump == true) if isBhopActive and not grounded then local currentSpeed = GetCharacterHorizontalSpeed(self.Character) if ConfigState.autoAccelerationEnabled then if currentSpeed > ConfigState.maxAutoAccelSpeed then desiredFriction = ConfigState.maxAcceleration elseif currentSpeed < ConfigState.maxAutoAccelSpeed then desiredFriction = ConfigState.minAcceleration else desiredFriction = ConfigState.accelerationValue end else desiredFriction = ConfigState.accelerationValue end end end if desiredFriction ~= ConfigState.lastFriction then if desiredFriction ~= nil then SetCharacterMovementValue("Friction", desiredFriction) else SetCharacterMovementValue("Friction", ConfigState.defaultMovementValues.Friction) end ConfigState.lastFriction = desiredFriction end if (state == "WallrunRight" or state == "WallrunLeft") and ConfigState.AutowallHop then self:AttemptJump() end if ConfigState.autoJumpEnabled and grounded then if ConfigState.autoJumpType == "Realistic" then self:AttemptJump() else humanoid:ChangeState(Enum.HumanoidStateType.Jumping) end end if ConfigState.bhopHoldEnabled and grounded and humanoid.Jump == true then self:AttemptJump() end end function SyncBhopMovementFlag() local shouldEnable = (ConfigState.autoJumpEnabled or ConfigState.bhopHoldEnabled) and ConfigState.accelerationMethod == "Acceleration" SetCharacterMovementValue("BhopEnabled", shouldEnable) end function SetInfiniteSlideEnabled(state) ConfigState.infiniteSlide = state end function RefreshEmoteSpeedMultiplier() if ConfigState.activeMovement then Movement.RegistryTermUpdated(ConfigState.activeMovement, "Emote") end end function SetAutoJumpEnabled(state) ConfigState.autoJumpEnabled = state SyncBhopMovementFlag() end function SetBhopHoldEnabled(state) ConfigState.bhopHoldEnabled = state SyncBhopMovementFlag() end function SetBhopAccelerationMethod(method) ConfigState.accelerationMethod = method SyncBhopMovementFlag() if not (ConfigState.autoJumpEnabled or ConfigState.bhopHoldEnabled) then SetCharacterMovementValue("Friction", ConfigState.defaultMovementValues.Friction) ConfigState.lastFriction = nil end end function GetStatus(player) local character = player.Character if not character then return "DEAD" end local charData = CharacterService:GetCharacterFromPlayer(player) if charData and charData.DataRegistry:Get("Downed") then return "DOWNED" end local humanoid = character:FindFirstChildOfClass("Humanoid") if humanoid and humanoid.Health > 0 then return "ALIVE" end return "DEAD" end function isPlayerDowned(player) return GetStatus(player) == "DOWNED" end function isReviveTargetDowned(model) if not model then return false end local plr = Players:GetPlayerFromCharacter(model) return (plr ~= nil and isPlayerDowned(plr)) or isModelDowned(model) end function isPlayerRagdolled(player) if not player or not player.Character then return false end local char = player.Character if char:FindFirstChild("RagdollConstraints") then return true end local charData = CharacterService:GetCharacterFromPlayer(player) if charData and charData.DataRegistry and charData.DataRegistry:Get("Ragdolling") then return true end if char.PrimaryPart and char.PrimaryPart.Anchored then return true end return false end function EnableAntiAFK() ConfigState.AntiAFKConnection = LocalPlayer.Idled:Connect(function() VirtualUser:Button2Down(Vector2.new(0, 0), workspace.CurrentCamera.CFrame) task.wait(1) VirtualUser:Button2Up(Vector2.new(0, 0), workspace.CurrentCamera.CFrame) end) end function DisableAntiAFK() if ConfigState.AntiAFKConnection then ConfigState.AntiAFKConnection:Disconnect() ConfigState.AntiAFKConnection = nil end end function DisableNoFog() Lighting.FogEnd = ConfigState.originalFogEnd for _, atmosphere in pairs(ConfigState.originalAtmospheres) do if not atmosphere.Parent then local newAtmosphere = Instance.new("Atmosphere") for _, prop in pairs({ "Density", "Offset", "Color", "Decay", "Glare", "Haze" }) do if atmosphere[prop] then newAtmosphere[prop] = atmosphere[prop] end end newAtmosphere.Parent = Lighting end end end if not workspace:FindFirstChild("SecurityPart") then SecurityPart = Instance.new("Part") SecurityPart.Name = "SecurityPart" SecurityPart.Size = Vector3.new(10, 1, 10) SecurityPart.Position = Vector3.new(50000, 50000, 50000) SecurityPart.Anchored = true SecurityPart.CanCollide = true SecurityPart.Parent = workspace end Tabs.Player:Section({ Title = "Player", TextSize = 40 }) Tabs.Player:Divider() Tabs.Player:Section({ Title = "Modify Bounce", TextSize = 20 }) BounceEnabled = Tabs.Player:Toggle({ Title = "Modify Multiplier", Flag = "BounceEnabled", Value = false, }) BounceEnabled.Callback = function(state) if ConfigState.bounceConnection then ConfigState.bounceConnection:Disconnect() ConfigState.bounceConnection = nil end if state then ConfigState.bounceConnection = game:GetService("RunService").RenderStepped:Connect(function() local char = LocalPlayer.Character if not char then return end local humanoid = char:FindFirstChild("Humanoid") if not humanoid then return end if humanoid.Health <= 0 then return end humanoid.WalkSpeed = ConfigState.BounceSpeed end) else local char = LocalPlayer.Character if char then local humanoid = char:FindFirstChild("Humanoid") if humanoid then humanoid.WalkSpeed = 0 end end end end VelocityMultiplier = Tabs.Player:Input({ Title = "Multiplier value", Flag = "VelocityMultiplier", Placeholder = "80", NumbersOnly = true, }) VelocityMultiplier.Callback = function(value) ConfigState.BounceSpeed = tonumber(value) or 0 end Tabs.Player:Section({ Title = "Supper Bounce", TextSize = 20 }) Tabs.Player:Divider() BounceInput = Tabs.Player:Input({ Title = "Bounce Height", Placeholder = "190", }) BounceInput.Callback = function(value) ConfigState.BounceHeight = tonumber(value) or 50 end function TriggerSuperBounce() if not LocalPlayer.Character then return end local humanoid = LocalPlayer.Character:FindFirstChild("Humanoid") local rootPart = LocalPlayer.Character:FindFirstChild("HumanoidRootPart") if humanoid and rootPart then humanoid:ChangeState(Enum.HumanoidStateType.Jumping) rootPart.Velocity = Vector3.new(rootPart.Velocity.X, ConfigState.BounceHeight, rootPart.Velocity.Z) end end SuperBounceToggle = Tabs.Player:Toggle({ Title = "Supper Bounce", Flag = "SuperBounceToggle", Value = false, }) SuperBounceToggle.Callback = function(state) ConfigState.SuperBounceEnabled = state end ShowUISupperBounceToggle = Tabs.Player:Toggle({ Title = "Show UI Supper Bounce", Flag = "ShowUISupperBounce", Value = false, }) ShowUISupperBounceToggle.Callback = function(state) if SuperBounceButton then SuperBounceButton:SetVisible(state) end end SuperBounceButton = ButtonLib.Create:Button({ Text = "Supper Bounce", Flag = "SuperBounce", Position = UDim2.new(0.5, - 125, 0.2, 0), Visible = false, Callback = function() TriggerSuperBounce() end }) if ButtonLib.SuperBounce then ButtonLib.SuperBounce:SetText("Supper Bounce") end Tabs.Player:Space() Character = nil Humanoid = nil function handleCharacterAdded(NewCharacter) Character = NewCharacter Humanoid = Character:WaitForChild("Humanoid") ConfigState.RootPart = Character:WaitForChild("HumanoidRootPart") ConfigState.LastPosition = ConfigState.RootPart.Position ConfigState.WasFalling = false ConfigState.EdgeDetected = false end Tabs.Player:Space() EdgeTrimpToggle = Tabs.Player:Toggle({ Title = "Modify Edge Trimp", Flag = "ModifyEdgeTrimp", Value = false, }) EdgeTrimpToggle.Callback = function(State) ConfigState.EdgeTrimpEnabled = State if State then if LocalPlayer.Character then handleCharacterAdded(LocalPlayer.Character) end ConfigState.charAddedConnection = LocalPlayer.CharacterAdded:Connect(handleCharacterAdded) ConfigState.edgeTrimpConnection = RunService.Heartbeat:Connect(function() if not (Character and Humanoid and ConfigState.RootPart) then return end local CurrentPosition = ConfigState.RootPart.Position local Velocity = (CurrentPosition - ConfigState.LastPosition) / RunService.Heartbeat:Wait() ConfigState.LastPosition = CurrentPosition local CurrentFloorMaterial = Humanoid.FloorMaterial local IsFalling = Humanoid:GetState() == Enum.HumanoidStateType.Freefall or Humanoid:GetState() == Enum.HumanoidStateType.Jumping if CurrentFloorMaterial ~= ConfigState.LastFloorMaterial and CurrentFloorMaterial == Enum.Material.Air and not IsFalling then ConfigState.EdgeDetected = true else ConfigState.EdgeDetected = false end if ConfigState.EdgeDetected and Humanoid:GetState() ~= Enum.HumanoidStateType.Freefall then local FallVelocity = Velocity.Y if FallVelocity < - ConfigState.FallSpeedThreshold then local BounceVelocity = math.abs(FallVelocity) * ConfigState.BounceMultiplier ConfigState.RootPart.Velocity = Vector3.new(ConfigState.RootPart.Velocity.X, BounceVelocity, ConfigState.RootPart.Velocity.Z) end end ConfigState.LastFloorMaterial = CurrentFloorMaterial ConfigState.WasFalling = IsFalling end) else if ConfigState.edgeTrimpConnection then ConfigState.edgeTrimpConnection:Disconnect() ConfigState.edgeTrimpConnection = nil end if ConfigState.charAddedConnection then ConfigState.charAddedConnection:Disconnect() ConfigState.charAddedConnection = nil end end end BounceMultiplierInput = Tabs.Player:Input({ Title = "Bounce Height Multiplier", Flag = "EdgeHeightMultiplier", Placeholder = "5", Value = tostring(ConfigState.BounceMultiplier), NumbersOnly = true, }) BounceMultiplierInput.Callback = function(Value) local Num = tonumber(Value) if Num and Num > 0 then ConfigState.BounceMultiplier = Num end end FallSpeedThresholdInput = Tabs.Player:Input({ Title = "Falling Threshold", Flag = "EdgeFallThreshold", Placeholder = "69", Value = tostring(ConfigState.FallSpeedThreshold), NumbersOnly = true, }) FallSpeedThresholdInput.Callback = function(Value) local Num = tonumber(Value) if Num and Num > 0 then ConfigState.FallSpeedThreshold = Num end end ConfigState.fly_speed = ConfigState.fly_speed or 1.5 ConfigState.originalFlyMovementUpdate = Movement.Update function GetFlyMoveDirection() local camCF = Workspace.CurrentCamera.CFrame local moveVector = ControlModule:GetMoveVector() if moveVector.Magnitude < 0.01 then return Vector3.new(0, 0, 0) end local forward = camCF.LookVector local right = camCF.RightVector return (forward * - moveVector.Z + right * moveVector.X).Unit * 100 * ConfigState.fly_speed end function FlyMovementUpdate(self, dt) ConfigState.originalFlyMovementUpdate(self, dt) local hrp = self.Character and self.Character:FindFirstChild("HumanoidRootPart") if not hrp then return end local flyDir = GetFlyMoveDirection() if flyDir.Magnitude > 0.1 then ConfigState.freezeY = nil elseif not ConfigState.freezeY then ConfigState.freezeY = hrp.Position.Y end local newVel = flyDir self.DataRegistry:Set("Velocity", newVel * 90) hrp.AssemblyLinearVelocity = newVel if ConfigState.freezeY and flyDir.Magnitude <= 0.1 then local pos = hrp.Position hrp.CFrame = CFrame.new(pos.X, ConfigState.freezeY, pos.Z) * (hrp.CFrame - hrp.CFrame.Position) end end function EnableFly() if ConfigState.flying then return end ConfigState.flying = true ConfigState.freezeY = nil Movement.Update = FlyMovementUpdate end function DisableFly() if not ConfigState.flying then return end ConfigState.flying = false ConfigState.freezeY = nil Movement.Update = ConfigState.originalFlyMovementUpdate end Tabs.Player:Space() FlyToggle = Tabs.Player:Toggle({ Title = "Fly", Flag = "FlyToggle", Value = false, }) FlyToggle.Callback = function(state) if state then EnableFly() else DisableFly() end end ShowFlyButtonToggle = Tabs.Player:Toggle({ Title = "Show UI Flight", Flag = "ShowFlyButton", Value = false, }) ShowFlyButtonToggle.Callback = function(state) if ButtonLib and ButtonLib.Flight then ButtonLib.Flight:SetVisible(state) end end FlightButton = ButtonLib.Create:Toggle({ Text = "Flight", Flag = "Flight", Default = false, Visible = false, Callback = function(s) if FlyToggle then FlyToggle:Set(s) end end }) if ButtonLib.Flight then ButtonLib.Flight:SetText("Flight") end FlightButton.Position = UDim2.new(0.5, - 125, 0.4, 0) FlySpeedInput = Tabs.Player:Input({ Title = "Fly Speed", Flag = "FlySpeedInput", Placeholder = "Enter speed value", Value = ConfigState.fly_speed, NumbersOnly = true, }) FlySpeedInput.Callback = function(value) local speed = tonumber(value) if speed and speed > 0 then ConfigState.fly_speed = speed end end Tabs.Player:Space() InfiniteSlideToggle = Tabs.Player:Toggle({ Title = "Infinite Slide", Flag = "InfiniteSlideToggle", Value = false, }) InfiniteSlideToggle.Callback = function(v) SetInfiniteSlideEnabled(v) end ShowInfSlideButton = Tabs.Player:Toggle({ Title = "Show UI Inf Slide", }) ShowInfSlideButton.Callback = function(b) InfButton:SetVisible(b) end InfButton = ButtonLib.Create:Toggle({ Text = "Inf Slide", Flag = "InfSlide", Default = false, Visible = false, Callback = function(s) InfiniteSlideToggle:Set(s) end }) SlideFrictionInput = Tabs.Player:Input({ Title = "Slide Friction (Negative Only)", Flag = "SlideFrictionInput", Placeholder = "-8", NumbersOnly = false, Value = "-8", }) SlideFrictionInput.Callback = function(v) local n = tonumber(v) if n then ConfigState.slideFriction = n end end function hookWallImpact() if ConfigState.originalWallImpact then return true end local mod = MoveFunctionHelpers if type(mod) ~= "table" or type(mod.WallImpact) ~= "function" then return false end local prev = mod.WallImpact local ok = pcall(function() if setreadonly then setreadonly(mod, false) end mod.WallImpact = function(_, _, _, _, _, _, velocity) return velocity end end) if not ok or mod.WallImpact == prev then ConfigState.wallHelpers, ConfigState.originalWallImpact = nil, nil return false end ConfigState.wallHelpers, ConfigState.originalWallImpact = mod, prev return true end Tabs.Player:Space() noclipCFrame = Tabs.Player:Toggle({ Title = "Noclip", Desc = "Walk through walls (disables the game's wall check)", Flag = "noclipCFrame", Value = false, }) noclipCFrame.Callback = function(state) ConfigState.noclipEnabled = state if state then if ConfigState.noclipConnection then ConfigState.noclipConnection:Disconnect() ConfigState.noclipConnection = nil end local hooked = hookWallImpact() if not hooked then WindUI:Notify({ Title = "Noclip", Content = "Wall check module not found", Duration = 3 }) end local char = LocalPlayer.Character local hrp = char and char:FindFirstChild("HumanoidRootPart") if hrp then hrp.CanCollide = false end ConfigState.noclipConnection = LocalPlayer.CharacterAdded:Connect(function() task.wait(0.1) if ConfigState.noclipEnabled then local newChar = LocalPlayer.Character local newHrp = newChar and newChar:FindFirstChild("HumanoidRootPart") if newHrp then newHrp.CanCollide = false end end end) else if ConfigState.noclipConnection then ConfigState.noclipConnection:Disconnect() ConfigState.noclipConnection = nil end if ConfigState.wallHelpers and ConfigState.originalWallImpact then pcall(function() ConfigState.wallHelpers.WallImpact = ConfigState.originalWallImpact end) end ConfigState.wallHelpers, ConfigState.originalWallImpact = nil, nil local char = LocalPlayer.Character local hrp = char and char:FindFirstChild("HumanoidRootPart") if hrp then hrp.CanCollide = true end end end Tabs.Player:Space() ConfigState.rampBoostMultiplier = ConfigState.rampBoostMultiplier or 2 function StopRampBooster() if ConfigState.rampBoostConnection then ConfigState.rampBoostConnection:Disconnect() ConfigState.rampBoostConnection = nil end end function StartRampBooster() StopRampBooster() local armed = true ConfigState.rampBoostConnection = RunService.Heartbeat:Connect(function(dt) local character = LocalPlayer.Character local humanoid = character and character:FindFirstChildOfClass("Humanoid") local root = humanoid and (humanoid.RootPart or character.PrimaryPart) if not root then return end local velocity = root.AssemblyLinearVelocity local vy = velocity.Y local gravity = workspace.Gravity local jumpSpeed = humanoid.UseJumpPower and humanoid.JumpPower or math.sqrt(2 * gravity * humanoid.JumpHeight) local limit = jumpSpeed + gravity * dt if not armed and vy <= 0 then armed = true end if armed and vy > limit then armed = false root.AssemblyLinearVelocity = Vector3.new(velocity.X, vy * ConfigState.rampBoostMultiplier, velocity.Z) end end) end RampBoosterToggle = Tabs.Player:Toggle({ Title = "RampBooster", Desc = "Multiplies your upward speed when a ramp launches you", Flag = "RampBoosterToggle", Value = false, }) RampBoosterToggle.Callback = function(state) if state then StartRampBooster() else StopRampBooster() end end RampBoosterMultiplierInput = Tabs.Player:Input({ Title = "Ramp Booster Multiplier", Flag = "RampBoosterMultiplierInput", Placeholder = "2", NumbersOnly = false, Value = "2", }) RampBoosterMultiplierInput.Callback = function(v) local n = tonumber(v) if n and n > 0 then ConfigState.rampBoostMultiplier = n end end Tabs.Player:Space() WalkOnWaterToggle = Tabs.Player:Toggle({ Title = "Walk On Water", Flag = "WalkOnWater", Value = false, }) WalkOnWaterToggle.Callback = function(state) local partsFolder = workspace:FindFirstChild("Map") and workspace.Map:FindFirstChild("Parts") if not partsFolder then return end local waterFolder = partsFolder:FindFirstChild("Water") if not waterFolder then return end local fakeWaterFolder = partsFolder:FindFirstChild("FakeWater") if not fakeWaterFolder then fakeWaterFolder = Instance.new("Folder") fakeWaterFolder.Name = "FakeWater" fakeWaterFolder.Parent = partsFolder end if state then if ConfigState.waterRenderConnection then ConfigState.waterRenderConnection:Disconnect() end ConfigState.waterRenderConnection = game:GetService("RunService").RenderStepped:Connect(function() for _, part in ipairs(waterFolder:GetChildren()) do if part:IsA("BasePart") and part.Parent ~= fakeWaterFolder then part.CanCollide = true part.Parent = fakeWaterFolder end end end) else if ConfigState.waterRenderConnection then ConfigState.waterRenderConnection:Disconnect() ConfigState.waterRenderConnection = nil end for _, part in ipairs(fakeWaterFolder:GetChildren()) do if part:IsA("BasePart") then part.CanCollide = false part.Parent = waterFolder end end end end Tabs.Player:Space() function EnableTeleportWalk() if ConfigState.tpwalkConnection then ConfigState.tpwalkConnection:Disconnect() ConfigState.tpwalkConnection = nil end ConfigState.tpwalkEnabled = true ConfigState.tpwalkConnection = RunService.RenderStepped:Connect(function() local v282 = 10 if not ConfigState.tpwalkEnabled then return end local char = LocalPlayer.Character if not char then return end local hrp = char:FindFirstChild("HumanoidRootPart") local humanoid = char:FindFirstChild("Humanoid") if not hrp or not humanoid then return end local moveDir = humanoid.MoveDirection if moveDir.Magnitude > 0 then local speed = ConfigState.TpwalkValue hrp.AssemblyLinearVelocity = Vector3.new( moveDir.X * v282 * speed, hrp.AssemblyLinearVelocity.Y, moveDir.Z * v282 * speed) end end) end function DisableTeleportWalk() ConfigState.tpwalkEnabled = false if ConfigState.tpwalkConnection then ConfigState.tpwalkConnection:Disconnect() ConfigState.tpwalkConnection = nil end local char = LocalPlayer.Character if char then local hrp = char:FindFirstChild("HumanoidRootPart") if hrp then hrp.AssemblyLinearVelocity = Vector3.new(0, hrp.AssemblyLinearVelocity.Y, 0) end end end TPWALKToggle = Tabs.Player:Toggle({ Title = "Teleport Walk", Flag = "TPWALKToggle", Value = false, }) TPWALKToggle.Callback = function(state) if state then EnableTeleportWalk() else DisableTeleportWalk() end end TPWALKSlider = Tabs.Player:Slider({ Title = "Teleport Walk Value", Flag = "TPWALKSlider", Desc = "Adjust Teleport Walk speed", Value = { Min = 1, Max = 200, Default = 1, Step = 1 }, }) TPWALKSlider.Callback = function(value) ConfigState.TpwalkValue = value end LocalPlayer.CharacterAdded:Connect(function() if ConfigState.tpwalkEnabled then task.wait(0.5) EnableTeleportWalk() end end) Tabs.Player:Section({ Title = "Modification" }) BaseSpeedInput = Tabs.Player:Input({ Title = "Speed", Placeholder = tostring(ConfigState.defaultMovementValues.Speed), NumbersOnly = true, Value = tostring(ConfigState.defaultMovementValues.Speed) }) BaseSpeedInput.Callback = function(value) SetCharacterMovementValue("Speed", tonumber(value)) end Tabs.Player:Space() JumpHeightInput = Tabs.Player:Input({ Title = "Jump height", Placeholder = tostring(ConfigState.defaultMovementValues.JumpHeight), NumbersOnly = true, Value = tostring(ConfigState.defaultMovementValues.JumpHeight) }) JumpHeightInput.Callback = function(value) SetCharacterMovementValue("JumpHeight", tonumber(value)) end JumpCapInput = Tabs.Player:Input({ Title = "Jump Cap", Placeholder = tostring(ConfigState.defaultMovementValues.JumpCap), NumbersOnly = true, Value = tostring(ConfigState.defaultMovementValues.JumpCap) }) JumpCapInput.Callback = function(value) SetCharacterMovementValue("JumpCap", tonumber(value)) end JumpSpeedMultiplierInput = Tabs.Player:Input({ Title = "Jump Speed Multiplier", Placeholder = tostring(ConfigState.defaultMovementValues.JumpSpeedMultiplier), NumbersOnly = true, Value = tostring(ConfigState.defaultMovementValues.JumpSpeedMultiplier) }) JumpSpeedMultiplierInput.Callback = function(value) SetCharacterMovementValue("JumpSpeedMultiplier", tonumber(value)) end Tabs.Player:Space() AirStrafeAccelerationInput = Tabs.Player:Input({ Title = "Air Strafe Acceleration", Placeholder = tostring(ConfigState.defaultMovementValues.AirStrafeAcceleration), NumbersOnly = true, Value = tostring(ConfigState.defaultMovementValues.AirStrafeAcceleration) }) AirStrafeAccelerationInput.Callback = function(value) SetCharacterMovementValue("AirStrafeAcceleration", tonumber(value)) end AirAccelerationInput = Tabs.Player:Input({ Title = "Air Acceleration", Placeholder = tostring(ConfigState.defaultMovementValues.AirAcceleration), NumbersOnly = true, Value = tostring(ConfigState.defaultMovementValues.AirAcceleration) }) AirAccelerationInput.Callback = function(value) SetCharacterMovementValue("AirAcceleration", tonumber(value)) end Tabs.Player:Space() SprintCapInput = Tabs.Player:Input({ Title = "Sprint Cap", Placeholder = tostring(ConfigState.defaultMovementValues.SprintCap), NumbersOnly = true, Value = tostring(ConfigState.defaultMovementValues.SprintCap) }) SprintCapInput.Callback = function(value) SetCharacterMovementValue("SprintCap", tonumber(value)) end SprintAccelerationInput = Tabs.Player:Input({ Title = "Sprint Acceleration", Placeholder = tostring(ConfigState.defaultMovementValues.SprintAcceleration), NumbersOnly = true, Value = tostring(ConfigState.defaultMovementValues.SprintAcceleration) }) SprintAccelerationInput.Callback = function(value) SetCharacterMovementValue("SprintAcceleration", tonumber(value)) end Tabs.Player:Space() RunAccelInput = Tabs.Player:Input({ Title = "Run Acceleration", Placeholder = tostring(ConfigState.defaultMovementValues.RunAccel), NumbersOnly = true, Value = tostring(ConfigState.defaultMovementValues.RunAccel) }) RunAccelInput.Callback = function(value) SetCharacterMovementValue("RunAccel", tonumber(value)) end RunDeaccelInput = Tabs.Player:Input({ Title = "Run Deacceleration", Placeholder = tostring(ConfigState.defaultMovementValues.RunDeaccel), NumbersOnly = true, Value = tostring(ConfigState.defaultMovementValues.RunDeaccel) }) RunDeaccelInput.Callback = function(value) SetCharacterMovementValue("RunDeaccel", tonumber(value)) end FrictionInput = Tabs.Player:Input({ Title = "Friction", Placeholder = tostring(ConfigState.defaultMovementValues.Friction), NumbersOnly = true, Value = tostring(ConfigState.defaultMovementValues.Friction) }) FrictionInput.Callback = function(value) SetCharacterMovementValue("Friction", tonumber(value)) end Tabs.Player:Space() WalkSpeedMultiplierInput = Tabs.Player:Input({ Title = "Walk Speed Multiplier", Placeholder = tostring(ConfigState.defaultMovementValues.WalkSpeedMultiplier), NumbersOnly = true, Value = tostring(ConfigState.defaultMovementValues.WalkSpeedMultiplier) }) WalkSpeedMultiplierInput.Callback = function(value) SetCharacterMovementValue("WalkSpeedMultiplier", tonumber(value)) end GroundedDistCheckInput = Tabs.Player:Input({ Title = "Grounded Distance Check", Placeholder = tostring(ConfigState.defaultMovementValues.GroundedDistCheck), NumbersOnly = true, Value = tostring(ConfigState.defaultMovementValues.GroundedDistCheck) }) GroundedDistCheckInput.Callback = function(value) SetCharacterMovementValue("GroundedDistCheck", tonumber(value)) end Tabs.Player:Section({ Title = "Emote Speed" }) EmoteSpeedToggle = Tabs.Player:Toggle({ Title = "Enable Emote Speed", Flag = "EmoteSpeedToggle", Value = false, }) EmoteSpeedToggle.Callback = function(v) ConfigState.emoteSpeedEnabled = v RefreshEmoteSpeedMultiplier() end EmoteSpeedType = Tabs.Player:Dropdown({ Title = "Emote Speed Type", Flag = "EmoteSpeedType", Values = { "Blatant", "Legit" }, Value = "Blatant", Callback = function(value) ConfigState.emoteSpeedType = value RefreshEmoteSpeedMultiplier() end }) EmoteSpeedInput = Tabs.Player:Input({ Title = "Emote Speed Value", Flag = "EmoteSpeedInput", Placeholder = "1000", NumbersOnly = true, Value = "1000", }) EmoteSpeedInput.Callback = function(v) ConfigState.emoteSpeedValue = tonumber(v) or 1000 RefreshEmoteSpeedMultiplier() end ApplyUnwalkableEmoteSpeedToggle = Tabs.Player:Toggle({ Title = "Apply Unwalkable Emote Speed", Flag = "ApplyUnwalkableEmoteSpeed", Type = "Checkbox", Value = false, }) ApplyUnwalkableEmoteSpeedToggle.Callback = function(v) ConfigState.applyUnwalkableEmoteSpeed = v RefreshEmoteSpeedMultiplier() end EmoteAccelerationInput = Tabs.Player:Input({ Title = "Emote Acceleration (Negative Only)", Flag = "EmoteAccelerationInput", Desc = "Negative Only", Placeholder = "-2", NumbersOnly = true, Value = "-2", }) EmoteAccelerationInput.Callback = function(v) ConfigState.emoteAccelerationValue = tonumber(v) or - 2 end ResetEmoteSpeedButton = Tabs.Player:Button({ Title = "Reset Emote Speed", Desc = "Having Trouble? reset the speed or rejoin", Callback = function() ConfigState.emoteSpeedValue = 1000 ConfigState.emoteAccelerationValue = - 2 ConfigState.emoteSpeedType = "Blatant" if EmoteSpeedInput then EmoteSpeedInput:Set("1000") end if EmoteAccelerationInput then EmoteAccelerationInput:Set("-2") end if EmoteSpeedType then EmoteSpeedType:Select("Blatant") end RefreshEmoteSpeedMultiplier() end }) function PerkNotify(text) WindUI:Notify({ Title = "Spawn Perk", Content = text, Duration = 3 }) end function PerkAddEntry(names, title, term, id) local state = ConfigState.Perk if id and not state.IDs[title] then state.IDs[title] = id state.Terms[title] = term table.insert(names, title) end end function PerkAddModule(names, module) if not module:IsA("ModuleScript") or not module.Parent or module.Parent.Name ~= "Perks" then return end local ok, data = pcall(require, module) if ok and type(data) == "table" and data.EquipInfo and data.EquipInfo.SlotType == "Perk" then local title = data.AppearanceInfo and data.AppearanceInfo.Name or module.Name PerkAddEntry(names, title, "Perks", module:GetAttribute("ID")) end end function PerkAddAction(names, module) if not module:IsA("ModuleScript") then return end local ok, data = pcall(require, module) local label = ok and type(data) == "table" and data.Name local title = "[Action] " .. module.Name if label and label ~= module.Name then title = title .. " (" .. label .. ")" end PerkAddEntry(names, title, "Actions", module:GetAttribute("ID")) end function PerkBuildList() local state = ConfigState.Perk local names = {} table.clear(state.IDs) table.clear(state.Terms) for _, module in pairs(ClientItemService.Names) do PerkAddModule(names, module) end if # names == 0 then for _, module in ipairs(ReplicatedStorage.Items:GetDescendants()) do PerkAddModule(names, module) end end local actions = ReplicatedStorage.Objects.Game.Actions:FindFirstChild("ActionTypes") for _, module in ipairs(actions and actions:GetChildren() or {}) do PerkAddAction(names, module) end table.sort(names) return names end function PerkMerge(term, list) local merged = {} local present = {} for _, id in ipairs(list) do table.insert(merged, id) present[id] = true end for _, id in ipairs(ConfigState.Perk.Spawned[term]) do if not present[id] then table.insert(merged, id) present[id] = true end end return merged end function PerkSetTermHook(self, term, value) local state = ConfigState.Perk if not state.Internal and state.Spawned[term] and type(value) == "table" and self.Parent and self.Parent.Local then state.Real[term] = table.clone(value) value = PerkMerge(term, value) end return state.OriginalSetTerm(self, term, value) end function PerkInstallHook() local state = ConfigState.Perk if state.Hooked then return true end local ok, module = pcall(require, ReplicatedStorage.Objects.Game.Character.DataRegistry) if not ok or type(module) ~= "table" or type(module.SetTerm) ~= "function" then return false end state.Module = module state.OriginalSetTerm = module.SetTerm module.SetTerm = PerkSetTermHook state.Hooked = true return true end function PerkDropActions(character) local holder = character.Actions local real = ConfigState.Perk.Real.Actions if not holder or not holder.Actions or not real then return end for index = # holder.Actions, # real + 1, - 1 do local object = table.remove(holder.Actions, index) pcall(object.Destroy, object) end end function PerkWrite(character, term, list) local state = ConfigState.Perk state.Internal = true character.DataRegistry:SetTerm(term, list) state.Internal = false local movement = character.Movement if term == "Perks" and movement and movement.MoveStats then pcall(movement.MoveStats.Reset, movement.MoveStats) end end function PerkRelease() local state = ConfigState.Perk if # state.Spawned.Perks + # state.Spawned.Actions + # state.Spawned.Tools > 0 then return end if state.Hooked and state.Module and state.Module.SetTerm == PerkSetTermHook then state.Module.SetTerm = state.OriginalSetTerm end state.Hooked = false end function PerkApply() local state = ConfigState.Perk local character = CharacterService:GetLocalCharacter() if not character or not character.DataRegistry then PerkNotify("No character yet, spawn first") return end for _, term in ipairs(state.Order) do table.clear(state.Spawned[term]) end for _, title in ipairs(state.Selected) do local id = state.IDs[title] local term = state.Terms[title] if id and term then table.insert(state.Spawned[term], id) end end if # state.Spawned.Perks + # state.Spawned.Actions == 0 and not state.Real.Perks and not state.Real.Actions then PerkNotify("Pick at least one perk or action first") return end local hooked = PerkInstallHook() for _, term in ipairs(state.Order) do if # state.Spawned[term] > 0 or state.Real[term] then state.Real[term] = state.Real[term] or table.clone(character.DataRegistry:Get(term) or {}) if term == "Actions" then PerkDropActions(character) end PerkWrite(character, term, PerkMerge(term, state.Real[term])) end end PerkNotify("Spawned " .. # state.Spawned.Perks .. " perk(s) and " .. # state.Spawned.Actions .. " action(s)" .. (hooked and "" or ", hook failed so a respawn will drop them")) end function PerkReset() local state = ConfigState.Perk for _, term in ipairs(state.Order) do table.clear(state.Spawned[term]) end local character = CharacterService:GetLocalCharacter() if character and character.DataRegistry then PerkDropActions(character) for _, term in ipairs(state.Order) do if state.Real[term] then PerkWrite(character, term, table.clone(state.Real[term])) end end end for _, term in ipairs(state.Order) do state.Real[term] = nil end PerkRelease() PerkNotify("Perks and actions back to normal") end function PerkPicked(values) ConfigState.Perk.Selected = table.clone(values) end Tabs.Player:Section({ Title = "Spawn Perk", TextSize = 20 }) Tabs.Player:Divider() SpawnPerkDropdown = Tabs.Player:Dropdown({ Title = "Perks and Actions", Desc = "Pick perks or [Action] types to spawn on yourself", Flag = "SpawnPerkDropdown", Values = PerkBuildList(), Value = {}, Multi = true, AllowNone = true, Callback = PerkPicked }) Tabs.Player:Button({ Title = "Apply Perks", Desc = "Client side, reward and revive perks are server checked", Icon = "check", Callback = PerkApply }) Tabs.Player:Button({ Title = "Reset Perks", Icon = "rotate-ccw", Callback = PerkReset }) Tabs.Player:Space() function ToolModsEachMethod(info, callback) for _, taskInfo in ipairs(info.Tasks or {}) do for _, functionInfo in ipairs(taskInfo.Functions or {}) do for _, activation in ipairs(functionInfo.Activations or {}) do for _, method in ipairs(activation.Methods or {}) do callback(method, taskInfo) end end end for _, functionInfo in ipairs(taskInfo.AutomaticFunctions or {}) do for _, method in ipairs(functionInfo.Methods or {}) do callback(method, taskInfo) end end end end function ToolModsSetKeys(data, keys, valueFn) if type(data) ~= "table" then return end for key, value in pairs(data) do if keys[key] and type(value) == "number" then data[key] = valueFn(key, value) elseif type(value) == "table" then ToolModsSetKeys(value, keys, valueFn) end end end ConfigState.ToolMods.InfoPatchers = { Ammo = function(info) for _, taskInfo in ipairs(info.Tasks or {}) do local resourceInfo = taskInfo.ResourceInfo if resourceInfo and resourceInfo.Type == "Clip" then resourceInfo.Reserve = ConfigState.ToolModBig resourceInfo.Cap = ConfigState.ToolModBig if resourceInfo.MaxReserve ~= nil then resourceInfo.MaxReserve = ConfigState.ToolModBig end end end end, NoDelay = function(info) ToolModsEachMethod(info, function(method) if type(method.Info) == "table" then ToolModsSetKeys(method.Info, {Cooldown = true}, function() return 1 / 65536 end) end end) end, Spread = function(info) for _, taskInfo in ipairs(info.Tasks or {}) do for _, reference in pairs(taskInfo.MethodReferences or {}) do local spreadInfo = type(reference) == "table" and type(reference.Info) == "table" and reference.Info.SpreadInfo if type(spreadInfo) == "table" then spreadInfo.MaxSpread = 0 spreadInfo.MinSpread = 0 end end end end, Range = function(info) ToolModsEachMethod(info, function(method) if type(method.Info) ~= "table" then return end ToolModsSetKeys(method.Info, {Range = true, LungeRange = true, HearingRange = true}, function() return math.huge end) local interval = method.Info.DamageDistanceInterval if type(interval) == "table" and # interval >= 2 then interval[2] = math.huge end end) end } ConfigState.ToolMods.LivePatchers = { Ammo = function(tool) for _, taskObject in ipairs(tool.Tasks and tool.Tasks.Tasks or {}) do local clip = taskObject.Resource and taskObject.Resource.Resource if type(clip) == "table" and clip.Cap ~= nil and clip.Ammo ~= nil then clip.Cap = ConfigState.ToolModBig clip.Reserve = ConfigState.ToolModBig clip.MaxReserve = ConfigState.ToolModBig clip.Ammo = ConfigState.ToolModBig end end end, Spread = function(tool) for _, taskObject in ipairs(tool.Tasks and tool.Tasks.Tasks or {}) do for _, reference in ipairs(taskObject.Methods or {}) do local spread = reference.Spread if type(spread) == "table" then spread.Min = 0 spread.Max = 0 spread.Value = 0 end end end end } function ToolModsPatchTool(tool) if type(tool) ~= "table" or type(tool.Info) ~= "table" then return end for kind in pairs(ConfigState.ToolMods.Active) do local infoPatcher = ConfigState.ToolMods.InfoPatchers[kind] if infoPatcher then pcall(infoPatcher, tool.Info) end local livePatcher = ConfigState.ToolMods.LivePatchers[kind] if livePatcher then pcall(livePatcher, tool) end end end function ToolModsGetLiveTools() local list = {} local okService, ToolService = pcall(require, ReplicatedStorage.Services.Asset.ToolService) if okService and type(ToolService) == "table" and type(ToolService.Profiles) == "table" then for _, profile in ipairs(ToolService.Profiles) do local isMine = profile.Player == LocalPlayer or (profile.Character ~= nil and profile.Character == LocalPlayer.Character) if isMine then for _, tool in ipairs(profile.Tools or {}) do table.insert(list, tool) end end end end return list end function ToolModsInstallHook() if ConfigState.ToolMods.Hooked then return true end local okClass, ToolClass = pcall(require, ReplicatedStorage.Objects.Game.Tool) if not okClass or type(ToolClass) ~= "table" or type(ToolClass.Init) ~= "function" then return false end local originalInit = ToolClass.Init ConfigState.ToolMods.OriginalInit = originalInit ConfigState.ToolMods.ToolClass = ToolClass ToolClass.Init = function(self, ...) local results = table.pack(originalInit(self, ...)) pcall(ToolModsPatchTool, self) return table.unpack(results, 1, results.n) end ConfigState.ToolMods.Hooked = true return true end function ToolModsUnhook() if ConfigState.ToolMods.Hooked and ConfigState.ToolMods.ToolClass and ConfigState.ToolMods.ToolClass.Init ~= ConfigState.ToolMods.OriginalInit then ConfigState.ToolMods.ToolClass.Init = ConfigState.ToolMods.OriginalInit end ConfigState.ToolMods.Hooked = false ConfigState.ToolMods.Active = {} end function ToolModsEnable(kind) ConfigState.ToolMods.Active[kind] = true local hooked = ToolModsInstallHook() local patched = 0 for _, tool in ipairs(ToolModsGetLiveTools()) do ToolModsPatchTool(tool) patched = patched + 1 end if not hooked then local infoPatcher = ConfigState.ToolMods.InfoPatchers[kind] for _, tool in ipairs(ReplicatedStorage.Tools:GetChildren()) do if tool:IsA("ModuleScript") then local okModule, data = pcall(require, tool) if okModule and type(data) == "table" and infoPatcher then pcall(infoPatcher, data) end end end end WindUI:Notify({ Title = "Tool Modifier", Content = kind .. " applied to " .. patched .. " tool(s)" .. (hooked and ", new tools get it too" or " (hook failed, only works next spawn)"), Duration = 3 }) end Tabs.Combat:Button({ Title = "Visual Infinite Ammo", Callback = function() ToolModsEnable("Ammo") end }) Tabs.Combat:Space() Tabs.Combat:Button({ Title = "Visual No Tool Delay", Callback = function() ToolModsEnable("NoDelay") end }) Tabs.Combat:Space() Tabs.Combat:Button({ Title = "Disable Weapon Spread", Callback = function() ToolModsEnable("Spread") end }) Tabs.Combat:Space() function DefibGetProfile() local character = CharacterService:GetLocalCharacter() if character and character.ToolProfile and character.Model then return character.ToolProfile, character end end function DefibFindTool(profile) for index, tool in pairs(profile.Tools or {}) do if tool.Module and tool.Module.Name == "Defibrillator" then return index, tool end end end function DefibFindReviveMethod(tool) local info = tool.Info for _, taskInfo in ipairs(info and info.Tasks or {}) do for _, func in ipairs(taskInfo.Functions or {}) do for _, activation in ipairs(func.Activations or {}) do for _, method in ipairs(activation.Methods or {}) do if method.VisualName == "Revive" and not method.Ignore then return method end end end end end end function DefibFindTarget(localCharacter, localRoot) local myTag = localCharacter.Model:GetAttribute("Tag") local range = ConfigState.defibrillator.AuraRange local bestModel, bestDistance for _, other in pairs(CharacterService:GetCharacters()) do local model = other.Model local root = model and model.PrimaryPart local registry = other.DataRegistry if other ~= localCharacter and root and registry and registry:Get("Downed") and (registry:Get("Carried") or 0) == 0 then local humanoid = model:FindFirstChild("Humanoid") local queue = registry:Get("ReviveQueue") or {} if humanoid and humanoid.Health <= 0 and not (queue[1] and queue[1] ~= myTag) and model:GetAttribute("Tag") then local distance = (root.Position - localRoot.Position).Magnitude if range == "inf" or (type(range) == "number" and distance <= range) then if not bestDistance or distance < bestDistance then bestModel = model bestDistance = distance end end end end end return bestModel end function DefibRestore(profile) local state = ConfigState.defibrillator if state.UsedEquip and profile then local _, tool = DefibFindTool(profile) local current = profile:GetCurrentTool() if tool and current == tool and state.PreviousKeybind then pcall(profile.AttemptEquip, profile, state.PreviousKeybind) end end state.UsedEquip = false state.PreviousKeybind = nil state.NoTargetSince = nil end function DefibStep() local state = ConfigState.defibrillator local profile, character = DefibGetProfile() if not profile then return end local localRoot = character.Model.PrimaryPart if not localRoot or character.DataRegistry:Get("Downed") then return end local target = DefibFindTarget(character, localRoot) if not target then state.NoTargetSince = state.NoTargetSince or tick() if tick() - state.NoTargetSince > 0.6 then DefibRestore(profile) end return end state.NoTargetSince = nil local index, tool = DefibFindTool(profile) if not tool then if not state.WarnedMissing then state.WarnedMissing = true WindUI:Notify({ Title = "Defibrillator Aura", Content = "No Defibrillator in your loadout, put it in a slot first (needs to be owned too)", Duration = 4 }) end return end if profile.DataRegistry:Get("Equipped") ~= index then if tick() - state.LastEquipTry < 0.8 then return end local current = profile:GetCurrentTool() if current and current ~= tool then state.PreviousKeybind = current.Keybind end if state.EquipDelay > 0 then task.wait(state.EquipDelay) end state.LastEquipTry = tick() state.UsedEquip = true pcall(profile.AttemptEquip, profile, tool.Keybind) return end if tick() - state.LastFire < state.Cooldown or tool.Tasks and tool.Tasks.Unequipping then return end if state.ReviveDelay > 0 then task.wait(state.ReviveDelay) if not target.Parent or profile.DataRegistry:Get("Equipped") ~= index then return end end local indexBuffer local method = DefibFindReviveMethod(tool) if method and tool.Tasks then local okBuffer, result = pcall(tool.Tasks.GetIndexBufferFromMethod, tool.Tasks, method) if okBuffer then indexBuffer = result end end indexBuffer = indexBuffer or buffer.fromstring("\1\1\1\1") state.LastFire = tick() ToolAction:FireServer(indexBuffer, target:GetAttribute("Tag")) end function StopReviveAura() local state = ConfigState.defibrillator state.AuraEnabled = false if state.Loop then state.Loop:Disconnect() state.Loop = nil end DefibRestore(DefibGetProfile()) end function StartReviveAura() local state = ConfigState.defibrillator if state.Loop then StopReviveAura() end state.AuraEnabled = true state.WarnedMissing = false state.LastFire = 0 state.Loop = HeartbeatLoop(0.1, DefibStep) end DefibrillatorAura = Tabs.Combat:Toggle({ Title = "Defibrillator Aura", Desc = "Auto Token Bug closest downed player", Value = false, }) DefibrillatorAura.Callback = function(state) if state then StartReviveAura() else StopReviveAura() end end AuraRange_2 = Tabs.Combat:Input({ Title = "Aura Range", Placeholder = "20 or inf", Value = "20", }) AuraRange_2.Callback = function(value) if value == "inf" then ConfigState.defibrillator.AuraRange = "inf" else local num = tonumber(value) if num then ConfigState.defibrillator.AuraRange = num end end end EquipDelaySeconds = Tabs.Combat:Input({ Title = "Equip Delay (seconds)", Value = "0", }) EquipDelaySeconds.Callback = function(value) ConfigState.defibrillator.EquipDelay = tonumber(value) or 0 end ReviveDelaySeconds = Tabs.Combat:Input({ Title = "Revive Delay (seconds)", Value = "0", }) ReviveDelaySeconds.Callback = function(value) ConfigState.defibrillator.ReviveDelay = tonumber(value) or 0 end Tabs.Combat:Space() Tabs.Combat:Button({ Title = "Infinite Range", Callback = function() ToolModsEnable("Range") end }) Tabs.Combat:Space() Tabs.Combat:Button({ Title = "Portal bypass", Callback = function() Portal.IsPortalPossible = function(...) return true end end }) Tabs.Combat:Space() Tabs.Combat:Button({ Title = "Build Offset Multiplier", Value = false, Callback = function(state) local oldGetClientPosition = BuildModule.GetClientPosition BuildModule.GetClientPosition = function(self, ...) local valid, cframe = oldGetClientPosition(self, ...) if cframe then cframe = cframe * CFrame.new(getgenv().BuildOffsetX, getgenv().BuildOffsetY, getgenv().BuildOffsetZ) end return valid, cframe end end }) OffsetX = Tabs.Combat:Input({ Title = "Offset X", Value = "0", Placeholder = "0", NumbersOnly = true, }) OffsetX.Callback = function(v) getgenv().BuildOffsetX = tonumber(v) or 0 end OffsetY = Tabs.Combat:Input({ Title = "Offset Y", Value = "0", Placeholder = "0", NumbersOnly = true, }) OffsetY.Callback = function(v) getgenv().BuildOffsetY = tonumber(v) or 0 end OffsetZ = Tabs.Combat:Input({ Title = "Offset Z", Value = "0", Placeholder = "0", NumbersOnly = true, }) OffsetZ.Callback = function(v) getgenv().BuildOffsetZ = tonumber(v) or 0 end Tabs.Combat:Space() Tabs.Combat:Button({ Title = "Bypass \\\"TooMany\\\" Consumables item limit", Callback = function() for i = 1, 4 do local a = PlayerGui:FindFirstChild("Shared") if a then a = a:FindFirstChild("HUD") end if a then a = a:FindFirstChild("Interactors") end if a then a = a:FindFirstChild("Popups") end if a then a = a:FindFirstChild("Usables") end if a then a = a:FindFirstChild("Wheel") end if a then local b = a:FindFirstChild("Item" .. i) if b then b = b:FindFirstChild("Icon") end if b then b = b:FindFirstChild("TooMany") end if b then b:Destroy() end end end for i = 1, 4 do local a = ReplicatedStorage:FindFirstChild("Assets") if a then a = a:FindFirstChild("UI") end if a then a = a:FindFirstChild("Game") end if a then a = a:FindFirstChild("HUD") end if a then a = a:FindFirstChild("Interactors") end if a then a = a:FindFirstChild("Popups") end if a then a = a:FindFirstChild("Usables") end if a then a = a:FindFirstChild("Wheel") end if a then local b = a:FindFirstChild("Item" .. i) if b then b = b:FindFirstChild("Icon") end if b then b = b:FindFirstChild("TooMany") end if b then b:Destroy() end end end end }) Tabs.Combat:Space() function GetAimbotTargetPart(model) if not model then return nil end if ConfigState.aimPartName == "Head" then return model:FindFirstChild("Head") or model:FindFirstChild("HumanoidRootPart") end return model:FindFirstChild("HumanoidRootPart") or model:FindFirstChild("Torso") or model:FindFirstChild("UpperTorso") end function IsAimbotTargetVisible(part) if not ConfigState.aimWallCheck then return true end local camera = workspace.CurrentCamera if not camera then return false end local params = RaycastParams.new() params.FilterType = Enum.RaycastFilterType.Exclude params.FilterDescendantsInstances = { LocalPlayer.Character, part.Parent } local origin = camera.CFrame.Position return workspace:Raycast(origin, part.Position - origin, params) == nil end function CollectAimbotTargetModels() local models = {} if table.find(ConfigState.aimTargetTypes, "Player") then for _, player in ipairs(Players:GetPlayers()) do local char = player.Character local hum = char and char:FindFirstChildOfClass("Humanoid") if player ~= LocalPlayer and hum and hum.Health > 0 and not isPlayerDowned(player) then table.insert(models, char) end end end if table.find(ConfigState.aimTargetTypes, "NPC") then for _, model in ipairs(getNPCs()) do table.insert(models, model) end end return models end function FindClosestAimbotTarget() local camera = workspace.CurrentCamera local myChar = LocalPlayer.Character local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart") if not camera or not myRoot then return nil end local center = Vector2.new(camera.ViewportSize.X / 2, camera.ViewportSize.Y / 2) local best, bestDistance = nil, ConfigState.aimFOV for _, model in ipairs(CollectAimbotTargetModels()) do local part = GetAimbotTargetPart(model) if part and (part.Position - myRoot.Position).Magnitude <= ConfigState.aimMaxDistance then local screen, onScreen = camera:WorldToViewportPoint(part.Position) if onScreen then local distance = (Vector2.new(screen.X, screen.Y) - center).Magnitude if distance < bestDistance and IsAimbotTargetVisible(part) then best, bestDistance = part, distance end end end end return best end function InstallAimbotCameraHook() if ConfigState.cameraInputHooked then return true end local originalGetRotation = CameraInput.getRotation CameraInput.getRotation = function(...) local rotation = originalGetRotation(...) local camera = workspace.CurrentCamera if not (ConfigState.aimbotEnabled and ConfigState.aimTarget and ConfigState.aimTarget.Parent and camera) then return rotation end local factor = math.clamp(1 - (ConfigState.aimSmoothness / 20), 0.001, 1) local cf = camera.CFrame local direction = (ConfigState.aimTarget.Position - cf.Position).Unit local localDir = cf:VectorToObjectSpace(direction) local yaw = math.atan2(localDir.X, - localDir.Z) local pitch = math.asin(math.clamp(direction.Y, - 1, 1)) - math.asin(math.clamp(cf.LookVector.Y, - 1, 1)) return rotation + Vector2.new(yaw * factor, - pitch * factor) end ConfigState.cameraInputHooked = true return true end function UpdateAimbotFOVCircle() if ConfigState.aimCircle then ConfigState.aimCircle.Visible = ConfigState.aimShowFOV and ConfigState.aimbotEnabled ConfigState.aimCircle.Radius = ConfigState.aimFOV ConfigState.aimCircle.Color = ConfigState.aimFOVColor end end function EnableAimbot() if ConfigState.aimRenderConnection then return end if not InstallAimbotCameraHook() then WindUI:Notify({ Title = "Aimbot", Content = "Camera module not found", Duration = 4 }) return end ConfigState.aimbotEnabled = true if Drawing and not ConfigState.aimCircle then ConfigState.aimCircle = Drawing.new("Circle") ConfigState.aimCircle.Filled = false ConfigState.aimCircle.NumSides = 60 ConfigState.aimCircle.Thickness = 2 end UpdateAimbotFOVCircle() ConfigState.aimRenderConnection = RunService.RenderStepped:Connect(function() local camera = workspace.CurrentCamera if ConfigState.aimCircle and camera then ConfigState.aimCircle.Position = Vector2.new(camera.ViewportSize.X / 2, camera.ViewportSize.Y / 2) end local now = os.clock() if now - ConfigState.aimLastScan >= 0.05 then ConfigState.aimLastScan = now ConfigState.aimTarget = FindClosestAimbotTarget() end end) end function DisableAimbot() ConfigState.aimbotEnabled = false ConfigState.aimTarget = nil if ConfigState.aimRenderConnection then ConfigState.aimRenderConnection:Disconnect() ConfigState.aimRenderConnection = nil end if ConfigState.aimCircle then ConfigState.aimCircle:Remove() ConfigState.aimCircle = nil end end function KillAuraFindMeleeEnd(taskInfo) for _, func in ipairs(taskInfo.AutomaticFunctions or {}) do for _, method in ipairs(func.Methods or {}) do if method.ActivationType == "End" and type(method.Info) == "table" then return method end end end end function KillAuraGetPlan(tool) local cache = ConfigState.KillAura.Cache local cached = cache[tool] if cached ~= nil then return cached or nil end local plan = false for _, taskInfo in ipairs(tool.Info and tool.Info.Tasks or {}) do local references = taskInfo.MethodReferences or {} for _, func in ipairs(taskInfo.Functions or {}) do for _, activation in ipairs(func.Activations or {}) do for _, method in ipairs(activation.Methods or {}) do local reference = references[method.MethodReferencing] local kind = type(reference) == "table" and reference.Type if not plan and not method.Ignore and type(method.Info) == "table" then if kind == "Bullet" and activation.ActivationRequirement == "Down" then plan = { Kind = "Bullet", Method = method } elseif kind == "Melee" and method.ActivationType == "Start" then local finish = KillAuraFindMeleeEnd(taskInfo) if finish then plan = { Kind = "Melee", Method = method, Finish = finish } end end end end end end end cache[tool] = plan return plan or nil end function KillAuraHasAmmo(tool, plan) if plan.Kind ~= "Bullet" then return true end for _, taskObject in ipairs(tool.Tasks and tool.Tasks.Tasks or {}) do local clip = taskObject.Resource and taskObject.Resource.Resource if type(clip) == "table" and type(clip.Ammo) == "number" then return clip.Ammo > 0 end end return true end function KillAuraModeAllows(kind) local mode = ConfigState.KillAura.Mode return mode == "Both" or (mode == "Melee" and kind == "Melee") or (mode == "Gun" and kind == "Bullet") end function KillAuraReach(plan) local state = ConfigState.KillAura if plan.Kind == "Melee" then local range = plan.Finish.Info.Range or plan.Method.Info.Range or 6 return math.min(state.Range, range + 4, 25) end return math.min(state.Range, plan.Method.Info.Range or 400) end function KillAuraValidTarget(model, target) local humanoid = target:FindFirstChildOfClass("Humanoid") if target == model or not humanoid or not target.PrimaryPart or humanoid.Health <= 0 or not target:GetAttribute("Tag") then return false end local team = target:GetAttribute("Team") if team == "Decoys" or team == "Menu" then return false end return not (ConfigState.KillAura.TeamCheck and team ~= nil and team == model:GetAttribute("Team")) end function KillAuraHasSight(model, target) local map = workspace:FindFirstChild("Map") local parts = map and map:FindFirstChild("Parts") if not parts then return true end local rootPart = model:FindFirstChild("HumanoidRootPart") local headPos = rootPart and rootPart:FindFirstChild("HeadPos") local origin = headPos and headPos.WorldPosition or model.PrimaryPart.Position local params = RaycastParams.new() params.FilterType = Enum.RaycastFilterType.Include params.FilterDescendantsInstances = {parts, workspace.Terrain} params.IgnoreWater = true return workspace:Raycast(origin, target.PrimaryPart.Position - origin, params) == nil end function KillAuraFindTarget(model, root, reach, needSight) local folder = workspace:FindFirstChild("Players") if not folder then return nil end local best, bestDistance for _, target in ipairs(folder:GetChildren()) do if target:IsA("Model") and KillAuraValidTarget(model, target) then local distance = (target.PrimaryPart.Position - root.Position).Magnitude if distance <= reach and (not bestDistance or distance < bestDistance) and (not needSight or KillAuraHasSight(model, target)) then best = target bestDistance = distance end end end return best end function KillAuraChoose(profile, model, root) local equipped = profile.DataRegistry:Get("Equipped") local bestIndex, bestTool, bestPlan, bestTarget for index, tool in pairs(profile.Tools or {}) do local plan = KillAuraGetPlan(tool) if plan and KillAuraModeAllows(plan.Kind) and KillAuraHasAmmo(tool, plan) then local target = KillAuraFindTarget(model, root, KillAuraReach(plan), plan.Kind == "Bullet") if target and (not bestTool or index == equipped) then bestIndex = index bestTool = tool bestPlan = plan bestTarget = target end end end return bestIndex, bestTool, bestPlan, bestTarget end function KillAuraBuffer(tool, method) local ok, result = pcall(tool.Tasks.GetIndexBufferFromMethod, tool.Tasks, method) if ok then return result end end function KillAuraRestore(profile) local state = ConfigState.KillAura if state.UsedEquip and profile and state.PreviousKeybind then pcall(profile.AttemptEquip, profile, state.PreviousKeybind) end state.UsedEquip = false state.PreviousKeybind = nil state.NoTargetSince = nil end function KillAuraAttack(tool, plan, target, root, now) local state = ConfigState.KillAura local buffer = KillAuraBuffer(tool, plan.Method) if not buffer then return end local info = plan.Method.Info if plan.Kind == "Bullet" then local part = target:FindFirstChild("Head") or target.PrimaryPart local normal = (root.Position - part.Position).Unit local hits = {} for index = 1, info.Bullets or 1 do hits[index] = {target:GetAttribute("Tag"), part.Position, normal, 0, part.Name} end ToolAction:FireServer(buffer, hits) state.NextAttackAt = now + (info.Cooldown or 0.2) + 0.03 return end ToolAction:FireServer(buffer, {}) state.SwingTarget = target:GetAttribute("Tag") state.SwingTool = tool state.SwingPlan = plan state.SwingEndAt = now + math.max(0.05, (info.Cooldown or 0.3) * 0.8 - 0.1) + 0.05 end function KillAuraFinish(root, now) local state = ConfigState.KillAura local tag = state.SwingTarget local tool = state.SwingTool local plan = state.SwingPlan state.SwingTarget = nil state.SwingTool = nil state.SwingPlan = nil local buffer = tool and plan and KillAuraBuffer(tool, plan.Finish) if not buffer then return end local ok, character = pcall(CharacterService.GetCharacterFromTag, CharacterService, tag) local targetRoot = ok and character and character.Model and character.Model.PrimaryPart local position = targetRoot and targetRoot.Position local normal = position and (root.Position - position).Unit ToolAction:FireServer(buffer, {tag, position, normal, 0}) state.NextAttackAt = now + (plan.Finish.Info.Cooldown or 0.6) + 0.05 end function KillAuraStep() local state = ConfigState.KillAura local profile, character = DefibGetProfile() if not profile then return end local model = character.Model local root = model.PrimaryPart if not root or character.DataRegistry:Get("Downed") then return end local now = os.clock() if state.SwingTarget then if now >= state.SwingEndAt then KillAuraFinish(root, now) end return end if now < state.NextAttackAt then return end local index, tool, plan, target = KillAuraChoose(profile, model, root) if not target then state.NoTargetSince = state.NoTargetSince or now if now - state.NoTargetSince > 0.6 then KillAuraRestore(profile) end return end state.NoTargetSince = nil if profile.DataRegistry:Get("Equipped") ~= index then if now - state.LastEquipTry < 0.8 then return end local current = profile:GetCurrentTool() if current and not state.UsedEquip then state.PreviousKeybind = current.Keybind end state.LastEquipTry = now state.UsedEquip = true pcall(profile.AttemptEquip, profile, tool.Keybind) return end if tool.Tasks and tool.Tasks.Unequipping then return end KillAuraAttack(tool, plan, target, root, now) end function KillAuraStop() local state = ConfigState.KillAura state.Enabled = false if state.Loop then state.Loop:Disconnect() state.Loop = nil end state.SwingTarget = nil state.SwingTool = nil state.SwingPlan = nil KillAuraRestore(DefibGetProfile()) end function KillAuraStart() local state = ConfigState.KillAura if state.Loop then KillAuraStop() end state.Enabled = true state.NextAttackAt = 0 state.Loop = HeartbeatLoop(0.05, KillAuraStep) end function KillAuraToggled(state) if state then KillAuraStart() else KillAuraStop() end end function KillAuraToggleKey() KillAuraToggle:Set(not KillAuraToggle.Value) end function KillAuraTeamChanged(state) ConfigState.KillAura.TeamCheck = state end function KillAuraModeChanged(value) ConfigState.KillAura.Mode = value end function KillAuraRangeChanged(value) local number = tonumber(value) if number and number > 0 then ConfigState.KillAura.Range = number end end Tabs.Combat:Section({ Title = "Kill Aura", TextSize = 20 }) Tabs.Combat:Divider() KillAuraToggle = Tabs.Combat:Toggle({ Title = "Kill Aura (Gun / Melee)", Desc = "Experimental. Hits players and NPCs in range with your loadout weapons", Flag = "KillAuraToggle", Value = false, Callback = KillAuraToggled }) KillAuraTeamCheck = Tabs.Combat:Toggle({ Title = "Team Check", Desc = "Skip anyone on your own Team attribute", Flag = "KillAuraTeamCheck", Type = "Checkbox", Value = true, Callback = KillAuraTeamChanged }) KillAuraModeDropdown = Tabs.Combat:Dropdown({ Title = "Kill Aura Weapons", Flag = "KillAuraMode", Values = { "Both", "Melee", "Gun" }, Value = "Both", Callback = KillAuraModeChanged }) KillAuraRangeInput = Tabs.Combat:Input({ Title = "Kill Aura Range", Desc = "Melee gets capped by the weapon's real reach", Placeholder = "60", Value = "60", Callback = KillAuraRangeChanged }) Tabs.Combat:Space() function GrappleHookNotify(text) WindUI:Notify({ Title = "Grapple Hook", Content = text, Duration = 3 }) end function GrappleHookParseValue(text) local lowered = string.lower(text) if lowered == "true" then return true, true elseif lowered == "false" then return false, true elseif lowered == "inf" then return math.huge, true end local number = tonumber(text) if number then return number, true end local x, y, z = string.match(text, "^%s*(-?[%d%.]+)%s*,%s*(-?[%d%.]+)%s*,%s*(-?[%d%.]+)%s*$") if x then return Vector3.new(tonumber(x), tonumber(y), tonumber(z)), true end if text == "" or lowered == "nil" then return nil, false end return text, true end function GrappleHookSetInfoKey(data, key, value) local mod = ConfigState.GrappleMod local saved = mod.Saved[data] if not saved then saved = {} mod.Saved[data] = saved end if saved[key] == nil then saved[key] = {data[key]} end data[key] = value end function GrappleHookPatchInfo(info) local mod = ConfigState.GrappleMod if not mod.Enabled then return end ToolModsEachMethod(info, GrappleHookPatchMethod) end function GrappleHookPatchMethod(method) local mod = ConfigState.GrappleMod local data = method.Info if type(data) ~= "table" or data.Projectile ~= "Grapple" then return end for key, value in pairs(mod.Overrides) do GrappleHookSetInfoKey(data, key, value) end end function GrappleHookPatchImpulse(data) local mod = ConfigState.GrappleMod if not mod.Enabled or type(data) ~= "table" then return end local name = data.Projectile if typeof(name) == "Instance" then name = name.Name end if name ~= "Grapple" or data.Creator ~= LocalPlayer.Character then return end for key, value in pairs(mod.Overrides) do data[key] = value end if mod.Range > 0 and mod.Range ~= mod.DefaultRange and mod.Overrides.Lifetime == nil and type(data.Speed) == "number" and data.Speed > 0 then data.Lifetime = mod.Range / data.Speed end end function GrappleHookNew(data, ...) pcall(GrappleHookPatchImpulse, data) return ConfigState.GrappleMod.OriginalNew(data, ...) end function GrappleHookInstall() local mod = ConfigState.GrappleMod if mod.Hooked then return true end local ok, module = pcall(require, ReplicatedStorage.Services.Shared.GenericImpulse.Types.Assets.Projectile) if not ok or type(module) ~= "table" or type(module.new) ~= "function" then return false end mod.Module = module mod.OriginalNew = module.new module.new = GrappleHookNew mod.Hooked = true return true end function GrappleHookRestoreInfo() local mod = ConfigState.GrappleMod for data, saved in pairs(mod.Saved) do for key, box in pairs(saved) do data[key] = box[1] end end table.clear(mod.Saved) end function GrappleHookApplyInfo() for _, tool in ipairs(ToolModsGetLiveTools()) do if type(tool.Info) == "table" then pcall(GrappleHookPatchInfo, tool.Info) end end end function GrappleHookDisable() local mod = ConfigState.GrappleMod mod.Enabled = false ConfigState.ToolMods.Active.Grapple = nil GrappleHookRestoreInfo() if mod.Hooked and mod.Module and mod.Module.new == GrappleHookNew then mod.Module.new = mod.OriginalNew end mod.Hooked = false end function GrappleHookValueText(value) if typeof(value) == "Vector3" then return value.X .. ", " .. value.Y .. ", " .. value.Z end return tostring(value) end function GrappleHookCollectMethod(method) local mod = ConfigState.GrappleMod local data = method.Info if type(data) ~= "table" or data.Projectile ~= "Grapple" then return end for key, value in pairs(data) do if mod.Defaults[key] == nil then mod.Defaults[key] = value table.insert(mod.Keys, key) end end end function GrappleHookCollectDefaults() local mod = ConfigState.GrappleMod for _, toolName in ipairs({"GrappleHook", "GrappleShot"}) do local ok, info = pcall(require, ReplicatedStorage.Tools:FindFirstChild(toolName)) if ok and type(info) == "table" then ToolModsEachMethod(info, GrappleHookCollectMethod) end end if # mod.Keys == 0 then mod.Defaults = { Projectile = "Grapple", Gravity = Vector3.new(0, -6, 0), Speed = 470, Lifetime = 0.12, Cooldown = 1.8, SpreadIncrease = 2.5 } for key in pairs(mod.Defaults) do table.insert(mod.Keys, key) end end table.sort(mod.Keys) local speed, lifetime = mod.Defaults.Speed, mod.Defaults.Lifetime if type(speed) == "number" and type(lifetime) == "number" then mod.DefaultRange = math.floor(speed * lifetime * 10 + 0.5) / 10 end mod.Range = mod.DefaultRange end function GrappleHookRangeChanged(value) local number = tonumber(value) if number and number >= 0 then ConfigState.GrappleMod.Range = number end end function GrappleHookMakeCallback(key) return function(value) ConfigState.GrappleMod.Texts[key] = value end end function GrappleHookApply() local mod = ConfigState.GrappleMod table.clear(mod.Overrides) local count = 0 for _, key in ipairs(mod.Keys) do local text = mod.Texts[key] if text ~= nil and text ~= GrappleHookValueText(mod.Defaults[key]) then local value, keep = GrappleHookParseValue(text) if keep then mod.Overrides[key] = value count = count + 1 end end end if mod.Range > 0 and mod.Range ~= mod.DefaultRange then count = count + 1 end mod.Enabled = true local hooked = GrappleHookInstall() ConfigState.ToolMods.InfoPatchers.Grapple = GrappleHookPatchInfo ConfigState.ToolMods.Active.Grapple = true ToolModsInstallHook() GrappleHookRestoreInfo() GrappleHookApplyInfo() if hooked then GrappleHookNotify("Applied " .. count .. " change(s), fire the hook again") else GrappleHookNotify("Could not hook the projectile module, range and speed changes will not apply") end end function GrappleHookReset() local mod = ConfigState.GrappleMod GrappleHookDisable() table.clear(mod.Overrides) table.clear(mod.Texts) mod.Range = mod.DefaultRange mod.Inputs.Range:Set(tostring(mod.DefaultRange)) for _, key in ipairs(mod.Keys) do mod.Inputs[key]:Set(GrappleHookValueText(mod.Defaults[key])) end GrappleHookNotify("Grapple hook back to default") end GrappleHookCollectDefaults() Tabs.Combat:Section({ Title = "Grapple Hook", TextSize = 20 }) Tabs.Combat:Divider() ConfigState.GrappleMod.Inputs.Range = Tabs.Combat:Input({ Title = "Range (studs)", Desc = "How far the hook flies, default is speed x lifetime", Value = tostring(ConfigState.GrappleMod.DefaultRange), Callback = GrappleHookRangeChanged }) for _, key in ipairs(ConfigState.GrappleMod.Keys) do ConfigState.GrappleMod.Inputs[key] = Tabs.Combat:Input({ Title = key, Desc = "Default: " .. GrappleHookValueText(ConfigState.GrappleMod.Defaults[key]), Value = GrappleHookValueText(ConfigState.GrappleMod.Defaults[key]), Callback = GrappleHookMakeCallback(key) }) end Tabs.Combat:Button({ Title = "Apply", Icon = "check", Callback = GrappleHookApply }) Tabs.Combat:Button({ Title = "Reset", Icon = "rotate-ccw", Callback = GrappleHookReset }) Tabs.Combat:Space() function ToolSpawnBuildList() local names = {} table.clear(ConfigState.Perk.ToolIDs) for _, module in ipairs(ReplicatedStorage.Tools:GetChildren()) do local id = module:IsA("ModuleScript") and module:GetAttribute("ID") if id then ConfigState.Perk.ToolIDs[module.Name] = id table.insert(names, module.Name) end end table.sort(names) return names end function ToolSpawnPicked(values) ConfigState.Perk.ToolSelected = table.clone(values) end function ToolSpawnApply() local state = ConfigState.Perk local character = CharacterService:GetLocalCharacter() if not character or not character.DataRegistry then PerkNotify("No character yet, spawn first") return end table.clear(state.Spawned.Tools) for _, name in ipairs(state.ToolSelected) do table.insert(state.Spawned.Tools, state.ToolIDs[name]) end if # state.Spawned.Tools == 0 and not state.Real.Tools then PerkNotify("Pick at least one tool first") return end local hooked = PerkInstallHook() state.Real.Tools = state.Real.Tools or table.clone(character.DataRegistry:Get("Tools") or {}) PerkWrite(character, "Tools", PerkMerge("Tools", state.Real.Tools)) PerkNotify("Spawned " .. # state.Spawned.Tools .. " tool(s) in your hotbar, visual only" .. (hooked and "" or ", hook failed so a respawn will drop them")) end function ToolSpawnReset() local state = ConfigState.Perk table.clear(state.Spawned.Tools) local character = CharacterService:GetLocalCharacter() if character and character.DataRegistry and state.Real.Tools then PerkWrite(character, "Tools", table.clone(state.Real.Tools)) end state.Real.Tools = nil PerkRelease() PerkNotify("Hotbar back to normal") end Tabs.Combat:Section({ Title = "Tool Spawner", TextSize = 20 }) Tabs.Combat:Divider() ToolSpawnDropdown = Tabs.Combat:Dropdown({ Title = "Tools", Desc = "Pick tools to put in your hotbar", Flag = "ToolSpawnDropdown", Values = ToolSpawnBuildList(), Value = {}, Multi = true, AllowNone = true, SearchBarEnabled = true, Callback = ToolSpawnPicked }) Tabs.Combat:Button({ Title = "Spawn Tools", Desc = "Visual only, the server does not know about them", Icon = "check", Callback = ToolSpawnApply }) Tabs.Combat:Button({ Title = "Reset Tools", Icon = "rotate-ccw", Callback = ToolSpawnReset }) Tabs.Combat:Space() Tabs.Combat:Section({ Title = "Aimbot", TextSize = 20 }) Tabs.Combat:Divider() AimbotToggle = Tabs.Combat:Toggle({ Title = "Aimbot", Desc = "Turns your camera toward the closest target inside the FOV circle", Flag = "AimbotToggle", Value = false, }) AimbotToggle.Callback = function(state) if state then EnableAimbot() else DisableAimbot() end end Tabs.Combat:Dropdown({ Title = "Target Type", Flag = "AimbotTargetType", Values = { "Player", "NPC" }, Value = { "Player" }, Multi = true, AllowNone = true, Callback = function(values) ConfigState.aimTargetTypes = values end }) Tabs.Combat:Dropdown({ Title = "Aim Part", Flag = "AimbotAimPart", Values = { "Head", "Body" }, Value = "Head", Callback = function(value) ConfigState.aimPartName = value end }) AimbotSmoothness = Tabs.Combat:Slider({ Title = "Smoothness", Flag = "AimbotSmoothness", Desc = "Higher = smoother, lower = snappier", Step = 0.01, Value = { Min = 0.01, Max = 20, Default = 10 }, }) AimbotSmoothness.Callback = function(value) ConfigState.aimSmoothness = value end AimbotFOV = Tabs.Combat:Slider({ Title = "FOV Radius", Flag = "AimbotFOV", Step = 5, Value = { Min = 10, Max = 500, Default = 150 }, }) AimbotFOV.Callback = function(value) ConfigState.aimFOV = value UpdateAimbotFOVCircle() end AimbotMaxDistance = Tabs.Combat:Input({ Title = "Max Distance", Flag = "AimbotMaxDistance", Value = "500", Placeholder = "Enter max distance", }) AimbotMaxDistance.Callback = function(value) local n = tonumber(value) if n then ConfigState.aimMaxDistance = n end end AimbotWallCheck = Tabs.Combat:Toggle({ Title = "Wall Check", Flag = "AimbotWallCheck", Type = "Checkbox", Value = false, }) AimbotWallCheck.Callback = function(state) ConfigState.aimWallCheck = state end AimbotShowFOV = Tabs.Combat:Toggle({ Title = "Show FOV Circle", Flag = "AimbotShowFOV", Type = "Checkbox", Value = false, }) AimbotShowFOV.Callback = function(state) ConfigState.aimShowFOV = state UpdateAimbotFOVCircle() end Tabs.Combat:Colorpicker({ Title = "FOV Color", Flag = "AimbotFOVColor", Default = Color3.fromRGB(0, 255, 0), Callback = function(color) ConfigState.aimFOVColor = color UpdateAimbotFOVCircle() end }) Tabs.Combat:Space() Tabs.Combat:Section({ Title = "Deployment", TextSize = 20 }) Tabs.Combat:Divider() local okDS, DeployableService = pcall(function() return require(ReplicatedStorage.Services.Items.DeployableService) end) if not okDS or type(DeployableService) ~= "table" then DeployableService = nil end local deployCharacterTask = ReplicatedStorage.Remotes.Character:FindFirstChild("CharacterTask") function DeployFindHammerRange() local hammerRange = 8 local tools = ReplicatedStorage:FindFirstChild("Tools") local hammer = tools and tools:FindFirstChild("Hammer") local okH, data = pcall(require, hammer) if okH and type(data) == "table" then local found local function walk(t, visited, depth) if found or visited[t] or depth > 10 then return end visited[t] = true for k, v in pairs(t) do if k == "Range" and type(v) == "number" and v > 0 and v < 100 then found = v return elseif type(v) == "table" then walk(v, visited, depth + 1) end end end walk(data, {}, 0) if found then hammerRange = found end end return hammerRange end local deployHammerRange = DeployFindHammerRange() function DeployLocalProfile() local ok, me = pcall(function() return CharacterService:GetLocalCharacter() end) if ok and me and me.ToolProfile then return me.ToolProfile end return nil end function DeployCurrentToolName(profile) local ok, tool = pcall(function() return profile:GetCurrentTool() end) if ok and tool and tool.Module then return tool.Module.Name end return nil end function DeployFindHammerTool(profile) local ok, tools = pcall(function() return profile.Tools end) if not ok or type(tools) ~= "table" then return nil end for _, t in pairs(tools) do if type(t) == "table" and t.Module and t.Module.Name == "Hammer" then return t end end return nil end function DeployFindHammerMethod(tool) local fallback local ok, info = pcall(function() return tool.Info.Tasks end) if not ok or type(info) ~= "table" then return nil end for _, task_ in ipairs(info) do for _, fn in ipairs(task_.Functions or {}) do local primary = fn.Keybinds and table.find(fn.Keybinds, "Primary") ~= nil for _, act in ipairs(fn.Activations or {}) do for _, m in ipairs(act.Methods or {}) do if primary and act.ActivationRequirement == "Down" then return m end fallback = fallback or m end end end end return fallback end function DeployPickTarget(hrp) local best, bestDist, bestPart for _, d in ipairs(DeployableService.Deployables) do local model = d.Model local part = model and model.Parent and model.PrimaryPart if part then local eligible = false if d.Building then eligible = ConfigState.deployState.autoSpeedUp and d.Owner == LocalPlayer.Name elseif d.UsesLeft and d.MaxUses and d.UsesLeft < d.MaxUses then eligible = ConfigState.deployState.autoRepair end if eligible then local dist = ((part.Position - hrp.Position) * Vector3.new(1, 0.5, 1)).Magnitude if not bestDist or dist < bestDist then best, bestDist, bestPart = d, dist, part end end end end return best, bestDist, bestPart end function DeployHammerStep() local char = LocalPlayer.Character local hrp = char and char:FindFirstChild("HumanoidRootPart") local hum = char and char:FindFirstChildOfClass("Humanoid") local profile = DeployLocalProfile() if not (hrp and hum and hum.Health > 0 and profile) then return end local target, dist, part = DeployPickTarget(hrp) if not target then if ConfigState.deployLastHammer > 0 and os.clock() - ConfigState.deployLastHammer > 1.3 then ConfigState.deployLastHammer = 0 if DeployCurrentToolName(profile) == "Hammer" then pcall(function() profile:AttemptEquip("Weaponless") end) end end return end if dist > deployHammerRange then return end if DeployCurrentToolName(profile) ~= "Hammer" then pcall(function() profile:AttemptEquip("Hammer", 0) end) for _ = 1, 17 do if DeployCurrentToolName(profile) == "Hammer" then break end task.wait(0.03) end if DeployCurrentToolName(profile) ~= "Hammer" then return end end local tool = DeployFindHammerTool(profile) local method = tool and DeployFindHammerMethod(tool) if not method then return end local okBuf, buf = pcall(function() return tool.Tasks:GetIndexBufferFromMethod(method) end) if not okBuf or not buf or target.Tag == nil then return end pcall(function() ToolAction:FireServer(buf, { target.Tag, CFrame.new(part.Position), true }) end) ConfigState.deployLastHammer = os.clock() end if DeployableService then for _, d in ipairs(DeployableService.Deployables) do ConfigState.deployFirstSeen[d] = - math.huge end end function DeployBuildSeconds(d) local ok, v = pcall(function() return d.BuildTime or d.Config.DeployableInfo.BuildTime end) if ok and type(v) == "number" then return v end return 0 end function DeployIsPending(d, now) if ConfigState.deployFirstSeen[d] == nil then ConfigState.deployFirstSeen[d] = d.Building and now or - math.huge end return d.Building or now - ConfigState.deployFirstSeen[d] < DeployBuildSeconds(d) end function DeployKind(d) local model = d.Model local holder = model and model.Parent if not holder then return nil end local name = holder.Name:lower() if name:find("jump") then return "jump" elseif name:find("speed") then return "speed" elseif name:find("teleport") then return "teleport" end return nil end function DeployInsideBox(bb, pos, padXZ, padY) local rel = bb.CFrame:PointToObjectSpace(pos) local half = bb.Size / 2 return math.abs(rel.X) <= half.X + padXZ and math.abs(rel.Y) <= half.Y + padY and math.abs(rel.Z) <= half.Z + padXZ end function DeployEmitCharacterTask(...) if not getconnections or not deployCharacterTask then return end for _, c in ipairs(getconnections(deployCharacterTask.OnClientEvent)) do local fn = c.Function if fn then task.spawn(pcall, fn, ...) end end end function DeployUsableStep() local char = LocalPlayer.Character local hrp = char and char:FindFirstChild("HumanoidRootPart") if not hrp then return end local now = os.clock() for _, d in ipairs(DeployableService.Deployables) do local kind = DeployKind(d) if kind and DeployIsPending(d, now) then local bb = d.Model.Parent:FindFirstChild("BoundingBox") if bb and bb:IsA("BasePart") then if kind == "jump" then if now - (ConfigState.deployLastUse[d] or 0) > 1.6 and DeployInsideBox(bb, hrp.Position, 1, 3) then ConfigState.deployLastUse[d] = now pcall(function() d:Use(char) end) end elseif kind == "speed" then if now - (ConfigState.deployLastUse[d] or 0) > 5 and (hrp.Position - (bb.Position + Vector3.new(0, 2, 0))).Magnitude <= 5 then local tag = char:GetAttribute("Tag") if tag ~= nil then local settings = type(d.Settings) == "table" and d.Settings or {} ConfigState.deployLastUse[d] = now DeployEmitCharacterTask(tag, "Movement", { SpeedChange = { Type = "SpeedPad", Value = type(settings.Boost) == "number" and settings.Boost or 1.3, Length = type(settings.Length) == "number" and settings.Length or 3 } }) end end elseif now - (ConfigState.deployLastUse[d] or 0) > 3 and DeployInsideBox(bb, hrp.Position, 1, 3) then for _, other in ipairs(DeployableService.Deployables) do if other ~= d and DeployKind(other) == "teleport" and not DeployIsPending(other, now) then local ob = other.Model.Parent:FindFirstChild("BoundingBox") if ob and ob:IsA("BasePart") then ConfigState.deployLastUse[d] = now ConfigState.deployLastUse[other] = now hrp.CFrame = CFrame.new(ob.Position + Vector3.new(0, 3, 0)) break end end end end end end end end function DeploySetLoop(name, interval, step, enabled) local existing = ConfigState.deployLoops[name] if enabled and not existing then ConfigState.deployLoops[name] = HeartbeatLoop(interval, step) elseif not enabled and existing then existing:Disconnect() ConfigState.deployLoops[name] = nil end end function DeploySyncLoops() if not DeployableService then return end DeploySetLoop("hammer", 0.1, DeployHammerStep, ConfigState.deployState.autoSpeedUp or ConfigState.deployState.autoRepair) DeploySetLoop("usable", 0.05, DeployUsableStep, ConfigState.deployState.usableBuilding) end AutoSpeedUpToggle = Tabs.Combat:Toggle({ Title = "Auto Speed Up", Flag = "AutoSpeedUpToggle", Desc = "Hammers your own buildings to finish them faster. Stay within hammer range", Value = false, }) AutoSpeedUpToggle.Callback = function(state) ConfigState.deployState.autoSpeedUp = state DeploySyncLoops() end AutoRepairToggle = Tabs.Combat:Toggle({ Title = "Auto Repair", Flag = "AutoRepairToggle", Desc = "Hammers deployables that ran out of uses. Stay within hammer range", Value = false, }) AutoRepairToggle.Callback = function(state) ConfigState.deployState.autoRepair = state DeploySyncLoops() end UsableWhileBuildingToggle = Tabs.Combat:Toggle({ Title = "Usable While Building", Flag = "UsableWhileBuildingToggle", Desc = "Jump pads, speed pads and teleporters work before the server finishes them (client side)", Value = false, }) UsableWhileBuildingToggle.Callback = function(state) ConfigState.deployState.usableBuilding = state DeploySyncLoops() end Tabs.Auto:Section({ Title = "Auto", TextSize = 40 }) local changePlayerMode = ReplicatedStorage.Remotes.Session.SetPlayerMode function checkAndFire() local Status = GetStatus(LocalPlayer) if not ConfigState.autoJoinEnabled then return end if Status == "DEAD" then if not ConfigState.isRejoiningRespawn then ConfigState.isRejoiningRespawn = true end if ConfigState.isRejoiningRespawn then local currentTime = tick() if currentTime - ConfigState.lastFireTime >= 10 then changePlayerMode:FireServer(true) ConfigState.lastFireTime = currentTime end end else ConfigState.isRejoiningRespawn = false end end toggleAutoJoin = Tabs.Auto:Toggle({ Title = "Auto Join", Value = false, }) toggleAutoJoin.Callback = function(state) ConfigState.autoJoinEnabled = state if state then if not ConfigState.connection then ConfigState.connection = RunService.RenderStepped:Connect(checkAndFire) end if not ConfigState.RejoinRepsawnConnection then ConfigState.RejoinRepsawnConnection = LocalPlayer.CharacterAdded:Connect(function() ConfigState.isRejoiningRespawn = false ConfigState.lastFireTime = 0 end) end else if ConfigState.connection then ConfigState.connection:Disconnect() ConfigState.connection = nil end if ConfigState.RejoinRepsawnConnection then ConfigState.RejoinRepsawnConnection:Disconnect() ConfigState.RejoinRepsawnConnection = nil end ConfigState.isRejoiningRespawn = false ConfigState.lastFireTime = 0 end end Tabs.Auto:Space() for bindName, data in pairs(DefaultKeybinds) do if type(data) == "table" and data.Type then local t = tostring(data.Type) if not ConfigState.KeybindType.HasSeen[t] then ConfigState.KeybindType.HasSeen[t] = true table.insert(ConfigState.KeybindType.KeyList, t) end end end function StartSpamKeybind() local isDown = false ConfigState.SpamKeybind.Connection = RunService.RenderStepped:Connect(function() if os.clock() - ConfigState.SpamKeybind.LastTick >= ConfigState.SpamKeybind.Delay and ConfigState.SpamKeybind.Enabled then ConfigState.SpamKeybind.LastTick = os.clock() SendKeybindEvent(ConfigState.SpamKeybind.KeybindTarget, isDown) isDown = not isDown end end) end function StopSpamKeybind() if ConfigState.SpamKeybind.Connection then ConfigState.SpamKeybind.Connection:Disconnect() ConfigState.SpamKeybind.Connection = nil end end Tabs.Auto:Space() SpamKeybindToggle = Tabs.Auto:Toggle({ Title = "Enable Spam Keybind", Value = false, }) SpamKeybindToggle.Callback = function(value) ConfigState.SpamKeybind.Enabled = value if value then StartSpamKeybind() else StopSpamKeybind() end end ButtonLib.Create:Toggle({ Text = "Smash Keybinds", Flag = "SpamKeybindButton", Default = false, Visible = false, Callback = function(value) SpamKeybindToggle:Set(not SpamKeybindToggle.Value) end }) ShowKeybindsSpamButton = Tabs.Auto:Toggle({ Title = "Show UI Smash Keybinds", Value = false, }) ShowKeybindsSpamButton.Callback = function(value) ButtonLib.SpamKeybindButton:SetVisible(value) end KeybindDelay = Tabs.Auto:Input({ Title = "Keybind Delay", Value = ConfigState.SpamKeybind.Delay, }) KeybindDelay.Callback = function(value) ConfigState.SpamKeybind.Delay = tonumber(value) or ConfigState.SpamKeybind.Delay end Tabs.Auto:Dropdown({ Title = "Keybind Type", Values = ConfigState.KeybindType.KeyList, Value = "None", Callback = function(value) ConfigState.SpamKeybind.KeybindTarget = value end }) Tabs.Auto:Section({ Title = "Bhop" }) BhopToggle = Tabs.Auto:Toggle({ Title = "Bhop", Flag = "BhopToggle", Value = false, }) BhopToggle.Callback = function(state) SetAutoJumpEnabled(state) end BhopHoldToggle = Tabs.Auto:Toggle({ Title = "Bhop Hold Jump", Flag = "BhopHoldToggle", Value = false, }) BhopHoldToggle.Callback = function(state) SetBhopHoldEnabled(state) end AccelerationDropdown = Tabs.Auto:Dropdown({ Title = "Bhop Mode", Flag = "AccelerationDropdown", Values = { "No Acceleration", "Acceleration" }, Value = "Acceleration", Callback = function(value) SetBhopAccelerationMethod(value) end }) AccelerationInput = Tabs.Auto:Input({ Title = "Bhop Acceleration (Negative Only)", Flag = "AccelerationInput", Placeholder = "-0.2", Numeric = true, Value = "-0.2", }) AccelerationInput.Callback = function(value) local n = tonumber(value) if n then ConfigState.accelerationValue = n end end AutoJumpTypeDropdown = Tabs.Auto:Dropdown({ Title = "Auto Jump Mode", Flag = "AutoJumpTypeDropdown", Values = { "Simulation", "Realistic" }, Value = "Simulation", Callback = function(value) ConfigState.autoJumpType = value if ConfigState.autoJumpEnabled or ConfigState.bhopHoldEnabled then SyncBhopMovementFlag() end end }) AutoWallHop = Tabs.Auto:Toggle({ Title = "Auto Wall Hop", Flag = "AutoWallHop", Value = false, Type = "Checkbox", }) AutoWallHop.Callback = function(state) ConfigState.AutowallHop = state end ShowBunnyHopButtonToggle = Tabs.Auto:Toggle({ Title = "Show UI Bunny Hop", Flag = "ShowBunnyHopButton", Value = false, }) ShowBunnyHopButtonToggle.Callback = function(state) if ButtonLib and ButtonLib.BunnyHopToggle then ButtonLib.BunnyHopToggle:SetVisible(state) end end ButtonLib.Create:Toggle({ Text = "Bunny Hop", Flag = "BunnyHopToggle", Default = false, Visible = false, Callback = function(s) if BhopToggle then BhopToggle:Set(s) end end }).Position = UDim2.new(0.5, - 125, 0.4, 0) Tabs.Auto:Section({ Title = "Auto Acceleration" }) AutoAccelerationToggle = Tabs.Auto:Toggle({ Title = "Auto Acceleration (Legit)", Flag = "AutoAccelerationToggle", Value = false, }) AutoAccelerationToggle.Callback = function(state) ConfigState.autoAccelerationEnabled = state end MaxAccelerationInput = Tabs.Auto:Input({ Title = "Max Acceleration", Flag = "MaxAccelerationInput", Placeholder = "3", Numeric = true, Value = "3", }) MaxAccelerationInput.Callback = function(value) n = tonumber(value) if n then ConfigState.maxAcceleration = n end end MinAccelerationInput = Tabs.Auto:Input({ Title = "Min Acceleration", Flag = "MinAccelerationInput", Placeholder = "-1", Numeric = true, Value = "-1", }) MinAccelerationInput.Callback = function(value) n = tonumber(value) if n then ConfigState.minAcceleration = n end end MaxSpeedInput = Tabs.Auto:Input({ Title = "Max Speed", Flag = "MaxSpeedInput", Placeholder = "70", Numeric = true, Value = "70", }) MaxSpeedInput.Callback = function(value) n = tonumber(value) if n and n > 0 then ConfigState.maxAutoAccelSpeed = n end end function preserveJumpVelocity() if ConfigState.jumpConnection then ConfigState.jumpConnection:Disconnect() end ConfigState.jumpConnection = RunService.Heartbeat:Connect(function() local char = LocalPlayer.Character if not char then return end local humanoid = char:FindFirstChild("Humanoid") local rootPart = char:FindFirstChild("HumanoidRootPart") if not humanoid or not rootPart then return end local state = humanoid:GetState() if state == Enum.HumanoidStateType.Jumping then if ConfigState.lastVelocity.Magnitude > 0 then local currentVel = rootPart.AssemblyLinearVelocity if currentVel.Magnitude < ConfigState.lastVelocity.Magnitude then rootPart.AssemblyLinearVelocity = Vector3.new( ConfigState.lastVelocity.X, currentVel.Y, ConfigState.lastVelocity.Z) end end ConfigState.lastVelocity = rootPart.AssemblyLinearVelocity elseif state == Enum.HumanoidStateType.Landed then ConfigState.lastVelocity = Vector3.new() end end) end Tabs.Auto:Section({ Title = "Auto Walk", TextSize = 20 }) Tabs.Auto:Divider() function StartAutoWalk() if not ControlModule then return false end if not ConfigState.autoWalkHooked then ConfigState.autoWalkHooked = true local original = ControlModule.GetMoveVector ControlModule.GetMoveVector = function(...) local input = original(...) if ConfigState.autoWalkEnabled and input.Magnitude <= 0.1 then return ConfigState.autoWalkDirection end return input end end ConfigState.autoWalkEnabled = true preserveJumpVelocity() return true end function StopAutoWalk() ConfigState.autoWalkEnabled = false if ConfigState.jumpConnection then ConfigState.jumpConnection:Disconnect() ConfigState.jumpConnection = nil end ConfigState.lastVelocity = Vector3.new() end AutoWalkToggle = Tabs.Auto:Toggle({ Title = "Auto Walk", Flag = "AutoWalkToggle", Value = false, }) AutoWalkToggle.Callback = function(state) if state then if not StartAutoWalk() then WindUI:Notify({ Title = "Auto Walk", Content = "Control module not found", Duration = 4 }) end else StopAutoWalk() end end ShowAutoWalkButtonToggle = Tabs.Auto:Toggle({ Title = "Show UI Auto Walk", Flag = "ShowAutoWalkButton", Value = false, }) ShowAutoWalkButtonToggle.Callback = function(state) if ButtonLib and ButtonLib.AutoWalkToggle then ButtonLib.AutoWalkToggle:SetVisible(state) end end AutoWalkDirectionInput = Tabs.Auto:Input({ Title = "Move Direction", Flag = "AutoWalkDirectionInput", Desc = "Move input as X Y Z. 0 0 -1 walks forward, 0 0 1 backward, 1 0 0 right", Placeholder = "X Y Z", Value = "0 0 -1", }) AutoWalkDirectionInput.Callback = function(value) local x, y, z = value:match("^%s*(%-?[%d.]+)%s+(%-?[%d.]+)%s+(%-?[%d.]+)%s*$") if x and y and z then ConfigState.autoWalkDirection = Vector3.new(tonumber(x), tonumber(y), tonumber(z)) end end ButtonLib.Create:Toggle({ Text = "Auto Walk", Flag = "AutoWalkToggle", Default = false, Visible = false, Callback = function(s) if AutoWalkToggle then AutoWalkToggle:Set(s) end end }).Position = UDim2.new(0.5, - 125, 0.4, 0) Tabs.Auto:Space() function StartAutoCrouch() if ConfigState.crouchConnection then return end ConfigState.crouchConnection = RunService.RenderStepped:Connect(function() local autoOn = ConfigState.AutoCrouch local mode = ConfigState.AutoCrouchMode if not autoOn then SendKeybindEvent("Crouching", false) return end local character = Players.LocalPlayer.Character if not character or not character:FindFirstChild("Humanoid") then return end local humanoid = character.Humanoid local isAir = (humanoid.FloorMaterial == Enum.Material.Air) and (humanoid:GetState() ~= Enum.HumanoidStateType.Seated) if mode == "Spam" then local currentTime = tick() if currentTime - ConfigState.arg_v784 >= ConfigState.CrouchDelay then ConfigState.arg_v785 = not ConfigState.arg_v785 SendKeybindEvent("Crouching", ConfigState.arg_v785) ConfigState.arg_v784 = currentTime end elseif mode == "Normal" then SendKeybindEvent("Crouching", true) elseif mode == "Air" and isAir then SendKeybindEvent("Crouching", true) elseif mode == "Ground" and not isAir then SendKeybindEvent("Crouching", true) else SendKeybindEvent("Crouching", false) end end) end function StopAutoCrouch() if ConfigState.crouchConnection then ConfigState.crouchConnection:Disconnect() ConfigState.crouchConnection = nil end ConfigState.arg_v784 = 0 ConfigState.arg_v785 = false SendKeybindEvent("Crouching", false) end Tabs.Auto:Space() AutoCrouchToggle = Tabs.Auto:Toggle({ Title = "Auto Crouch", Flag = "AutoCrouchToggle", Value = false, }) AutoCrouchToggle.Callback = function(state) ConfigState.AutoCrouch = state if state then StartAutoCrouch() else StopAutoCrouch() end end SpamDelaySeconds = Tabs.Auto:Input({ Title = "Spam Delay (seconds)", Value = "0", }) SpamDelaySeconds.Callback = function(delay) ConfigState.CrouchDelay = tonumber(delay) or 0 end ButtonLib.Create:Toggle({ Text = "Auto Crouch", Flag = "AutoCrouchToggle", Default = false, Visible = false, Callback = function(s) if AutoCrouchToggle then AutoCrouchToggle:Set(s) end end }).Position = UDim2.new(0.5, - 125, 0.4, 0) ShowAutoCrouchButtonToggle = Tabs.Auto:Toggle({ Title = "Show UI Auto Crouch", Flag = "ShowAutoCrouchButton", Value = false, }) ShowAutoCrouchButtonToggle.Callback = function(state) ConfigState.ShowAutoCrouchButton = state ButtonLib.AutoCrouchToggle:SetVisible(state) end AutoCrouchModeDropdown = Tabs.Auto:Dropdown({ Title = "Auto Crouch Mode", Flag = "AutoCrouchModeDropdown", Values = { "Air", "Spam", "Ground", "Normal" }, Value = "Air", Callback = function(value) ConfigState.AutoCrouchMode = value ConfigState.arg_v784 = 0 ConfigState.arg_v785 = false if value ~= "Spam" then SendKeybindEvent("Crouching", false) end end }) Tabs.Auto:Space() function startAutoCarry() ConfigState.AutoCarryConnection = RunService.Heartbeat:Connect(function() if not ConfigState.AutoCarry then return end local char = LocalPlayer.Character if not char then return end local hrp = char:FindFirstChild("HumanoidRootPart") if not hrp then return end local charData = CharacterService:GetCharacterFromPlayer(LocalPlayer) if not charData then return end local movement = charData.Movement if not movement then return end local state = movement.State local carryStates = { "Carry", "CarrySlide", "CarrySlideAir", "CarryAir", "Carried", "CarryMove", "CarryIdle" } local isCarrying = false for _, s in ipairs(carryStates) do if state == s then isCarrying = true break end end if isCarrying then return end local now = tick() if now - ConfigState.lastCarryAttempt < ConfigState.carryCooldown then return end for _, other in ipairs(Players:GetPlayers()) do if other == LocalPlayer then continue end local otherChar = other.Character if not otherChar then continue end if isPlayerDowned(other) then if isPlayerRagdolled(other) then continue end local otherHRP = otherChar:FindFirstChild("HumanoidRootPart") if not otherHRP then continue end local dist = (hrp.Position - otherHRP.Position).Magnitude local targetTag = otherChar:GetAttribute("Tag") if targetTag then Interact:FireServer("Carry", targetTag) ConfigState.lastCarryAttempt = now break end end end end) end function stopAutoCarry() if ConfigState.AutoCarryConnection then ConfigState.AutoCarryConnection:Disconnect() ConfigState.AutoCarryConnection = nil end end AutoCarryToggle = Tabs.Auto:Toggle({ Title = "Auto Carry", Flag = "AutoCarryToggle", Value = false, }) AutoCarryToggle.Callback = function(state) ConfigState.AutoCarry = state if state then startAutoCarry() else stopAutoCarry() end end ButtonLib.Create:Toggle({ Text = "AUTO CARRY", Flag = "CarryToggle", Default = false, Visible = false, Callback = function(s) if AutoCarryToggle then AutoCarryToggle:Set(s) end end }).Position = UDim2.new(0.5, - 125, 0.4, 0) ShowCarryButtonToggle = Tabs.Auto:Toggle({ Title = "Show UI Auto Carry", Flag = "ShowCarryButton", Value = false, }) ShowCarryButtonToggle.Callback = function(state) ConfigState.ShowCarryButton = state if ButtonLib and ButtonLib.CarryToggle then ButtonLib.CarryToggle:SetVisible(state) end end Tabs.Auto:Space() function getVotePopup() if ServerStateRegistryService.Registry.Voting == false then return nil end if not PlayerGui then return nil end local shared = PlayerGui:FindFirstChild("Shared") if shared then local popups = shared:FindFirstChild("Popups") if popups then local voteActive = popups:FindFirstChild("VoteActive") if voteActive and voteActive.Visible then return voteActive end local vote = popups:FindFirstChild("Vote") if vote and vote.Visible then return vote end end end return nil end function fireVoteServer(mapNumber) local votePopup = getVotePopup() if not votePopup then return end local voteEvent = ReplicatedStorage:FindFirstChild("Remotes") if voteEvent then voteEvent = voteEvent:FindFirstChild("Round") end if voteEvent then voteEvent = voteEvent:FindFirstChild("Vote") if voteEvent and voteEvent:IsA("RemoteEvent") then voteEvent:FireServer(mapNumber) end end end function fireVoteMode(modeNumber) local votePopup = getVotePopup() if not votePopup then return end local voteEvent = ReplicatedStorage:FindFirstChild("Remotes") if voteEvent then voteEvent = voteEvent:FindFirstChild("Round") end if voteEvent then voteEvent = voteEvent:FindFirstChild("Vote") if voteEvent and voteEvent:IsA("RemoteEvent") then voteEvent:FireServer(modeNumber, true) end end end function StartAutoVoteMap() StopAutoVoteMap() ConfigState.AutoVote.Enabled = true ConfigState.AutoVote.Connections.Map = RunService.Heartbeat:Connect(function() fireVoteServer(ConfigState.AutoVote.Map) end) end function StopAutoVoteMap() ConfigState.AutoVote.Enabled = false if ConfigState.AutoVote.Connections.Map then ConfigState.AutoVote.Connections.Map:Disconnect() ConfigState.AutoVote.Connections.Map = nil end end function StartAutoVoteMode() StopAutoVoteMode() ConfigState.AutoVote.Enabled = true ConfigState.AutoVote.Connections.Mode = RunService.Heartbeat:Connect(function() fireVoteMode(ConfigState.AutoVote.Mode) end) end function StopAutoVoteMode() if ConfigState.AutoVote.Connections.Mode then ConfigState.AutoVote.Connections.Mode:Disconnect() ConfigState.AutoVote.Connections.Mode = nil end end for i = 1, 4 do table.insert(ConfigState.mapDropdownValues, "Map " .. i) end AutoVoteDropdown = Tabs.Auto:Dropdown({ Title = "Auto Vote Map", Flag = "AutoVoteDropdown", Values = ConfigState.mapDropdownValues, Value = "Map 1", Callback = function(value) ConfigState.AutoVote.Map = tonumber(value:match("%d+")) end }) AutoVoteToggle = Tabs.Auto:Toggle({ Title = "Auto Vote Map", Flag = "AutoVoteToggle", Value = false, }) AutoVoteToggle.Callback = function(state) if state then StartAutoVoteMap() else StopAutoVoteMap() end end Tabs.Auto:Space() for i = 1, 4 do table.insert(ConfigState.modeDropdownValues, "Mode " .. i) end AutoVoteModeDropdown = Tabs.Auto:Dropdown({ Title = "Auto Vote Mode", Flag = "AutoVoteModeDropdown", Values = ConfigState.modeDropdownValues, Value = "Mode 1", Callback = function(value) ConfigState.AutoVote.Mode = tonumber(value:match("%d+")) end }) AutoVoteModeToggle = Tabs.Auto:Toggle({ Title = "Auto Vote Game Mode", Flag = "AutoVoteModeToggle", Value = false, }) AutoVoteModeToggle.Callback = function(state) if state then StartAutoVoteMode() else StopAutoVoteMode() end end function ConfigState.SelfRevive:Respawn() local now = tick() if now - ConfigState.SelfRevive.LastRespawnTime < 0.5 then return end ConfigState.SelfRevive.LastRespawnTime = now if ConfigState.SelfRevive.IsProcessing then return end local char = LocalPlayer.Character if not char then return end local charData = CharacterService:GetCharacterFromPlayer(LocalPlayer) local isDowned = charData and charData.DataRegistry:Get("Downed") if not isDowned then return end ConfigState.SelfRevive.IsProcessing = true local hrp = char:FindFirstChild("HumanoidRootPart") if ConfigState.SelfRevive.Method == "Spawnpoint" then if not ConfigState.SelfRevive.HasRevived then self.HasRevived = true changePlayerMode:FireServer(true) ConfigState.SelfRevive.IsProcessing = false task.delay(10, function() self.HasRevived = false end) else ConfigState.SelfRevive.IsProcessing = false end elseif self.Method == "Fake Revive" then local savedPos = nil if hrp then savedPos = hrp.CFrame.Position end pcall(function() changePlayerMode:FireServer(true) end) local reviveConn reviveConn = game:GetService("RunService").Heartbeat:Connect(function() local newCharacter = LocalPlayer.Character if not (newCharacter and newCharacter:FindFirstChild("HumanoidRootPart") and newCharacter ~= char) then return end reviveConn:Disconnect() local newHRP = newCharacter:FindFirstChild("HumanoidRootPart") if savedPos and newHRP then task.wait(0.1) newHRP.CFrame = CFrame.new(savedPos + Vector3.new(0, 0, 0)) end ConfigState.SelfRevive.IsProcessing = false end) else ConfigState.SelfRevive.IsProcessing = false end end function ConfigState.SelfRevive:Start() if ConfigState.SelfRevive.Connections.Heartbeat then return end ConfigState.SelfRevive.Enabled = true ConfigState.SelfRevive.Connections.Heartbeat = RunService.Heartbeat:Connect(function() if not ConfigState.SelfRevive.Enabled then return end local char = LocalPlayer.Character if not char then return end local charData = CharacterService:GetCharacterFromPlayer(LocalPlayer) if charData and charData.DataRegistry:Get("Downed") then self:Respawn() end end) ConfigState.SelfRevive.Connections.Character = LocalPlayer.CharacterAdded:Connect(function(newChar) ConfigState.SelfRevive.HasRevived = false ConfigState.SelfRevive.IsProcessing = false ConfigState.SelfRevive.LastSavedPosition = nil end) end function ConfigState.SelfRevive:Stop() ConfigState.SelfRevive.Enabled = false ConfigState.SelfRevive.HasRevived = false ConfigState.SelfRevive.IsProcessing = false ConfigState.SelfRevive.LastSavedPosition = nil for name, conn in pairs(ConfigState.SelfRevive.Connections) do if conn then conn:Disconnect() ConfigState.SelfRevive.Connections[name] = nil end end end Tabs.Auto:Space() AutoSelfReviveToggle = Tabs.Auto:Toggle({ Title = "Auto Self Revive", Flag = "AutoSelfReviveToggle", Value = false, }) AutoSelfReviveToggle.Callback = function(state) if state then ConfigState.SelfRevive:Start() else ConfigState.SelfRevive:Stop() end end SelfReviveMethodDropdown = Tabs.Auto:Dropdown({ Title = "Self Revive Method", Flag = "SelfReviveMethodDropdown", Values = { "Spawnpoint", "Fake Revive" }, Value = "Spawnpoint", Callback = function(value) ConfigState.SelfRevive.Method = value end }) function SelfReviveNow() ConfigState.SelfRevive:Respawn() end function ForceRespawnNow() changePlayerMode:FireServer(true) end function SelfReviveButtonToggled(state) if ButtonLib.SelfReviveButton then ButtonLib.SelfReviveButton:SetVisible(state) end end function ForceRespawnButtonToggled(state) if ButtonLib.ForceRespawnButton then ButtonLib.ForceRespawnButton:SetVisible(state) end end Tabs.Auto:Button({ Title = "Manual Revive", Desc = "Manually revive yourself", Icon = "heart", Callback = SelfReviveNow }) Tabs.Auto:Button({ Title = "Force Respawn", Icon = "heart", Callback = ForceRespawnNow }) ButtonLib.Create:Button({ Text = "Self Revive", Flag = "SelfReviveButton", Position = UDim2.new(0.5, - 125, 0.3, 0), Visible = false, Callback = SelfReviveNow }) ButtonLib.Create:Button({ Text = "Force Respawn", Flag = "ForceRespawnButton", Position = UDim2.new(0.5, - 125, 0.4, 0), Visible = false, Callback = ForceRespawnNow }) Tabs.Auto:Toggle({ Title = "Show UI Self Revive", Flag = "SelfReviveButtonToggle", Value = false, Callback = SelfReviveButtonToggled }) Tabs.Auto:Toggle({ Title = "Show UI Force Respawn", Flag = "ForceRespawnButtonToggle", Value = false, Callback = ForceRespawnButtonToggled }) Tabs.Auto:Space() function AutoReviveStop() ConfigState.autoReviveEnabled = false if ConfigState.autoReviveConnection then ConfigState.autoReviveConnection:Disconnect() ConfigState.autoReviveConnection = nil end table.clear(ConfigState.lastRevive) end function AutoReviveStart() AutoReviveStop() ConfigState.autoReviveEnabled = true ConfigState.autoReviveConnection = RunService.Heartbeat:Connect(function() if not ConfigState.autoReviveEnabled then return end local folder = workspace:FindFirstChild("Players") local ownCharacter = LocalPlayer.Character local ownRoot = ownCharacter and ownCharacter:FindFirstChild("HumanoidRootPart") if not folder or not ownRoot then return end local now = os.clock() for _, model in ipairs(folder:GetChildren()) do if model:IsA("Model") and model ~= ownCharacter then local tag = model:GetAttribute("Tag") local root = model:FindFirstChild("HumanoidRootPart") or model.PrimaryPart local is_downed_target = isReviveTargetDowned(model) if tag ~= nil and root and is_downed_target and now - (ConfigState.lastRevive[model] or 0) >= ConfigState.autoReviveDelay then if ConfigState.autoReviveRange == math.huge or (ownRoot.Position - root.Position).Magnitude <= ConfigState.autoReviveRange then ConfigState.lastRevive[model] = now Interact:FireServer("Revive", tag) Interact:FireServer("Revive", tag, true) end end end end end) end AutoReviveToggle = Tabs.Auto:Toggle({ Title = "Auto Revive", Flag = "AutoReviveToggle", Desc = "Fires revive on downed players within range", Value = false, }) AutoReviveToggle.Callback = function(state) if state then AutoReviveStart() else AutoReviveStop() end end AutoReviveDelaySlider = Tabs.Auto:Slider({ Title = "Auto Revive Delay", Flag = "AutoReviveDelaySlider", Desc = "Seconds between revive fires per target", Step = 0.01, Value = { Min = 0.84, Max = 4, Default = 1.17 }, }) AutoReviveDelaySlider.Callback = function(value) ConfigState.autoReviveDelay = value end Tabs.Auto:Space() AutoWhistleToggle = Tabs.Auto:Toggle({ Title = "Auto Whistle", Flag = "AutoWhistleToggle", Value = false, }) AutoWhistleToggle.Callback = function(state) ConfigState.AutoWhistle = state if state then startAutoWhistle() else stopAutoWhistle() end end function startAutoWhistle() if ConfigState.autoWhistleConnection then return end ConfigState.lastWhistle = tick() ConfigState.autoWhistleConnection = RunService.Heartbeat:Connect(function() if not ConfigState.AutoWhistle then return end local now = tick() if now - ConfigState.lastWhistle >= 1 then ConfigState.lastWhistle = now; SendKeybindInfo({ Down = true, Key = "Whistle", Keybind = "Whistle", }) end end) end function stopAutoWhistle() ConfigState.AutoWhistle = false if ConfigState.autoWhistleConnection then ConfigState.autoWhistleConnection:Disconnect() ConfigState.autoWhistleConnection = nil end end Tabs.Auto:Space() function isNPCModel(model) if not model or not model:IsA("Model") then return false end if model:GetAttribute("AI") == true then return true end if model:FindFirstChild("HumanoidRootPart") and model:FindFirstChild("Humanoid") then local parent = model.Parent if parent and parent.Name == "Players" then if model:GetAttribute("AI") == true then return true end end end return false end function isEventNPC(model) if typeof(model) ~= "Instance" then return false end if model:GetAttribute("TouchRange") ~= nil then return true end local ok, tagged = pcall(function() return game:GetService("CollectionService"):HasTag(model, ConfigState.CatchTagName or "TouchReward") end) return ok and tagged == true end function isModelDowned(model) if not model or not model:IsA("Model") then return false end local humanoid = model:FindFirstChild("Humanoid") if humanoid and humanoid.Health <= 0 then return true end return false end function getCurrentHRP() local char = LocalPlayer.Character if char then return char:FindFirstChild("HumanoidRootPart") end return nil end function getPlayersWithHRP() local result = {} for _, plr in ipairs(Players:GetPlayers()) do if plr ~= LocalPlayer and plr.Character and plr.Character:FindFirstChild("HumanoidRootPart") then table.insert(result, plr) end end return result end function getDownedPlayers() local downed = {} local function scanFolder(folder) if not folder then return end for _, model in ipairs(folder:GetChildren()) do if model:IsA("Model") and isModelDowned(model) and model.Name ~= LocalPlayer.Name then local hrp = model:FindFirstChild("HumanoidRootPart") if hrp then table.insert(downed, model) end end end end scanFolder(workspace:FindFirstChild("Players")) local gameFolder = workspace:FindFirstChild("Game") if gameFolder then scanFolder(gameFolder:FindFirstChild("Players")) end return downed end function getNPCs() local bots = {} local function scanFolder(folder) if not folder then return end for _, model in ipairs(folder:GetChildren()) do if model:IsA("Model") and isNPCModel(model) then local hrp = model:FindFirstChild("HumanoidRootPart") if hrp then table.insert(bots, model) end end end end scanFolder(workspace:FindFirstChild("Players")) local gameFolder = workspace:FindFirstChild("Game") if gameFolder then scanFolder(gameFolder:FindFirstChild("Players")) end return bots end function getSpawns() local spawnsFolder = workspace:FindFirstChild("Map") and workspace.Map:FindFirstChild("Parts") and workspace.Map.Parts:FindFirstChild("Spawns") if not spawnsFolder then spawnsFolder = workspace:FindFirstChild("Map") and workspace.Map:FindFirstChild("Parts") and workspace.Map.Parts:FindFirstChild("Spawns") end if spawnsFolder then return spawnsFolder:GetChildren() end return {} end function getTickets() local tickets = workspace:FindFirstChild("Effects") and workspace.Effects:FindFirstChild("Tickets") if not tickets then tickets = workspace:FindFirstChild("Effects") and workspace.Effects:FindFirstChild("Tickets") end if tickets then return tickets:GetChildren() end return {} end function getObjectives() local objectives = {} local gameFolder = workspace:FindFirstChild("Game") if not gameFolder then return objectives end local mapFolder = gameFolder:FindFirstChild("Map") if not mapFolder then return objectives end local partsFolder = mapFolder:FindFirstChild("Parts") if not partsFolder then return objectives end local objectivesFolder = partsFolder:FindFirstChild("Objectives") if not objectivesFolder then return objectives end for _, obj in pairs(objectivesFolder:GetChildren()) do if obj:IsA("Model") then local primaryPart = obj.PrimaryPart if not primaryPart then for _, part in pairs(obj:GetChildren()) do if part:IsA("BasePart") then primaryPart = part break end end end if primaryPart then table.insert(objectives, { Name = obj.Name, Part = primaryPart, Position = primaryPart.Position, Size = primaryPart.Size }) end end end return objectives end function teleportToCFrame(cframeOffset) local hrp = getCurrentHRP() if hrp then hrp.CFrame = cframeOffset end end function teleportToRandomFromList(list, offset) if # list > 0 then local target = list[math.random(1, # list)] local hrp = target:FindFirstChild("HumanoidRootPart") if hrp then teleportToCFrame(hrp.CFrame + offset) end end end function teleportToRandomPlayer(offset) local players = getPlayersWithHRP() if # players > 0 then local target = players[math.random(1, # players)] teleportToCFrame(target.Character.HumanoidRootPart.CFrame + offset) end end function teleportToRandomDowned(offset) local downed = getDownedPlayers() teleportToRandomFromList(downed, offset) end function teleportToRandomNPC(offset) local bots = getNPCs() teleportToRandomFromList(bots, offset) end function teleportToRandomSpawn(offset) local spawns = getSpawns() if # spawns > 0 then local target = spawns[math.random(1, # spawns)] teleportToCFrame(target.CFrame + offset) end end function teleportToRandomTicket(offset) local tickets = getTickets() if # tickets > 0 then local target = tickets[math.random(1, # tickets)] local part = target:FindFirstChild("HumanoidRootPart") or target:FindFirstChildWhichIsA("BasePart") if part then teleportToCFrame(part.CFrame + offset) end end end function teleportToObjective(objectiveName, offset) local objectives = getObjectives() for _, obj in ipairs(objectives) do if obj.Name == objectiveName then local teleportPosition = obj.Position + offset local raycastParams = RaycastParams.new() local char = LocalPlayer.Character if char then raycastParams.FilterDescendantsInstances = { char } end raycastParams.FilterType = Enum.RaycastFilterType.Blacklist local ray = workspace:Raycast(teleportPosition, Vector3.new(0, - 10, 0), raycastParams) if ray then teleportPosition = ray.Position + Vector3.new(0, 3, 0) end teleportToCFrame(CFrame.new(teleportPosition)) return end end end function teleportToSecurityPart(offset) local existingPart = SecurityPart or workspace:FindFirstChild("SecurityPart") if existingPart then local character = game.Players.LocalPlayer.Character if character and character:FindFirstChild("HumanoidRootPart") then character.HumanoidRootPart.CFrame = CFrame.new(existingPart.Position + offset) end else print("SecurityPart not found") end end if task.spawn(ConfigState.PlayerData.EventActive) then table.insert(ConfigState.AutoFarmType, "Auto Ticket") end local TicketsFolder = workspace:FindFirstChild("Effects") and workspace.Effects:FindFirstChild("Tickets") function isTokenFarmLocalPlayerModel(model) if not model then return true end if model == LocalPlayer.Character then return true end if model.Name == LocalPlayer.Name then return true end if model.Name == tostring(LocalPlayer.UserId) then return true end local attrName = model:GetAttribute("Name") if attrName == LocalPlayer.Name or attrName == LocalPlayer.DisplayName then return true end local attrTag = model:GetAttribute("Tag") if attrTag == LocalPlayer.Name or attrTag == LocalPlayer.DisplayName then return true end local userId = model:GetAttribute("UserId") or model:GetAttribute("PlayerUserId") if typeof(userId) == "number" and userId == LocalPlayer.UserId then return true end return false end function isValidTokenFarmTarget(model) if not model or not model.Parent or not model:IsA("Model") then return false end if model.Parent.Name ~= "Players" then return false end if isTokenFarmLocalPlayerModel(model) then return false end if not model:FindFirstChild("HumanoidRootPart") then return false end if model:GetAttribute("Tag") == nil then return false end if not isReviveTargetDowned(model) then return false end return true end function pickRandomTokenFarmTarget() local playersFolder = workspace:FindFirstChild("Players") if not playersFolder then return nil end local valid = {} for _, model in ipairs(playersFolder:GetChildren()) do if isValidTokenFarmTarget(model) then table.insert(valid, model) end end if # valid == 0 then return nil end return valid[math.random(1, # valid)] end function StartAutoObjective() if ConfigState.AutoObjective.Enabled then return end ConfigState.AutoObjective.Enabled = true ConfigState.AutoObjective.Thread = HeartbeatLoop(0.2, function() local objectivesContainer = workspace:FindFirstChild("Map") and workspace.Map:FindFirstChild("Parts") and workspace.Map.Parts:FindFirstChild("Objectives") if objectivesContainer then local anyCompleted = false for _, obj in pairs(objectivesContainer:GetChildren()) do if obj:GetAttribute("Completed") == true then anyCompleted = true break end end if not anyCompleted then for _, objective in pairs(objectivesContainer:GetChildren()) do if not ConfigState.AutoObjective.Enabled then break end if objective:FindFirstChild("WhenActivated") then local tagValue = objective:GetAttribute("Tag") if tagValue then pcall(function() Interact:FireServer("Dynamic", tagValue) end) task.wait(ConfigState.AutoObjective.Delay) end end end end end end) end function StopAutoObjective() ConfigState.AutoObjective.Enabled = false if ConfigState.AutoObjective.Thread then ConfigState.AutoObjective.Thread:Disconnect() ConfigState.AutoObjective.Thread = nil end end local CollectionService = game:GetService("CollectionService") function getCatchRoot(model) if typeof(model) ~= "Instance" or not model.Parent then return nil end return model.PrimaryPart or model:FindFirstChild("HumanoidRootPart") or model:FindFirstChildWhichIsA("BasePart", true) end function isCatchTarget(inst) if typeof(inst) ~= "Instance" or not inst:IsDescendantOf(workspace) then return false end if inst:GetAttribute("Tag") == nil then return false end return getCatchRoot(inst) ~= nil end function getCatchRange(inst) return tonumber(inst:GetAttribute("TouchRange")) or 10 end function getCatchTargets() local targets = {} local seen = {} local function add(inst) if not seen[inst] and isCatchTarget(inst) then seen[inst] = true table.insert(targets, inst) end end for _, inst in ipairs(CollectionService:GetTagged(ConfigState.CatchTagName)) do add(inst) end if # targets == 0 then local now = tick() if now - (ConfigState.AutoFarm.LastCatchFallbackScan or 0) >= 5 then ConfigState.AutoFarm.LastCatchFallbackScan = now for _, inst in ipairs(workspace:GetDescendants()) do if inst:IsA("Model") and inst:GetAttribute("TouchRange") ~= nil then add(inst) end end end end local char = LocalPlayer.Character local myRoot = char and char:FindFirstChild("HumanoidRootPart") if myRoot then table.sort(targets, function(x, y) local rx, ry = getCatchRoot(x), getCatchRoot(y) if not rx or not ry then return rx ~= nil end return (rx.Position - myRoot.Position).Magnitude < (ry.Position - myRoot.Position).Magnitude end) end return targets end function StartAutoFarm() if ConfigState.AutoFarm.Connection then ConfigState.AutoFarm.Connection:Disconnect() ConfigState.AutoFarm.Connection = nil end ConfigState.AutoFarm.Enabled = true ConfigState.AutoFarm.Connection = game:GetService("RunService").Heartbeat:Connect(function() local char = game.Players.LocalPlayer.Character local hrp = char and char:FindFirstChild("HumanoidRootPart") if not hrp then return end local hasTicket = table.find(ConfigState.AutoFarm.Modes, "Auto Ticket") ~= nil local hasTokenFarm = table.find(ConfigState.AutoFarm.Modes, "Token Farm") ~= nil local hasCatchNPC = table.find(ConfigState.AutoFarm.Modes, "Catch NPC") ~= nil local now = tick() local catchTarget = nil if hasCatchNPC then if now - ConfigState.AutoFarm.LastCatchScan >= 0.25 then ConfigState.AutoFarm.LastCatchScan = now ConfigState.AutoFarm.CatchTargets = getCatchTargets() end local target = ConfigState.AutoFarm.CatchTarget if not target or not isCatchTarget(target) then target = nil for _, candidate in ipairs(ConfigState.AutoFarm.CatchTargets) do if isCatchTarget(candidate) then target = candidate break end end ConfigState.AutoFarm.CatchTarget = target end catchTarget = target end local ticketTarget = nil if hasTicket then local ticket = TicketsFolder and TicketsFolder:GetChildren()[1] ticketTarget = ticket and (ticket:FindFirstChild("HumanoidRootPart") or ticket:FindFirstChildWhichIsA("BasePart")) end local tokenTarget = nil if hasTokenFarm then if not isValidTokenFarmTarget(ConfigState.AutoFarm.ReviveTarget) then ConfigState.AutoFarm.ReviveTarget = pickRandomTokenFarmTarget() end tokenTarget = ConfigState.AutoFarm.ReviveTarget end local catchHrp = catchTarget and getCatchRoot(catchTarget) local tokenHrp = tokenTarget and tokenTarget:FindFirstChild("HumanoidRootPart") local destPart = catchHrp or ticketTarget or tokenHrp if AntiNPCBlocksTeleport(destPart and destPart.Position or nil) then return end if catchHrp then local catchRange = getCatchRange(catchTarget) local catchOffset = ConfigState.AutoFarm.CatchOffset if catchOffset.Magnitude > catchRange - 1 then catchOffset = catchOffset.Magnitude > 0 and catchOffset.Unit * math.max(catchRange - 1, 0) or catchOffset end hrp.CFrame = catchHrp.CFrame + catchOffset local catchTag = catchTarget:GetAttribute("Tag") if catchTag and now - ConfigState.AutoFarm.LastCatchFire >= ConfigState.AutoFarm.CatchDelay then ConfigState.AutoFarm.LastCatchFire = now ReplicatedStorage.Remotes.Character.TouchReward:FireServer(catchTag) end elseif ticketTarget then hrp.CFrame = ticketTarget.CFrame + Vector3.new(0, 0, 0) elseif tokenHrp then hrp.CFrame = tokenHrp.CFrame + ConfigState.AutoFarm.TokenOffset local tag = tokenTarget:GetAttribute("Tag") if tag and now - ConfigState.AutoFarm.LastTokenFire >= ConfigState.AutoFarm.TokenDelay then ConfigState.AutoFarm.LastTokenFire = now; pcall(function() Interact:FireServer("Revive", tag) Interact:FireServer("Revive", tag, true) end) end else teleportToSecurityPart(Vector3.new(0, 3, 0)) end end) end function StopAutoFarm() ConfigState.AutoFarm.Enabled = false if ConfigState.AutoFarm.Connection then ConfigState.AutoFarm.Connection:Disconnect() ConfigState.AutoFarm.Connection = nil end ConfigState.AutoFarm.ReviveTarget = nil ConfigState.AutoFarm.CatchTarget = nil ConfigState.AutoFarm.CatchTargets = {} ConfigState.AutoFarm.LastCatchFallbackScan = 0 ConfigState.AutoFarm.FireCount = 0 ConfigState.AutoFarm.LastReviveFire = 0 ConfigState.AutoFarm.LastTokenFire = 0 end AutoFarmDropdown = Tabs.Auto:Dropdown({ Title = "Auto Farm Mode", Flag = "AutoFarmDropdown", Values = ConfigState.AutoFarmType, Multi = true, AllowNone = true, Value = {}, Callback = function(selected) ConfigState.AutoFarm.Modes = selected end }) TokenFarmOffsetInput = Tabs.Auto:Input({ Title = "Token Farm Offset", Flag = "TokenFarmOffsetInput", Placeholder = "X Y Z", Value = "0 0 0", }) TokenFarmOffsetInput.Callback = function(value) local x, y, z = value:match("^%s*([%-%d%.]+)%s+([%-%d%.]+)%s+([%-%d%.]+)%s*$") if x and y and z then ConfigState.AutoFarm.TokenOffset = Vector3.new(tonumber(x), tonumber(y), tonumber(z)) end end TokenFarmDelaySlider = Tabs.Auto:Slider({ Title = "Token Farm Delay", Flag = "TokenFarmDelaySlider", Desc = "Revive fire delay in seconds", Step = 0.01, Value = { Min = 0.84, Max = 4, Default = 2 }, }) TokenFarmDelaySlider.Callback = function(value) ConfigState.AutoFarm.TokenDelay = value end AutoFarmToggle = Tabs.Auto:Toggle({ Title = "Auto Farm", Flag = "AutoFarmToggle", Value = false, }) AutoFarmToggle.Callback = function(state) if state then AntiAfkToggle:Set(true) AutoSelfReviveToggle:Set(true) local isVIP = game.Players.LocalPlayer:GetAttribute("VIPCommandsAccess") == true if isVIP or ConfigState.AutoFarm.WarningShown then StartAutoFarm() else WindUI:Popup({ Title = "<b><font color='#FF5555'>WARNING! BAN WAVE!</font></b>", Icon = "shield-x", Content = [[<b><font color='#FFAA00'>⚠️DO NOT USE AUTO FARM ON PUBLIC SERVER OR UNTRUSTED PRIVATE SERVER! IF YOU DON'T WANNA GET BAN!</font></b>
<font color='#4fe000'> • Be Sure Use It On Your Own Private Server To Avoid BAN!</font>
<b><font color='#FF5555'> • IF YOU KEEP CONTINUE DOING THIS YOU WILL GET BAN ANYTIME SOON!</font></b>
<b><font color='#FF5555'> 🚫 WHEN YOU GET BANNED, THERE'S NO UNBAN APPEAL!</font></b>
<font color='#FF5555'> Remember: Staff will not giving you second chance!</font>]], Buttons = { { Title = "Cancel", Callback = function() AutoFarmToggle:Set(false) end, Variant = "Destructive" }, { Title = "Continue Anyway", Icon = "shield-check", Callback = function() ConfigState.AutoFarm.WarningShown = true StartAutoFarm() end, Variant = "Primary" } } }) end else StopAutoFarm() end end AutoCompleteObjectiveToggle = Tabs.Auto:Toggle({ Title = "Auto Complete Objective", Flag = "AutoCompleteObjectiveToggle", Value = false, }) AutoCompleteObjectiveToggle.Callback = function(state) if state then StartAutoObjective() else StopAutoObjective() end end Tabs.Visuals:Section({ Title = "Visual", TextSize = 20 }) Tabs.Visuals:Divider() popupservice_rewards_speed_toggle = Tabs.Visuals:Toggle({ Title = "Speedup Popup Rewards", Flag = "popupservice_rewards_speed_toggle", Value = false, Callback = function(s) if s then if not PopupService_Rewards or type(PopupService_Rewards.ShowAnimation) ~= "function" then warn("[NEXRIFT] Rewards popup module not loaded, speed patch skipped") return end if not (getfenv and setfenv) then warn("[NEXRIFT] This executor has no getfenv/setfenv, speed patch unavailable") return end if PopupService_Rewards._speedPatched then return end local original = PopupService_Rewards.ShowAnimation local baseEnv = getfenv(original) local baseTween = baseEnv.tween PopupService_Rewards._originalEnv = baseEnv PopupService_Rewards._speedPatched = true local proxyTask = setmetatable({}, { __index = task }) proxyTask.wait = function(t) local mult = tonumber(ConfigState.popupservice_rewards_speed) or 1 if type(t) == "number" and t > 0 then return task.wait(t / mult) end return task.wait(t) end local proxyTween = function(inst, goal, time, style, dir, rev) local mult = tonumber(ConfigState.popupservice_rewards_speed) or 1 return baseTween(inst, goal, time / mult, style, dir, rev) end setfenv(original, setmetatable({ task = proxyTask, tween = proxyTween, }, { __index = baseEnv })) else if PopupService_Rewards and PopupService_Rewards._originalEnv then setfenv(PopupService_Rewards.ShowAnimation, PopupService_Rewards._originalEnv) end PopupService_Rewards._originalEnv = nil PopupService_Rewards._speedPatched = nil end end }) popupservice_rewards_speed_input = Tabs.Visuals:Input({ Title = "popupservice_rewards_speed", Value = tostring(ConfigState.popupservice_rewards_speed), Flag = "PopupService_Rewards_speed", Placeholder = "Enter Your Speed", }) popupservice_rewards_speed_input.Callback = function(val) local n = tonumber(val) if n and n > 0 then ConfigState.popupservice_rewards_speed = n end end task.defer(function() pcall(function() popupservice_rewards_speed_toggle:Set(true) end) end) Tabs.Visuals:Space() CameraStretchToggle = Tabs.Visuals:Toggle({ Title = "Camera Stretch", Flag = "CameraStretchToggle", Value = false, }) CameraStretchToggle.Callback = function(state) if state then if ConfigState.cameraStretchConnection then ConfigState.cameraStretchConnection:Disconnect() end ConfigState.cameraStretchConnection = game:GetService("RunService").RenderStepped:Connect(function() local Camera = workspace.CurrentCamera Camera.CFrame = Camera.CFrame * CFrame.new(0, 0, 0, ConfigState.stretchHorizontal, 0, 0, 0, ConfigState.stretchVertical, 0, 0, 0, 1) end) else if ConfigState.cameraStretchConnection then ConfigState.cameraStretchConnection:Disconnect() ConfigState.cameraStretchConnection = nil end end end CameraStretchHorizontalInput = Tabs.Visuals:Input({ Title = "Camera Stretch Horizontal", Flag = "CameraStretchHorizontalInput", Placeholder = "0.80", Numeric = true, Value = tostring(ConfigState.stretchHorizontal), }) CameraStretchHorizontalInput.Callback = function(value) local num = tonumber(value) if num then ConfigState.stretchHorizontal = num if ConfigState.cameraStretchConnection then ConfigState.cameraStretchConnection:Disconnect() ConfigState.cameraStretchConnection = game:GetService("RunService").RenderStepped:Connect(function() local Camera = workspace.CurrentCamera Camera.CFrame = Camera.CFrame * CFrame.new(0, 0, 0, ConfigState.stretchHorizontal, 0, 0, 0, ConfigState.stretchVertical, 0, 0, 0, 1) end) end end end CameraStretchVerticalInput = Tabs.Visuals:Input({ Title = "Camera Stretch Vertical", Flag = "CameraStretchVerticalInput", Placeholder = "0.80", Numeric = true, Value = tostring(ConfigState.stretchVertical), }) CameraStretchVerticalInput.Callback = function(value) local num = tonumber(value) if num then ConfigState.stretchVertical = num if ConfigState.cameraStretchConnection then ConfigState.cameraStretchConnection:Disconnect() ConfigState.cameraStretchConnection = game:GetService("RunService").RenderStepped:Connect(function() local Camera = workspace.CurrentCamera Camera.CFrame = Camera.CFrame * CFrame.new(0, 0, 0, ConfigState.stretchHorizontal, 0, 0, 0, ConfigState.stretchVertical, 0, 0, 0, 1) end) end end end Tabs.Visuals:Space() DisableFadeeffectToggle = Tabs.Visuals:Toggle({ Title = "Disable Fade effect", Flag = "DisableFadeeffectToggle", Value = false, }) DisableFadeeffectToggle.Callback = function(state) ConfigState.fadeEnabled = state if ConfigState.fadeConnection then ConfigState.fadeConnection:Disconnect() ConfigState.fadeConnection = nil end local coverScreen = PlayerGui:FindFirstChild("Shared") if coverScreen then coverScreen = coverScreen:FindFirstChild("Popups") if coverScreen then coverScreen = coverScreen:FindFirstChild("CoverScreen") end end if not coverScreen then return end if state then coverScreen.Visible = false ConfigState.fadeConnection = coverScreen:GetPropertyChangedSignal("Visible"):Connect(function() if ConfigState.fadeEnabled and coverScreen.Visible == true then coverScreen.Visible = false end end) else coverScreen.Visible = true end end Tabs.Visuals:Space() FullBrightToggle = Tabs.Visuals:Toggle({ Title = "Full Bright", Flag = "FullBrightToggle", Desc = "Ya Like drinking Night Vision while mining in da cave and sceard of creeper blow you up dawg?", Value = false, }) FullBrightToggle.Callback = function(state) ConfigState.FullBright = state if state then ConfigState.originalBrightness = Lighting.Brightness ConfigState.originalAmbient = Lighting.Ambient ConfigState.originalOutdoorAmbient = Lighting.OutdoorAmbient originalColorShiftBottom = Lighting.ColorShift_Bottom originalColorShiftTop = Lighting.ColorShift_Top local function applyFullBright() if Lighting.Brightness ~= 1 then Lighting.Brightness = 1 end if Lighting.Ambient ~= Color3.new(1, 1, 1) then Lighting.Ambient = Color3.new(1, 1, 1) end if Lighting.OutdoorAmbient ~= Color3.new(1, 1, 1) then Lighting.OutdoorAmbient = Color3.new(1, 1, 1) end if Lighting.ColorShift_Bottom ~= Color3.new(1, 1, 1) then Lighting.ColorShift_Bottom = Color3.new(1, 1, 1) end if Lighting.ColorShift_Top ~= Color3.new(1, 1, 1) then Lighting.ColorShift_Top = Color3.new(1, 1, 1) end end applyFullBright() if fullBrightConnection then fullBrightConnection:Disconnect() end fullBrightConnection = RunService.Heartbeat:Connect(function() if ConfigState.FullBright then applyFullBright() end end) fullBrightCharConnection = game.Players.LocalPlayer.CharacterAdded:Connect(function() task.wait(1) if ConfigState.FullBright then applyFullBright() end end) else if fullBrightConnection then fullBrightConnection:Disconnect() fullBrightConnection = nil end if fullBrightCharConnection then fullBrightCharConnection:Disconnect() fullBrightCharConnection = nil end if ConfigState.originalBrightness then Lighting.Brightness = ConfigState.originalBrightness Lighting.Ambient = ConfigState.originalAmbient Lighting.OutdoorAmbient = ConfigState.originalOutdoorAmbient Lighting.ColorShift_Bottom = originalColorShiftBottom Lighting.ColorShift_Top = originalColorShiftTop end end end Tabs.Visuals:Space() NoFogToggle = Tabs.Visuals:Toggle({ Title = "Remove Fog", Flag = "NoFogToggle", Value = false, }) NoFogToggle.Callback = function(state) ConfigState.NoFog = state if state then EnableNoFog() else DisableNoFog() end end fu