nt = TimeDisplay local TimeGradient = Instance.new("UIGradient") TimeGradient.Color = ColorSequence.new({ ColorSequenceKeypoint.new(0, Color3.fromRGB(255, 255, 255)), ColorSequenceKeypoint.new(1, Color3.fromRGB(194, 194, 194)) }) TimeGradient.Rotation = 90 TimeGradient.Parent = TimeDisplay end local StatusLabel = MainTimer:FindFirstChild("About") if not StatusLabel then StatusLabel = Instance.new("TextLabel") StatusLabel.Name = "About" StatusLabel.FontFace = Font.new("rbxasset://fonts/families/GothamSSm.json", Enum.FontWeight.Bold, Enum.FontStyle.Normal) StatusLabel.Text = "ROUND ACTIVE" StatusLabel.TextColor3 = Color3.fromRGB(165, 194, 255) StatusLabel.TextScaled = true StatusLabel.TextSize = 14 StatusLabel.TextStrokeTransparency = 0.95 StatusLabel.TextWrapped = true StatusLabel.AnchorPoint = Vector2.new(0.5, 0.5) StatusLabel.BackgroundTransparency = 1 StatusLabel.Position = UDim2.new(0.5, 0, 0.25, 0) StatusLabel.Size = UDim2.new(0.8, 0, 0.25, 0) StatusLabel.ZIndex = 3 StatusLabel.Parent = MainTimer local StatusStroke = Instance.new("UIStroke") StatusStroke.Thickness = 2 StatusStroke.Transparency = 0.7 StatusStroke.Parent = StatusLabel local StatusGradient = Instance.new("UIGradient") StatusGradient.Color = ColorSequence.new({ ColorSequenceKeypoint.new(0, Color3.fromRGB(255, 255, 255)), ColorSequenceKeypoint.new(1, Color3.fromRGB(194, 194, 194)) }) StatusGradient.Rotation = 90 StatusGradient.Parent = StatusLabel end local MainTimerStroke = MainTimer:FindFirstChildOfClass("UIStroke") if not MainTimerStroke then MainTimerStroke = Instance.new("UIStroke") MainTimerStroke.Transparency = 0.8 MainTimerStroke.Parent = MainTimer end local MainTimerImage = MainTimer:FindFirstChildOfClass("ImageLabel") if not MainTimerImage then MainTimerImage = Instance.new("ImageLabel") MainTimerImage.Name = "Background" MainTimerImage.Image = "rbxassetid://196969716" MainTimerImage.ImageColor3 = Color3.fromRGB(21, 21, 21) MainTimerImage.ImageTransparency = 0.7 MainTimerImage.AnchorPoint =