gState.TimerGUI = createTimerGUI() end end function GetRoundTitle(roundName) if not roundName or roundName == "" then return "" end local specialRoundsFolder = ReplicatedStorage:FindFirstChild("Info") if not specialRoundsFolder then return roundName end specialRoundsFolder = specialRoundsFolder:FindFirstChild("SpecialRounds") if not specialRoundsFolder then return roundName end local roundModule = specialRoundsFolder:FindFirstChild(roundName) if not roundModule then return roundName end local moduleData = require(roundModule) if moduleData and moduleData.Title then return moduleData.Title end return roundName end function SetTime(seconds) if not ConfigState.TimerGUI then return end if type(seconds) == "number" then local minutes = math.floor(seconds / 60) local remainingSeconds = math.floor(seconds % 60) ConfigState.TimerGUI.TimeDisplay.Text = string.format("%d:%02d", minutes, remainingSeconds) if seconds <= 5 then ConfigState.TimerGUI.TimeDisplay.TextColor3 = Color3.fromRGB(215, 100, 100) ConfigState.TimerGUI.StatusLabel.TextColor3 = Color3.fromRGB(215, 100, 100) if ConfigState.TimerGUI.MainTimerStroke then ConfigState.TimerGUI.MainTimerStroke.Color = Color3.fromRGB(255, 138, 138) end if ConfigState.TimerGUI.MainTimerImage then ConfigState.TimerGUI.MainTimerImage.ImageColor3 = Color3.fromRGB(255, 138, 138) end else ConfigState.TimerGUI.TimeDisplay.TextColor3 = Color3.fromRGB(165, 194, 255) ConfigState.TimerGUI.StatusLabel.TextColor3 = Color3.fromRGB(165, 194, 255) if ConfigState.TimerGUI.MainTimerStroke then ConfigState.TimerGUI.MainTimerStroke.Color = Color3.fromRGB(165, 194, 255) end if ConfigState.TimerGUI.MainTimerImage then ConfigState.TimerGUI.MainTimerImage.ImageColor3 = Color3.fromRGB(21, 21, 21) end end else ConfigState.TimerGUI.TimeDisplay.Text = tostring(seconds) end end function SetSpecialRound(roundName) if not ConfigState.TimerGUI then return end if roundName and roundName ~= "" then ConfigState.CurrentSpecialRoundName = roundName local roundTitle = GetRoundTitle(roundName) ConfigState.TimerGUI.SpecialRoundLabel.Text = roundTitle ConfigState.TimerGUI.SpecialRound.Visible = ConfigState.SpecialRoundEnabled else ConfigState.CurrentSpecialRoundName = "" ConfigState.TimerGUI.SpecialRound.Visible = false end end function SetStatus(text) if not ConfigState.TimerGUI then return end ConfigState.TimerGUI.StatusLabel.Text = text:upper() end function SetTimerVisible(visible) ConfigState.TimerEnabled = visible ConfigState.OriginalTimerVisible = visible if ConfigState.CheckingGameTimer then CheckGameTimerVisibility() else if ConfigState.TimerGUI then ConfigState.TimerGUI.MainTimer.Visible = visible end end end function SetSpecialRoundVisible(visible) ConfigState.SpecialRoundEnabled = visible if ConfigState.TimerGUI and visible and ConfigState.CurrentSpecialRoundName ~= "" then ConfigState.TimerGUI.SpecialRound.Visible = true elseif ConfigState.TimerGUI then ConfigState.TimerGUI.SpecialRound.Visible = false end end function CheckGameTimerVisibility() if not ConfigState.TimerEnabled or not ConfigState.TimerGUI then if ConfigState.TimerGUI then ConfigState.TimerGUI.MainTimer.Visible = false end return end local hud = PlayerGui:FindFirstChild("Shared") if not hud then ConfigState.TimerGUI.MainTimer.Visible = ConfigState.OriginalTimerVisible return end hud = hud:FindFirstChild("HUD") if not hud then ConfigState.TimerGUI.MainTimer.Visible = ConfigState.OriginalTimerVisible return end hud = hud:FindFirstChild("Overlay") if not hud then ConfigState.TimerGUI.MainTimer.Visible = ConfigState.OriginalTimerVisible return end hud = hud:FindFirstChild("Default") if not hud then ConfigState.TimerGUI.MainTimer.Visible = ConfigState.OriginalTimerVisible return end hud = hud:FindFirstChild("RoundOverlay") if not hud then ConfigState.TimerGUI.MainTimer.Visible = ConfigState.OriginalTimerVisible return end hud = hud:FindFirstChild("Round") if not hud then ConfigState.TimerGUI.MainTimer.Visible = ConfigState.OriginalTimerVisible return end local roundTimer = hud:FindFirstChild("RoundTimer") if not roundTimer then ConfigState.TimerGUI.MainTimer.Visible = ConfigState.OriginalTimerVisible return end if roundTimer.Visible then ConfigState.TimerGUI.MainTimer.Visible = false else ConfigState.TimerGUI.MainTimer.Visible = ConfigState.OriginalTimerVisible end end function StartGameTimerCheck() if ConfigState.CheckingGameTimer then return end ConfigState.CheckingGameTimer = true local last = 0 ConfigState._gameTimerConnection = RunService.Heartbeat:Connect(function() local now = os.clock() if now - last < 0.1 then return end last = now CheckGameTimerVisibility() end) end function StopGameTimerCheck() ConfigState.CheckingGameTimer = false if ConfigState._gameTimerConnection then ConfigState._gameTimerConnection:Disconnect() ConfigState._gameTimerConnection = nil end if ConfigState.TimerGUI then ConfigState.TimerGUI.MainTimer.Visible = ConfigState.OriginalTimerVisible end end function UpdateFromAttributes() local timerValue = ServerStateRegistryService.Registry.Time local specialRoundValue = ServerStateRegistryService.Registry.SpecialRound local roundStatus = ServerStateRegistryService.Registry.RoundStatus if timerValue and timerValue ~= - 1 then SetTime(timerValue) end if roundStatus == 2 then SetStatus("Round Active") elseif roundStatus == 1 or roundStatus == 0 then SetStatus("Intermission") else SetStatus("nil") end if specialRoundValue and specialRoundValue ~= false then SetSpecialRound(tostring(specialRoundValue)) else SetSpecialRound("") end end function StartAttributeMonitor() StopAttributeMonitor() local lastTimer = ServerStateRegistryService.Registry.Time local lastRoundStatus = ServerStateRegistryService.Registry.RoundStatus local lastSpecialRound = ServerStateRegistryService.Registry.SpecialRound ConfigState._attributeConnection = RunService.Heartbeat:Connect(function() local currentTimer = ServerStateRegistryService.Registry.Time local currentRoundStatus = ServerStateRegistryService.Registry.RoundStatus local currentSpecialRound = ServerStateRegistryService.Registry.SpecialRound if currentTimer ~= lastTimer or currentRoundStatus ~= lastRoundStatus or currentSpecialRound ~= lastSpecialRound then lastTimer = currentTimer lastRoundStatus = currentRoundStatus lastSpecialRound = currentSpecialRound UpdateFromAttributes() end end) UpdateFromAttributes() end function StopAttributeMonitor() if ConfigState._attributeConnection then ConfigState._attributeConnection:Disconnect() ConfigState._attributeConnection = nil end if ConfigState._attributeConnection2 then ConfigState._attributeConnection2:Disconnect() ConfigState._attributeConnection2 = nil end if ConfigState._attributeConnection3 then ConfigState._attributeConnection3:Disconnect() ConfigState._attributeConnection3 = nil end end function handleTimerToggles() local timerOn = ConfigState.TimerEnabled local specialOn = ConfigState.SpecialRoundEnabled if not timerOn and not specialOn then destroyTimerGUI() else ensureTimerGUI() if timerOn then SetTimerVisible(true) StartAttributeMonitor() StartGameTimerCheck() end if specialOn then SetSpecialRoundVisible(true) end end end Tabs.Visuals:Space() TimerDisplayToggle = Tabs.Visuals:Toggle({ Title = "Timer Display", Flag = "TimerDisplayToggle", Value = false, }) TimerDisplayToggle.Callback = function(state) ConfigState.TimerEnabled = state handleTimerToggles() end Tabs.Visuals:Space() SpecialRoundToggle = Tabs.Visuals:Toggle({ Title = "Special Round Display", Flag = "SpecialRoundToggle", Value = false, }) SpecialRoundToggle.Callback = function(state) ConfigState.SpecialRoundEnabled = state handleTimerToggles() end Tabs.Visuals:Space() function PlayerStatsStart() ConfigState.StatScreenUI = Instance.new("ScreenGui") ConfigState.StatScreenUI.Name = "Player Stat Gui" ConfigState.StatScreenUI.ResetOnSpawn = false ConfigState.StatScreenUI.IgnoreGuiInset = false ConfigState.StatScreenUI.DisplayOrder = 2147 local player_stat_frame = Instance.new("Frame") player_stat_frame.Name = "Player Stat Frame" player_stat_frame.Size = UDim2.fromScale(1, 1) player_stat_frame.Position = UDim2.fromScale(0, 0) player_stat_frame.BackgroundTransparency = 1 player_stat_frame.Parent = ConfigState.StatScreenUI local HomePage = PlayerGui:WaitForChild("HomePage") local OG_PlayerStats = HomePage:WaitForChild("Root"):WaitForChild("Bottom") OG_PlayerStats.Archivable = true local cloned_playerStats = OG_PlayerStats:Clone() cloned_playerStats.Parent = player_stat_frame ConfigState.StatScreenUI.Parent = PlayerGui for _, descendant in ipairs(cloned_playerStats:GetDescendants()) do if descendant:IsA("GuiObject") then if descendant.Visible == false then descendant.Visible = true end if descendant.Active == true then descendant.Active = false end if descendant.Name == "Plus" then descendant:Destroy() end end end local function FindClonedStat(originalDescendant) local relativePath = {} local current = originalDescendant for _ = 1, 100 do if not current or current == OG_PlayerStats then break end table.insert(relativePath, 1, current.Name) current = current.Parent end local targetClone = cloned_playerStats for _, name in ipairs(relativePath) do targetClone = targetClone:FindFirstChild(name) if not targetClone then break end end return targetClone end local function StatBindSync(originalInstance) local connection = originalInstance.Changed:Connect(function(property) if property == "Parent" then return end local matchingClone = FindClonedStat(originalInstance) if matchingClone then pcall(function() matchingClone[property] = originalInstance[property] if matchingClone:IsA("GuiObject") and property == "Visible" then matchingClone.Visible = true end end) end end) table.insert(ConfigState.PlayerStatConnection, connection) end for _, descendant in ipairs(OG_PlayerStats:GetDescendants()) do StatBindSync(descendant) end local descendantAddedConnection = OG_PlayerStats.DescendantAdded:Connect(function(descendant) StatBindSync(descendant) task.defer(function() local parentClone = FindClonedStat(descendant.Parent) if parentClone and not parentClone:FindFirstChild(descendant.Name) and not (descendant.Name == "Plus") then local newClone = descendant:Clone() if newClone:IsA("GuiObject") then newClone.Visible = true end newClone.Parent = parentClone end end) end) table.insert(ConfigState.PlayerStatConnection, descendantAddedConnection) end function PlayerStatsStop() for key, connection in pairs(ConfigState.PlayerStatConnection) do if typeof(connection) == "RBXScriptConnection" then if connection.Connected then connection:Disconnect() end end ConfigState.PlayerStatConnection[key] = nil end if ConfigState.StatScreenUI then ConfigState.StatScreenUI:Destroy() ConfigState.StatScreenUI = nil end end VisualsStatUI = Tabs.Visuals:Toggle({ Title = "Show Player Stats", Value = false }) VisualsStatUI.Callback = function(s) if s then PlayerStatsStart() else PlayerStatsStop() end end Tabs.Visuals:Space() function ForceDeathFeed() if ConfigState.originalDeathFeedFunctions.Set then return end ConfigState.originalDeathFeedFunctions.Set = DeathFeed.Set ConfigState.originalDeathFeedFunctions.CharacterDiedSimple = DeathFeed.CharacterDiedSimple DeathFeed.Set = function(self, eventType, data) if eventType == "Death" then self:CharacterDied(data) else ConfigState.originalDeathFeedFunctions.Set(self, eventType, data) end end DeathFeed.CharacterDiedSimple = function(self, data) return self:CharacterDied(data) end end function RestoreOldDeathFeed() if not ConfigState.originalDeathFeedFunctions.Set then return end DeathFeed.Set = ConfigState.originalDeathFeedFunctions.Set DeathFeed.CharacterDiedSimple = ConfigState.originalDeathFeedFunctions.CharacterDiedSimple ConfigState.originalDeathFeedFunctions.Set = nil ConfigState.originalDeathFeedFunctions.CharacterDiedSimple = nil end AlwaysShowDeathFeed = Tabs.Visuals:Toggle({ Title = "Always Show Death Feed", }) AlwaysShowDeathFeed.Callback = function(s) if s then ForceDeathFeed() else RestoreOldDeathFeed() end end function scanDescendantsAsync(root, matchFolderName, targetName, callback) local stack = {} for _, child in ipairs(root:GetChildren()) do table.insert(stack, child) end local found = nil local scanConn scanConn = game:GetService("RunService").Heartbeat:Connect(function() for _ = 1, 100 do if # stack == 0 or found then scanConn:Disconnect() callback(found) return end local node = table.remove(stack) if node:IsA("Folder") or node:IsA("Model") then if matchFolderName and node.Name == matchFolderName then local function findInFolder(folder, name) for _, child in ipairs(folder:GetChildren()) do if child.Name == name then return child end local result = findInFolder(child, name) if result then return result end end return nil end local innerResult = findInFolder(node, targetName) if innerResult then found = innerResult break end elseif not matchFolderName and node.Name == targetName then found = node break else for _, child in ipairs(node:GetChildren()) do table.insert(stack, child) end end end end end) end Tabs.Visuals:Section({ Title = "Cosmetic Changer", TextSize = 20 }) Tabs.Visuals:Divider() local EquippedCodec = CosmeticModules.EquippedCodec local InventoryService = CosmeticModules.InventoryService local LoadoutConfig = CosmeticModules.LoadoutConfig local RigService = CosmeticModules.RigService local AddCosmetics = CosmeticModules.AddCosmetics local DataRegistryClass = CosmeticModules.DataRegistryClass local RigClass = CosmeticModules.RigClass local cosmeticOrigStoreGet = InventoryStore.Get local cosmeticOrigServerToClient local cosmeticOrigBuildRig local cosmeticOrigSetRig local cosmeticItemIndex function CosmeticNotify(title, message, good) WindUI:Notify({ Title = title, Content = '<font color="' .. (good and "#00ff88" or "#ff3030") .. '">' .. message .. "</font>", Duration = 5 }) end function CosmeticBuildIndex() if cosmeticItemIndex then return cosmeticItemIndex end cosmeticItemIndex = { ByName = {}, ById = {} } for key, entry in pairs(ItemRegistry.GetAll()) do local id = type(entry) == "table" and entry.Id or key local module = type(entry) == "table" and entry.Module if type(id) == "number" and typeof(module) == "Instance" then local record = { Id = id, Module = module, Categories = entry.Categories or {} } cosmeticItemIndex.ById[id] = record local lowered = module.Name:lower() cosmeticItemIndex.ByName[lowered] = cosmeticItemIndex.ByName[lowered] or {} table.insert(cosmeticItemIndex.ByName[lowered], record) local ok, info = pcall(require, module) local display = ok and type(info) == "table" and type(info.AppearanceInfo) == "table" and info.AppearanceInfo.Name if type(display) == "string" then local displayLowered = display:lower() if displayLowered ~= lowered then cosmeticItemIndex.ByName[displayLowered] = cosmeticItemIndex.ByName[displayLowered] or {} table.insert(cosmeticItemIndex.ByName[displayLowered], record) end end end end return cosmeticItemIndex end function CosmeticItemTypeOf(record) local slotType = InventoryService.GetItemSlotType(record.Id) if slotType then return slotType end local ok, result = pcall(ClientItemService.GetItemType, ClientItemService, record.Module) if ok then return result end return nil end function CosmeticResolveItem(input, accepted) local text = string.match(input or "", "^%s*(.-)%s*$") if text == "" then return nil, "empty" end local index = CosmeticBuildIndex() local candidates = {} local numeric = tonumber(text) if numeric and index.ById[numeric] then candidates[1] = index.ById[numeric] else candidates = index.ByName[text:lower()] or {} end if # candidates == 0 then return nil, '"' .. text .. '" was not found' end local wrongType for _, record in ipairs(candidates) do local kind = CosmeticItemTypeOf(record) if kind and accepted[kind] then return record, nil, kind end wrongType = wrongType or kind end return nil, '"' .. text .. '" is a ' .. tostring(wrongType or "unknown type") .. " item, wrong slot" end function CosmeticSlotKeyFor(slot) local keys = {} for key, slotType in pairs(InventoryService.GetSlots()) do if slotType == slot.Type then table.insert(keys, key) end end table.sort(keys) return keys[slot.Index] end function CosmeticSlotIdFor(slot) local key = CosmeticSlotKeyFor(slot) return key and LoadoutConfig.Ids[key] or nil end function CosmeticRealEquipped(slot) local id = CosmeticSlotIdFor(slot) if not id then return nil end return EquippedCodec.Get(cosmeticOrigStoreGet(InventoryStore, "Equipped"), id) end function CosmeticGetLocal() local character = CharacterService:GetLocalCharacter() if character and character.Rig and character.DataRegistry and character.Model then return character end return nil end function CosmeticCompose() if ConfigState.cosmeticState.Blank then return {}, 0, nil end local drop = {} for index in pairs(ConfigState.cosmeticState.Overlay) do if ConfigState.cosmeticLayout[index].Type ~= "Boombox" then local real = CosmeticRealEquipped(ConfigState.cosmeticLayout[index]) if real then drop[real] = true end end end local list = {} for _, id in ipairs(ConfigState.cosmeticState.Real.Cosmetics or {}) do if not drop[id] then table.insert(list, id) end end for index, slot in ipairs(ConfigState.cosmeticLayout) do local chosen = ConfigState.cosmeticState.Overlay[index] if chosen and slot.Type ~= "Boombox" then table.insert(list, chosen.Id) end end local boombox = ConfigState.cosmeticState.Real.Boombox local boomboxIndex for index, slot in ipairs(ConfigState.cosmeticLayout) do if slot.Type == "Boombox" then boomboxIndex = index end end if boomboxIndex and ConfigState.cosmeticState.Overlay[boomboxIndex] then boombox = ConfigState.cosmeticState.Overlay[boomboxIndex].Id end local rigTerm for index, slot in ipairs(ConfigState.cosmeticLayout) do if slot.Type == "Character" and ConfigState.cosmeticState.Overlay[index] then local module = ConfigState.cosmeticState.Overlay[index].Module local modern = module:FindFirstChild("Character") ~= nil local classic = module:FindFirstChild("CharacterClassic") ~= nil if modern and not classic then rigTerm = Enum.HumanoidRigType.R15 elseif classic and not modern then rigTerm = Enum.HumanoidRigType.R6 end end end return list, boombox or 0, rigTerm end function CosmeticOverlaidBuffer(buffer) local result = buffer for index, slot in ipairs(ConfigState.cosmeticLayout) do local id = CosmeticSlotIdFor(slot) if id then local chosen = ConfigState.cosmeticState.Overlay[index] if chosen then result = EquippedCodec.With(result, id, chosen.Id) elseif ConfigState.cosmeticState.Blank then result = EquippedCodec.With(result, id, nil) end end end return result end function CosmeticNotifyEquipped(old, new) local fields = InventoryStore._fields local field = fields and fields.Equipped if not field then return end local changed = {} for _, slot in ipairs(ConfigState.cosmeticLayout) do local id = CosmeticSlotIdFor(slot) if id then changed[id] = true end end for listener in pairs(field.Listeners) do local callback = listener.Callback if listener.Key == nil then task.spawn(callback, new, old, changed) elseif changed[listener.Key] then task.spawn(callback, field.ReadKey(new, listener.Key)) end end end function CosmeticChangePlayerData(change) local old = InventoryStore:Get("Equipped") change() local new = InventoryStore:Get("Equipped") pcall(CosmeticNotifyEquipped, old, new) end function CosmeticRigModelOf() local character = CosmeticGetLocal() local rig = character and character.Rig and character.Rig.Rig return rig, rig and rig.Model end function CosmeticApplyToRig(id) local rig, model = CosmeticRigModelOf() if not model then return nil, "Your character rig is not ready" end local before = {} for _, descendant in ipairs(model:GetDescendants()) do before[descendant] = true end local mount = rig.BoomboxAsset and (rig.BoomboxAsset:FindFirstChildOfClass("MeshPart") or rig.BoomboxAsset:FindFirstChildOfClass("Part")) local ok, err = pcall(AddCosmetics, model, { id }, mount) if not ok then return nil, tostring(err) end local added = {} for _, descendant in ipairs(model:GetDescendants()) do if not before[descendant] then table.insert(added, descendant) end end return added end function CosmeticRestoreSpawned() local _, model = CosmeticRigModelOf() if not model then return end for _, record in ipairs(ConfigState.cosmeticState.Spawned) do local alive = false for _, instance in ipairs(record.Instances) do if instance.Parent and instance:IsDescendantOf(model) then alive = true break end end if not alive then local added = CosmeticApplyToRig(record.Id) if added then record.Instances = added end end end end function CosmeticEnsureHooks() if ConfigState.cosmeticState.Hooked then return true end local character = CosmeticGetLocal() if character then local data = character.DataRegistry.Data ConfigState.cosmeticState.Real = { Cosmetics = data.Cosmetics, Boombox = data.Boombox, Rig = data.Rig } end cosmeticOrigServerToClient = DataRegistryClass.ServerToClient DataRegistryClass.ServerToClient = function(self, incoming) local parent = self.Parent if parent and parent.Local and type(incoming) == "table" and (incoming.Cosmetics ~= nil or incoming.Boombox ~= nil or incoming.Rig ~= nil) then if incoming.Cosmetics ~= nil then ConfigState.cosmeticState.Real.Cosmetics = incoming.Cosmetics end if incoming.Boombox ~= nil then ConfigState.cosmeticState.Real.Boombox = incoming.Boombox end if incoming.Rig ~= nil then ConfigState.cosmeticState.Real.Rig = incoming.Rig end local patched = table.clone(incoming) local list, boombox, rigTerm = CosmeticCompose() if incoming.Cosmetics ~= nil then patched.Cosmetics = list end if incoming.Boombox ~= nil then patched.Boombox = boombox end if incoming.Rig ~= nil and rigTerm then patched.Rig = rigTerm end return cosmeticOrigServerToClient(self, patched) end return cosmeticOrigServerToClient(self, incoming) end cosmeticOrigBuildRig = RigClass.BuildRig RigClass.BuildRig = function(self, ...) local wasBuilt = self.Built local result = cosmeticOrigBuildRig(self, ...) if not wasBuilt and self.Built and self.Parent and self.Parent.Local and # ConfigState.cosmeticState.Spawned > 0 then task.defer(CosmeticRestoreSpawned) end return result end cosmeticOrigSetRig = RigService.SetRig RigService.SetRig = function(self, model, rigType, cosmetics, gear, boombox) if # ConfigState.cosmeticState.Spawned > 0 and typeof(model) == "Instance" and model:GetAttribute(RigService.PreviewAttribute) and type(cosmetics) == "table" then local merged = table.clone(cosmetics) for _, record in ipairs(ConfigState.cosmeticState.Spawned) do table.insert(merged, record.Id) end cosmetics = merged end return cosmeticOrigSetRig(self, model, rigType, cosmetics, gear, boombox) end pcall(function() InventoryStore.Get = function(self, key) local value = cosmeticOrigStoreGet(self, key) if key == "Equipped" and (next(ConfigState.cosmeticState.Overlay) ~= nil or ConfigState.cosmeticState.Blank) then return CosmeticOverlaidBuffer(value) or buffer.create(0) end return value end end) ConfigState.cosmeticState.Hooked = true return true end function CosmeticReleaseHooks() if not ConfigState.cosmeticState.Hooked then return end DataRegistryClass.ServerToClient = cosmeticOrigServerToClient RigClass.BuildRig = cosmeticOrigBuildRig RigService.SetRig = cosmeticOrigSetRig pcall(rawset, InventoryStore, "Get", nil) ConfigState.cosmeticState.Hooked = false end function CosmeticReleaseIfIdle() if next(ConfigState.cosmeticState.Overlay) == nil and not ConfigState.cosmeticState.Blank and # ConfigState.cosmeticState.Spawned == 0 then CosmeticReleaseHooks() end end function CosmeticDestroySpawned() for _, record in ipairs(ConfigState.cosmeticState.Spawned) do for _, instance in ipairs(record.Instances) do if instance.Parent then instance:Destroy() end end end table.clear(ConfigState.cosmeticState.Spawned) end for index, slot in ipairs(ConfigState.cosmeticLayout) do local input = Tabs.Visuals:Input({ Title = slot.Title, Placeholder = "Item name or ID" }) input.Callback = function(value) ConfigState.cosmeticInputs[index] = value end end Tabs.Visuals:Button({ Title = "Apply", Icon = "check", Callback = function() task.spawn(function() local chosen = {} local errors = {} local filled = 0 for index, slot in ipairs(ConfigState.cosmeticLayout) do local text = ConfigState.cosmeticInputs[index] or "" if string.match(text, "%S") then filled = filled + 1 local record, err = CosmeticResolveItem(text, { [slot.Type] = true }) if record then chosen[index] = record else table.insert(errors, slot.Title .. ": " .. err) end end end if filled == 0 then CosmeticNotify("Cosmetic Changer", "Fill at least one slot first", false) return end if # errors > 0 then CosmeticNotify("Cosmetic Changer", "Nothing applied<br/>" .. table.concat(errors, "<br/>"), false) return end CosmeticEnsureHooks() CosmeticChangePlayerData(function() ConfigState.cosmeticState.Overlay = chosen ConfigState.cosmeticState.Blank = false end) CosmeticNotify("Cosmetic Changer", "Saved " .. filled .. " slot" .. (filled > 1 and "s" or "") .. ", applies on next spawn", true) end) end }) Tabs.Visuals:Button({ Title = "Unhook & Reset", Icon = "rotate-ccw", Color = Color3.fromHex("#FF3030"), Callback = function() task.spawn(function() if not ConfigState.cosmeticState.Hooked then CosmeticNotify("Cosmetic Changer", "Nothing to reset", false) return end CosmeticChangePlayerData(function() table.clear(ConfigState.cosmeticState.Overlay) ConfigState.cosmeticState.Blank = false end) CosmeticReleaseIfIdle() CosmeticNotify("Cosmetic Changer", "Default data restored, applies on next spawn", true) end) end }) Tabs.Visuals:Space() Tabs.Visuals:Section({ Title = "Cosmetic Spawner", TextSize = 20 }) Tabs.Visuals:Divider() local cosmeticSpawnInput = Tabs.Visuals:Input({ Title = "Enter Your Cosmetic Name", Placeholder = "Item name or ID" }) cosmeticSpawnInput.Callback = function(value) ConfigState.cosmeticSpawnName = value end Tabs.Visuals:Button({ Title = "Spawn", Icon = "plus", Callback = function() task.spawn(function() local accepted = {} for _, slot in ipairs(ConfigState.cosmeticLayout) do if slot.Type ~= "Character" and slot.Type ~= "Boombox" then accepted[slot.Type] = true end end local record, err = CosmeticResolveItem(ConfigState.cosmeticSpawnName, accepted) if not record then CosmeticNotify("Cosmetic Spawner", err == "empty" and "Enter a cosmetic name first" or err, false) return end CosmeticEnsureHooks() local added = CosmeticApplyToRig(record.Id) table.insert(ConfigState.cosmeticState.Spawned, { Id = record.Id, Instances = added or {} }) local suffix = added and "" or ", it will appear on spawn" CosmeticNotify("Cosmetic Spawner", "Spawned " .. record.Module.Name .. suffix, true) end) end }) Tabs.Visuals:Button({ Title = "Remove All", Icon = "eraser", Callback = function() task.spawn(function() CosmeticEnsureHooks() CosmeticDestroySpawned() CosmeticChangePlayerData(function() table.clear(ConfigState.cosmeticState.Overlay) ConfigState.cosmeticState.Blank = true end) CosmeticNotify("Cosmetic Spawner", "Everything removed, applies on next spawn", true) end) end }) Tabs.Visuals:Button({ Title = "Remove Spawned", Icon = "trash-2", Callback = function() task.spawn(function() CosmeticDestroySpawned() CosmeticReleaseIfIdle() CosmeticNotify("Cosmetic Spawner", "Spawned cosmetics removed", true) end) end }) Tabs.Visuals:Button({ Title = "Reset", Icon = "rotate-ccw", Color = Color3.fromHex("#FF3030"), Callback = function() task.spawn(function() if not ConfigState.cosmeticState.Hooked then CosmeticNotify("Cosmetic Spawner", "Nothing to reset", false) return end CosmeticDestroySpawned() CosmeticChangePlayerData(function() table.clear(ConfigState.cosmeticState.Overlay) ConfigState.cosmeticState.Blank = false end) CosmeticReleaseHooks() CosmeticNotify("Cosmetic Spawner", "Unhooked, default data restored on next spawn", true) end) end }) Tabs.Visuals:Section({ Title = "Nametag Changer", TextSize = 20 }) function NametagCollect() ConfigState.nametagIdByName = {} local names = {} for _, category in ipairs(ItemRegistry.GetCategories()) do local lower = category:lower() if lower:find("nametag") or lower == "tag" or lower == "tags" then for id, entry in pairs(ItemRegistry.GetByCategory(category)) do local name = entry.Module.Name if ConfigState.nametagIdByName[name] then name = name .. " (" .. id .. ")" end ConfigState.nametagIdByName[name] = id table.insert(names, name) end end end table.sort(names) return names end function NametagValues() local names = NametagCollect() if # names == 0 then return {"No nametags found"} end return names end function NametagApply() local character = CharacterService:GetCharacterFromPlayer(LocalPlayer) local model = LocalPlayer.Character if not character or not model then return end local registry = character.DataRegistry if ConfigState.nametagOriginal.registry ~= registry or ConfigState.nametagOriginal.model ~= model then ConfigState.nametagOriginal = { registry = registry, model = model, tag = registry:Get("Nametag"), name = model:GetAttribute("DisplayName") } end if ConfigState.nametagId and registry:Get("Nametag") ~= ConfigState.nametagId then registry:Set("Nametag", ConfigState.nametagId) end if ConfigState.nametagName ~= "" and model:GetAttribute("DisplayName") ~= ConfigState.nametagName then model:SetAttribute("DisplayName", ConfigState.nametagName) end end function NametagRestoreDisplayName() local original = ConfigState.nametagOriginal if original.model then pcall(function() original.model:SetAttribute("DisplayName", original.name) end) end end function NametagRestore() local original = ConfigState.nametagOriginal ConfigState.nametagOriginal = {} if not original.registry then return end pcall(function() original.registry:Set("Nametag", original.tag) end) pcall(function() original.model:SetAttribute("DisplayName", original.name) end) end function NametagStopLoop() if ConfigState.nametagConn then ConfigState.nametagConn:Disconnect() ConfigState.nametagConn = nil end end function NametagStartLoop() NametagStopLoop() ConfigState.nametagConn = HeartbeatLoop(0.25, function() NametagApply() end) end NametagChangerToggle = Tabs.Visuals:Toggle({ Title = "Enable Nametag Changer", Flag = "NametagChangerToggle", Value = false, }) NametagChangerToggle.Callback = function(state) ConfigState.nametagEnabled = state if state then NametagStartLoop() else NametagStopLoop() NametagRestore() end end NametagDropdown = Tabs.Visuals:Dropdown({ Title = "Nametag", Flag = "NametagChangerSelect", Values = NametagValues(), Callback = function(value) ConfigState.nametagId = ConfigState.nametagIdByName[value] end }) Tabs.Visuals:Button({ Title = "Refresh Nametag List", Icon = "refresh-cw", Callback = function() NametagDropdown:Refresh(NametagValues()) end }) NametagID = Tabs.Visuals:Input({ Title = "Nametag ID", Placeholder = "Item ID (optional)", NumbersOnly = true, }) NametagID.Callback = function(v) local id = tonumber(v) if id then ConfigState.nametagId = id end end CustomName = Tabs.Visuals:Input({ Title = "Custom Name", Placeholder = "Leave empty to keep your name", }) CustomName.Callback = function(v) ConfigState.nametagName = v if v == "" then NametagRestoreDisplayName() end end Tabs.Visuals:Section({ Title = "Carry Animation Changer", TextSize = 20 }) Tabs.Visuals:Divider() function CarryAnimCollect() ConfigState.carryItems = {} ConfigState.carryNames = {} local itemsFolder = ReplicatedStorage:FindFirstChild("Items") if not itemsFolder then return end local function scan(parent, insideCarry) for _, child in ipairs(parent:GetChildren()) do if child:IsA("Folder") then scan(child, insideCarry or child.Name == "CarryAnimations") elseif insideCarry and child:IsA("ModuleScript") and child:GetAttribute("ID") then local name = child.Name local config = ItemRegistry.GetConfig(child:GetAttribute("ID")) if config and config.AppearanceInfo and config.AppearanceInfo.Name then name = config.AppearanceInfo.Name end if ConfigState.carryItems[name] then name = name .. " (" .. child:GetAttribute("ID") .. ")" end ConfigState.carryItems[name] = child table.insert(ConfigState.carryNames, name) end end end scan(itemsFolder, false) table.sort(ConfigState.carryNames) if # ConfigState.carryNames == 0 then ConfigState.carryNames = {"No carry animations found"} end end function CarryAnimResolve(module) if not module then return nil end local itemLoaded, item = pcall(function() return ClientItemService:GetItemFromID(module:GetAttribute("ID")) end) return itemLoaded and item or module end function RefreshCarryVisual() local character = CharacterService:GetCharacterFromPlayer(LocalPlayer) if not (character and character.Animations and character.DataRegistry) then return end local carrying = character.DataRegistry:Get("Carrying") if carrying and carrying ~= 0 then pcall(function() character.Animations:RegistryTermUpdated("Carrying") end) end end function CarryAnimStart() if ConfigState.originalSetCarry or not carryService then return end ConfigState.originalSetCarry = carryService.SetCarry carryService.SetCarry = function(self, character, item, p5, animations, carryingValue, rig) local isLocal = animations and animations.Parent and animations.Parent.Local if isLocal and ConfigState.selectedCarry then local isCarrier = carryingValue ~= nil if (isCarrier and ConfigState.replaceCarrier) or (not isCarrier and ConfigState.replaceCarried) then item = ConfigState.selectedCarry end end return ConfigState.originalSetCarry(self, character, item, p5, animations, carryingValue, rig) end end function CarryAnimStop() if ConfigState.originalSetCarry then carryService.SetCarry = ConfigState.originalSetCarry ConfigState.originalSetCarry = nil end end function CarryAnimUpdate() if ConfigState.replaceCarrier or ConfigState.replaceCarried then CarryAnimStart() else CarryAnimStop() end RefreshCarryVisual() end CarryAnimCollect() local carryDropdown = Tabs.Visuals:Dropdown({ Title = "Carry Animation", Flag = "CarryAnimationSelect", Values = ConfigState.carryNames, Callback = function(value) ConfigState.selectedCarry = CarryAnimResolve(ConfigState.carryItems[value]) CarryAnimUpdate() end }) CarryReplaceCarrier = Tabs.Visuals:Toggle({ Title = "Replace My Carry", Desc = "Visual only: changes the carry animation you see while you carry someone", Flag = "CarryReplaceCarrier", Value = false, }) CarryReplaceCarrier.Callback = function(state) ConfigState.replaceCarrier = state CarryAnimUpdate() end CarryReplaceCarried = Tabs.Visuals:Toggle({ Title = "Replace When Carried", Desc = "Visual only: applies the next time someone carries you", Flag = "CarryReplaceCarried", Value = false, }) CarryReplaceCarried.Callback = function(state) ConfigState.replaceCarried = state CarryAnimUpdate() end Tabs.Visuals:Button({ Title = "Refresh Carry List", Icon = "refresh-cw", Callback = function() CarryAnimCollect() carryDropdown:Refresh(ConfigState.carryNames) end }) Tabs.Visuals:Section({ Title = "Emote Changer", TextSize = 20 }) Tabs.Visuals:Divider() function EmoteChangerSet(emoteID) if not emoteID then return end local character = LocalPlayer.Character if not character then return end local tagValue = character:GetAttribute("Tag") if not tagValue then return end local tagBuf = buffer.create(2) buffer.writeu16(tagBuf, 0, tagValue) FireClient(UpdateCharacterDataRegistry, { buffer.fromstring("\24\1"), emoteID, tagBuf }) end for i = 1, 12 do ConfigState.currentEmotes[i] = "" ConfigState.selectEmotes[i] = "" end for i = 1, 12 do CurrentEmote = Tabs.Visuals:Input({ Title = "Current Emote" .. " " .. i, Placeholder = "Enter emote name or ID", }) CurrentEmote.Callback = function(v) ConfigState.currentEmotes[i] = v:gsub("%s+", "") end end Tabs.Visuals:Divider() for i = 1, 12 do SelectEmote = Tabs.Visuals:Input({ Title = "Select Emote" .. " " .. i, Placeholder = "Enter emote name or ID", }) SelectEmote.Callback = function(v) ConfigState.selectEmotes[i] = v:gsub("%s+", "") end end function EmoteChangerGetAll() local itemsFolder = ReplicatedStorage:FindFirstChild("Items") if not itemsFolder then return {} end local allEmotes = {} local function findEmotesFolders(parent) for _, child in ipairs(parent:GetChildren()) do if child:IsA("Folder") then if child.Name == "Emotes" then for _, emote in ipairs(child:GetChildren()) do if emote:IsA("ModuleScript") and emote:GetAttribute("ID") then table.insert(allEmotes, { Name = emote.Name, ID = emote:GetAttribute("ID") }) end end else findEmotesFolders(child) end end end end findEmotesFolders(itemsFolder) return allEmotes end function EmoteChangerFindInfo(emoteInput) if emoteInput == "" then return nil end local id = tonumber(emoteInput) if id then local config = ItemRegistry.GetConfig(id) if config then local allEmotes = EmoteChangerGetAll() for _, e in ipairs(allEmotes) do if e.ID == id then return { Name = e.Name, ID = id } end end return { Name = tostring(id), ID = id } else return nil end end local allEmotes = EmoteChangerGetAll() for _, emote in ipairs(allEmotes) do if emote.Name:lower() == emoteInput:lower() then return { Name = emote.Name, ID = emote.ID } end end return nil end function EmoteChangerBuildMapping() ConfigState.emoteReplacements = {} for i = 1, 12 do local currentInput = ConfigState.currentEmotes[i] or "" local selectInput = ConfigState.selectEmotes[i] or "" if currentInput ~= "" and selectInput ~= "" then local currentInfo = EmoteChangerFindInfo(currentInput) local selectInfo = EmoteChangerFindInfo(selectInput) if currentInfo and selectInfo then ConfigState.emoteReplacements[currentInfo.Name] = { select = selectInfo.Name, selectID = selectInfo.ID, slot = i } end end end end local origActivate = EmoteClass.Activate local origDeactivate = EmoteClass.Deactivate function EmoteChangerStartWatcher() if ConfigState.emoteHookActive then return end ConfigState.emoteHookActive = true EmoteClass.Activate = function(self, p2, p3) origActivate(self, p2, p3) local anim = self.Animations and self.Animations.Animation if anim and anim.IsPlaying and anim.Speed > 0 then if ConfigState.pendingWheelId and self.Character == LocalPlayer.Character then local wheelId = ConfigState.pendingWheelId ConfigState.pendingWheelId = nil ConfigState.lastEmoteName = self.EmoteModule and self.EmoteModule.Name RunService.Heartbeat:Wait() EmoteChangerSet(wheelId) return end local module = self.EmoteModule local currentEmote = module and module.Name or "Unknown" if currentEmote ~= ConfigState.lastEmoteName then if ConfigState.emoteReplacements[currentEmote] then local replacement = ConfigState.emoteReplacements[currentEmote] local selectID = replacement.selectID if selectID then ConfigState.lastEmoteName = currentEmote RunService.Heartbeat:Wait() EmoteChangerSet(selectID) end end ConfigState.lastEmoteName = currentEmote end end end EmoteClass.Deactivate = function(self, ...) origDeactivate(self, ...) ConfigState.lastEmoteName = nil end end function EmoteChangerStopWatcher() ConfigState.emoteHookActive = false EmoteClass.Activate = origActivate EmoteClass.Deactivate = origDeactivate ConfigState.lastEmoteName = nil end function EmoteChangerFindWheel() if not PopupService then return nil end for _, popup in ipairs(PopupService.PopupTypes) do if getmetatable(popup) == WheelClass then return popup end end end function EmoteChangerRefreshWheel() table.clear(ConfigState.wheelPairs) if ConfigState.wheelReplaceEnabled then for i = 1, 12 do local currentInput = ConfigState.currentEmotes[i] or "" local selectInput = ConfigState.selectEmotes[i] or "" if currentInput ~= "" and selectInput ~= "" then local currentInfo = EmoteChangerFindInfo(currentInput) local selectInfo = EmoteChangerFindInfo(selectInput) if currentInfo and selectInfo then ConfigState.wheelPairs[currentInfo.ID] = selectInfo.ID end end end end local wheel = EmoteChangerFindWheel() if wheel then WheelClass.SetEquipped(wheel, ConfigState.realEquipped) end end if WheelClass then local initialWheel = EmoteChangerFindWheel() if initialWheel and initialWheel.Emotes then ConfigState.realEquipped = initialWheel.Emotes end local origSetEquipped = WheelClass.SetEquipped local origKeyActivated = WheelClass.KeyActivated WheelClass.SetEquipped = function(self, equipped) ConfigState.realEquipped = equipped if not ConfigState.wheelReplaceEnabled then return origSetEquipped(self, equipped) end local merged = table.clone(equipped) for slot, id in pairs(equipped) do if ConfigState.wheelPairs[id] then merged[slot] = ConfigState.wheelPairs[id] end end return origSetEquipped(self, merged) end WheelClass.KeyActivated = function(self, slot) local realId = ConfigState.realEquipped[slot] local replacement = ConfigState.wheelReplaceEnabled and realId and ConfigState.wheelPairs[realId] if not replacement then return origKeyActivated(self, slot) end local shown = self.Emotes ConfigState.pendingWheelId = replacement self.Emotes = ConfigState.realEquipped origKeyActivated(self, slot) self.Emotes = shown task.delay(3, function() if ConfigState.pendingWheelId == replacement then ConfigState.pendingWheelId = nil end end) end end VisualsEmoteWheelToggle = Tabs.Visuals:Toggle({ Title = "Replace Emote Wheel", Type = "Checkbox", Flag = "ReplaceEmoteWheel", Value = false, }) VisualsEmoteWheelToggle.Callback = function(v) ConfigState.wheelReplaceEnabled = v if not v then EmoteChangerRefreshWheel() end end VisualsEmoteApply = Tabs.Visuals:Button({ Title = "Apply Emote Mappings", Icon = "refresh-cw", Callback = function() EmoteChangerRefreshWheel() local hasAnyEmote = false local incompleteSlots = {} local emptySlots = true for i = 1, 12 do local current = ConfigState.currentEmotes[i] or "" local select = ConfigState.selectEmotes[i] or "" if current ~= "" or select ~= "" then emptySlots = false if current ~= "" and select == "" then table.insert(incompleteSlots, string.format("Slot %d: Current set, Select missing", i)) elseif current == "" and select ~= "" then table.insert(incompleteSlots, string.format("Slot %d: Select set, Current missing", i)) else hasAnyEmote = true end end end if emptySlots then WindUI:Notify({ Title = "Emote Changer", Content = '<font color="#ffaa00"><font family="rbxasset://LuaPackages/Packages/_Index/BuilderIcons/BuilderIcons/BuilderIcons.json" weight="Regular">triangle-exclamation</font> No emote fields are filled. Please enter at least one Current and Select pair.</font>', Duration = 5 }) return end if # incompleteSlots > 0 then local msg = '<font color="#ff3030"><font family="rbxasset://LuaPackages/Packages/_Index/BuilderIcons/BuilderIcons/BuilderIcons.json" weight="Regular">circle-x</font> Failed to Apply Emote:</font>' for _, err in ipairs(incompleteSlots) do msg = msg .. '\n<font color="#ffaa00">' .. err .. '</font>' end WindUI:Notify({ Title = "Emote Changer", Content = msg, Duration = 8 }) return end EmoteChangerBuildMapping() local validMappings = 0 local messages = {} for i = 1, 12 do local currentInput = ConfigState.currentEmotes[i] or "" local selectInput = ConfigState.selectEmotes[i] or "" if currentInput ~= "" and selectInput ~= "" then local currentInfo = EmoteChangerFindInfo(currentInput) local selectInfo = EmoteChangerFindInfo(selectInput) if currentInfo and selectInfo then validMappings = validMappings + 1 table.insert(messages, string.format('<font color="#00ff88"><font family="rbxasset://LuaPackages/Packages/_Index/BuilderIcons/BuilderIcons/BuilderIcons.json" weight="Regular">circle-check</font> Slot %d:</font> <b>%s</b> <font color="#88ccff">→</font> <b>%s</b>', i, currentInfo.Name, selectInfo.Name)) else local errors = {} if not currentInfo then errors[# errors + 1] = string.format('<font color="#ff6666">Current "%s" not found</font>', currentInput) end if not selectInfo then errors[# errors + 1] = string.format('<font color="#ff6666">Select "%s" not found</font>', selectInput) end table.insert(messages, string.format('<font color="#ff3030"><font family="rbxasset://LuaPackages/Packages/_Index/BuilderIcons/BuilderIcons/BuilderIcons.json" weight="Regular">circle-x</font> Slot %d:</font> %s', i, table.concat(errors, ", "))) end end end if validMappings == 0 then table.insert(messages, 1, '<font color="#ffaa00"><font family="rbxasset://LuaPackages/Packages/_Index/BuilderIcons/BuilderIcons/BuilderIcons.json" weight="Regular">triangle-exclamation</font> No valid emote mappings found.</font>') WindUI:Notify({ Title = "Emote Changer", Content = table.concat(messages, "\n"), Duration = 8 }) return end EmoteChangerStopWatcher() task.wait(0.1) EmoteChangerStartWatcher() table.insert(messages, 1, string.format('<font color="#00ff88"><font family="rbxasset://LuaPackages/Packages/_Index/BuilderIcons/BuilderIcons/BuilderIcons.json" weight="Regular">circle-check</font> %d emote mapping%s applied.</font>', validMappings, validMappings > 1 and "s" or "")) WindUI:Notify({ Title = "Emote Changer", Content = table.concat(messages, "\n"), Duration = 8 }) end }) VisualsEmoteReset = Tabs.Visuals:Button({ Title = "Reset Emote Mappings", Icon = "trash-2", Color = Color3.fromHex("#FF3030"), Callback = function() EmoteChangerStopWatcher() ConfigState.emoteReplacements = {} for i = 1, 12 do ConfigState.currentEmotes[i] = "" ConfigState.selectEmotes[i] = "" end EmoteChangerRefreshWheel() WindUI:Notify({ Title = "Emote Changer", Content = '<font color="#ff3030"><font family="rbxasset://LuaPackages/Packages/_Index/BuilderIcons/BuilderIcons/BuilderIcons.json" weight="Regular">trash-can</font> All emote mappings have been reset.</font>', Duration = 3 }) end }) Tabs.Visuals:Section({ Title = "Deployment Skin Changer", TextSize = 20 }) Tabs.Visuals:Divider() function DeploySkinFind(type, name, callback) local packs = ReplicatedStorage:FindFirstChild("Items") if packs then packs = packs:FindFirstChild("ItemPacks") end if not packs then callback(nil) return end scanDescendantsAsync(packs, "Skins", nil, function(skinsFolder) if not skinsFolder then callback(nil) return end local deployables = skinsFolder:FindFirstChild("Deployables") if deployables then local typeFolder = deployables:FindFirstChild(type) if typeFolder then local folder = typeFolder:FindFirstChild(name) callback(folder) return end end callback(nil) end) end function DeploySkinSwap(type, current, target, onComplete) if type == "" or current == "" or target == "" or current == target then onComplete(false) return end local key = type .. "_" .. current if ConfigState.deploySkinSwaps[key] then local old = ConfigState.deploySkinSwaps[key] DeploySkinSwap(type, old.target, old.current, function() end) ConfigState.deploySkinSwaps[key] = nil end local curFound, tarFound = nil, nil local function checkDone() if curFound and tarFound then local cur = curFound local tar = tarFound local temp = Instance.new("Folder") temp.Name = "__temp_swap_" .. tostring(tick()) temp.Parent = ReplicatedStorage or workspace local curChildren = {} local tarChildren = {} for _, child in ipairs(cur:GetChildren()) do table.insert(curChildren, child) end for _, child in ipairs(tar:GetChildren()) do table.insert(tarChildren, child) end for _, child in ipairs(curChildren) do child.Parent = temp end for _, child in ipairs(tarChildren) do child.Parent = cur end for _, child in ipairs(temp:GetChildren()) do child.Parent = tar end temp:Destroy() ConfigState.deploySkinSwaps[key] = { type = type, current = current, target = target } onComplete(true) end end DeploySkinFind(type, current, function(result) curFound = result checkDone() end) DeploySkinFind(type, target, function(result) tarFound = result checkDone() end) end function DeploySkinRevertAll(onComplete) local list = {} for k, v in pairs(ConfigState.deploySkinSwaps) do table.insert(list, v) end local count = # list if count == 0 then onComplete() return end local done = 0 for _, v in ipairs(list) do DeploySkinSwap(v.type, v.target, v.current, function() done = done + 1 if done == count then ConfigState.deploySkinSwaps = {} onComplete() end end) end end DeploymentType = Tabs.Visuals:Input({ Title = "Deployment Type", Placeholder = "", Value = "", }) DeploymentType.Callback = function(v) if v ~= "" then ConfigState.deploySkinType = v end end CurrentDeployment = Tabs.Visuals:Input({ Title = "Current Deployment", Placeholder = "", }) CurrentDeployment.Callback = function(v) ConfigState.deploySkinCurName = v end NewDeployment = Tabs.Visuals:Input({ Title = "New Deployment", Placeholder = "", }) NewDeployment.Callback = function(v) ConfigState.deploySkinNewName = v end Tabs.Visuals:Button({ Title = "Swap Skin", Icon = "refresh-cw", Callback = function() task.spawn(function() DeploySkinSwap(ConfigState.deploySkinType, ConfigState.deploySkinCurName, ConfigState.deploySkinNewName, function(success) if success then WindUI:Notify({ Title = "Full Swap", Content = '<font color="#00ff88"><font family="rbxasset://LuaPackages/Packages/_Index/BuilderIcons/BuilderIcons/BuilderIcons.json" weight="Regular">circle-check</font> Swapped \'' .. ConfigState.deploySkinCurName .. '\' with \'' .. ConfigState.deploySkinNewName .. '\'</font>', Duration = 3 }) else WindUI:Notify({ Title = "Swap Skin", Content = '<font color="#ff3030"><font family="rbxasset://LuaPackages/Packages/_Index/BuilderIcons/BuilderIcons/BuilderIcons.json" weight="Regular">circle-x</font> Check names and type</font>', Duration = 3 }) end end) end) end }) Tabs.Visuals:Button({ Title = "Reset", Icon = "trash-2", Color = Color3.fromHex("#FF3030"), Callback = function() task.spawn(function() DeploySkinRevertAll(function() WindUI:Notify({ Title = "Reset", Content = '<font color="#ff3030"><font family="rbxasset://LuaPackages/Packages/_Index/BuilderIcons/BuilderIcons/BuilderIcons.json" weight="Regular">trash-can</font>All Deployment Skin Have been Reset</font>', Duration = 3 }) end) end) end }) Tabs.Visuals:Section({ Title = "Tools Skin Changer", TextSize = 20 }) Tabs.Visuals:Divider() function ToolSkinNormalize(str) return str:gsub("%s+", ""):lower() end function ToolSkinIsValidTool(toolName) local tools = ReplicatedStorage:FindFirstChild("Tools") if not tools then return false end local tool = tools:FindFirstChild(toolName) if not tool then return false end local variants = tool:FindFirstChild("Variants") if not variants then return false end return true, tool, variants end function ToolSkinIsValidSkin(toolName, skinName) local toolValid, tool, variants = ToolSkinIsValidTool(toolName) if not toolValid then return false end local skin = variants:FindFirstChild(skinName) if not skin then return false end return true, tool, variants, skin end function ToolSkinSwapFolderContents(parentFolder, firstSkin, secondSkin, tempName) local tempRoot = Instance.new("Folder") tempRoot.Name = tempName .. tostring(tick()):gsub("%.", "_") tempRoot.Parent = parentFolder local tempFirst = Instance.new("Folder") tempFirst.Name = "tempCurrent" tempFirst.Parent = tempRoot local tempSecond = Instance.new("Folder") tempSecond.Name = "tempSelected" tempSecond.Parent = tempRoot for _, child in ipairs(firstSkin:GetChildren()) do child.Parent = tempFirst end for _, child in ipairs(secondSkin:GetChildren()) do child.Parent = tempSecond end for _, child in ipairs(tempFirst:GetChildren()) do child.Parent = secondSkin end for _, child in ipairs(tempSecond:GetChildren()) do child.Parent = firstSkin end tempRoot:Destroy() end function ToolSkinRevert(toolName, currentSkinName, selectedSkinName) local key = toolName .. "_" .. currentSkinName if not ConfigState.activeToolsSwaps[key] then return false end local currentValid, currentTool, currentVariants, currentSkin = ToolSkinIsValidSkin(toolName, currentSkinName) local selectedValid, selectedTool, selectedVariants, selectedSkin = ToolSkinIsValidSkin(toolName, selectedSkinName) if currentValid and selectedValid then ToolSkinSwapFolderContents(currentVariants, currentSkin, selectedSkin, "__temp_skin_revert_") end ConfigState.activeToolsSwaps[key] = nil return true end function ToolSkinRevertAll() local swapsToRevert = {} for key, swapData in pairs(ConfigState.activeToolsSwaps) do table.insert(swapsToRevert, swapData) end for _, swapData in ipairs(swapsToRevert) do ToolSkinRevert(swapData.toolName, swapData.currentSkin, swapData.selectedSkin) end ConfigState.ToolSkinSawps = {} ConfigState.activeToolsSwaps = {} end function ToolSkinSwap(toolName, currentSkinName, selectedSkinName) local currentNorm = ToolSkinNormalize(currentSkinName) local selectedNorm = ToolSkinNormalize(selectedSkinName) if toolName == "" or currentNorm == "" or selectedNorm == "" then WindUI:Notify({ Title = "Skin Changer", Content = '<font color="#ffaa00"><font family="rbxasset://LuaPackages/Packages/_Index/BuilderIcons/BuilderIcons/BuilderIcons.json" weight="Regular">triangle-exclamation</font> All fields must be filled</font>', Duration = 3 }) return false end if currentNorm == selectedNorm then WindUI:Notify({ Title = "Skin Changer", Content = '<font color="#ffaa00"><font family="rbxasset://LuaPackages/Packages/_Index/BuilderIcons/BuilderIcons/BuilderIcons.json" weight="Regular">triangle-exclamation</font> Skin names cannot be the same</font>', Duration = 3 }) return false end local currentValid, currentTool, currentVariants, currentSkin = ToolSkinIsValidSkin(toolName, currentSkinName) local selectedValid, selectedTool, selectedVariants, selectedSkin = ToolSkinIsValidSkin(toolName, selectedSkinName) if not currentValid then WindUI:Notify({ Title = "Skin Changer", Content = '<font color="#ff3030"><font family="rbxasset://LuaPackages/Packages/_Index/BuilderIcons/BuilderIcons/BuilderIcons.json" weight="Regular">circle-x</font> Current skin not found: ' .. currentSkinName .. '</font>', Duration = 3 }) return false end if not selectedValid then WindUI:Notify({ Title = "Skin Changer", Content = '<font color="#ff3030"><font family="rbxasset://LuaPackages/Packages/_Index/BuilderIcons/BuilderIcons/BuilderIcons.json" weight="Regular">circle-x</font> Selected skin not found: ' .. selectedSkinName .. '</font>', Duration = 3 }) return false end local key = toolName .. "_" .. currentSkinName if ConfigState.activeToolsSwaps[key] then ToolSkinRevert(toolName, currentSkinName, ConfigState.activeToolsSwaps[key].selectedSkin) end ToolSkinSwapFolderContents(currentVariants, currentSkin, selectedSkin, "__temp_skin_swap_") local swapData = { toolName = toolName, currentSkin = currentSkinName, selectedSkin = selectedSkinName } ConfigState.activeToolsSwaps[key] = swapData local found = false for i, swap in ipairs(ConfigState.ToolSkinSawps) do if swap.toolName == toolName and swap.currentSkin == currentSkinName then ConfigState.ToolSkinSawps[i] = swapData found = true break end end if not found then table.insert(ConfigState.ToolSkinSawps, swapData) end WindUI:Notify({ Title = "Skin Changer", Content = '<font color="#00ff88"><font family="rbxasset://LuaPackages/Packages/_Index/BuilderIcons/BuilderIcons/BuilderIcons.json" weight="Regular">circle-check</font> Successfully swapped ' .. currentSkinName .. ' with ' .. selectedSkinName .. ' for ' .. toolName .. '</font>', Duration = 3 }) return true end ToolName = Tabs.Visuals:Input({ Title = "Tool Name", Placeholder = "Enter tool name", }) ToolName.Callback = function(value) ConfigState.currentToolInput = value end CurrentSkin = Tabs.Visuals:Input({ Title = "Current Skin", Placeholder = "Enter current skin name", }) CurrentSkin.Callback = function(value) ConfigState.currentSkinInput = value end NewSkin = Tabs.Visuals:Input({ Title = "New Skin", Placeholder = "Enter new skin name", }) NewSkin.Callback = function(value) ConfigState.selectedSkinInput = value end Tabs.Visuals:Button({ Title = "Replace Skin Swap", Icon = "refresh-cw", Callback = function() ToolSkinSwap(ConfigState.currentToolInput, ConfigState.currentSkinInput, ConfigState.selectedSkinInput) end }) Tabs.Visuals:Button({ Title = "Reset All Skins", Icon = "trash-2", Color = Color3.fromHex("#FF3030"), Desc = "Revert all skin swaps", Callback = function() ToolSkinRevertAll() WindUI:Notify({ Title = "Skin Changer", Content = '<font color="#ff3030"><font family="rbxasset://LuaPackages/Packages/_Index/BuilderIcons/BuilderIcons/BuilderIcons.json" weight="Regular">trash-can</font> All skins have been reset to original</font>', Duration = 3 }) end }) function getTracerGui() if ConfigState.tracerGui and ConfigState.tracerGui.Parent then return ConfigState.tracerGui end local parentGui = PlayerGui if not parentGui then parentGui = LocalPlayer and LocalPlayer:FindFirstChild("PlayerGui") end if not parentGui then return nil end local gui = Instance.new("ScreenGui") gui.Name = "Tracer GUI" gui.ResetOnSpawn = false gui.IgnoreGuiInset = true gui.DisplayOrder = - 2147483648 gui.Parent = parentGui ConfigState.tracerGui = gui return gui end function cleanupTracerESP() for _, data in pairs(ConfigState.tracerEntries) do if data.pivot then data.pivot:Destroy() end end ConfigState.tracerEntries = {} if ConfigState.tracerGui then ConfigState.tracerGui:Destroy() ConfigState.tracerGui = nil end end function ensureTracer(key, color) local data = ConfigState.tracerEntries[key] if data and data.pivot and data.pivot.Parent then if data.line then data.line.BackgroundColor3 = color end return data end local gui = getTracerGui() if not gui then return nil end local pivot = Instance.new("Frame") pivot.Name = "Tracer_" .. tostring(key) pivot.AnchorPoint = Vector2.new(0.5, 0.5) pivot.Position = UDim2.fromScale(0.5, 1) pivot.Size = UDim2.fromOffset(1, 1) pivot.BackgroundTransparency = 1 pivot.Visible = false pivot.ZIndex = - 2147483648 pivot.Parent = gui local line = Instance.new("Frame") line.Name = "Line" line.AnchorPoint = Vector2.new(0.5, 1) line.Position = UDim2.fromScale(0.5, 0.5) line.Size = UDim2.fromOffset(2, 0) line.BackgroundColor3 = color line.BorderSizePixel = 0 line.ZIndex = - 2147483648 line.Parent = pivot data = { pivot = pivot, line = line, lastPos = data and data.lastPos or nil } ConfigState.tracerEntries[key] = data return data end function drawTracer(data, worldPos, color) if not data or not data.pivot or not data.line then return end local camera = workspace.CurrentCamera if not camera or not worldPos then data.pivot.Visible = false return end data.line.BackgroundColor3 = color local screenPos = camera:WorldToViewportPoint(worldPos) local viewport = camera.ViewportSize local dirX = screenPos.X - (viewport.X * 0.5) local dirY = screenPos.Y - viewport.Y if screenPos.Z < 0 then dirX = - dirX dirY = - dirY end if dirX ~= dirX or dirY ~= dirY then data.pivot.Visible = false return end data.pivot.Visible = true data.pivot.Rotation = math.deg(math.atan2(dirX, - dirY)) data.line.Size = UDim2.fromOffset(2, math.sqrt(dirX * dirX + dirY * dirY)) end function tracerAnyEnabled() return ConfigState.playerTracersEnabled or ConfigState.npcTracersEnabled or ConfigState.toolTracersEnabled or ConfigState.downedTracersEnabled or ConfigState.enemyTracersEnabled or ConfigState.fruitTracersEnabled or ConfigState.gunTracersEnabled or ConfigState.ticketTracersEnabled or ConfigState.vehicleTracersEnabled or ConfigState.botTracersEnabled end function sweepDeadTracers(alive) for key, data in pairs(ConfigState.tracerEntries) do if not alive[key] then if data.pivot then data.pivot:Destroy() end ConfigState.tracerEntries[key] = nil end end end function getPartPos(inst) if not inst then return nil end if inst:IsA("BasePart") then return inst.Position end local hrp = inst:FindFirstChild("HumanoidRootPart") if hrp then return hrp.Position end local handle = inst:FindFirstChild("Handle") if handle then return handle.Position end if inst.PrimaryPart then return inst.PrimaryPart.Position end for _, child in ipairs(inst:GetChildren()) do if child:IsA("BasePart") then return child.Position end end return nil end function trackTracer(key, inst, color) local data = ensureTracer(key, color) if not data then return end local pos = getPartPos(inst) if pos then data.lastPos = pos end if data.lastPos then drawTracer(data, data.lastPos, color) else data.pivot.Visible = false end end function updateTracerESP() if not tracerAnyEnabled() then cleanupTracerESP() return end local registry = getESPRegistry() local alive = {} if ConfigState.playerTracersEnabled or ConfigState.downedTracersEnabled then for character, plr in pairs(registry.Players) do local downed = false pcall(function() downed = isPlayerDowned(plr) end) if downed and ConfigState.downedTracersEnabled then local key = "downed_" .. plr.UserId alive[key] = true trackTracer(key, character, Color3.fromRGB(255, 255, 0)) elseif (not downed) and ConfigState.playerTracersEnabled then local key = "player_" .. plr.UserId alive[key] = true trackTracer(key, character, Color3.fromRGB(0, 255, 0)) end end end if ConfigState.botTracersEnabled then for model in pairs(registry.NPC) do local key = "bot_" .. getESPTargetId(model) alive[key] = true trackTracer(key, model, isEventNPC(model) and Color3.fromRGB(255, 255, 255) or Color3.fromRGB(255, 0, 0)) end end if ConfigState.ticketTracersEnabled then for model in pairs(registry.Ticket) do local key = "ticket_" .. getESPTargetId(model) alive[key] = true trackTracer(key, model, Color3.fromRGB(0, 150, 255)) end end if ConfigState.vehicleTracersEnabled then for model in pairs(registry.Vehicle) do local key = "veh_" .. getESPTargetId(model) alive[key] = true trackTracer(key, model, Color3.fromRGB(255, 105, 180)) end end sweepDeadTracers(alive) end if not tracerRenderConnection then tracerRenderConnection = RunService.RenderStepped:Connect(function() if tracerAnyEnabled() then updateTracerESP() end end) end function getRigsFolder() local rigs = workspace:FindFirstChild("Rigs") if rigs then return rigs end for _, desc in ipairs(workspace:GetDescendants()) do if desc:IsA("Folder") and desc.Name == "Rigs" then return desc end end return nil end function findRigByTag(tag) if tag == nil then return nil end local cache = ConfigState.RigTagCache if not cache then cache = {} ConfigState.RigTagCache = cache end local cached = cache[tag] if cached and cached.Parent and cached:GetAttribute("Tag") == tag then return cached end local rigs = getRigsFolder() if not rigs then return nil end for _, rig in ipairs(rigs:GetChildren()) do if rig:IsA("Model") and rig:GetAttribute("Tag") == tag then cache[tag] = rig return rig end end cache[tag] = nil return nil end function setRigHighlight(rig, color) if not rig then return end local highlight = ConfigState.RigHighlightCache[rig] if not highlight or not highlight.Parent then highlight = Instance.new("Highlight") highlight.Name = "Rig_Highlight" highlight.FillTransparency = 0.5 highlight.OutlineTransparency = 0.3 highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop highlight.Parent = rig ConfigState.RigHighlightCache[rig] = highlight end highlight.FillColor = color highlight.OutlineColor = color end function clearAllRigHighlights() for rig, highlight in pairs(ConfigState.RigHighlightCache) do highlight:Destroy() end ConfigState.RigHighlightCache = {} end function isModelDownedRig(model) if not model then return false end local humanoid = model:FindFirstChildOfClass("Humanoid") if humanoid and humanoid.Health <= 0 then return true end local player = Players:FindFirstChild(model.Name) if player then return isPlayerDowned(player) end return false end function updateRigHighlights() local localTag = nil if LocalPlayer.Character then localTag = LocalPlayer.Character:GetAttribute("Tag") end local wanted = {} for model in pairs(getESPRegistry().Rigs) do if model.Parent then local tag = model:GetAttribute("Tag") if tag ~= nil and tag ~= localTag then local isNPC = model:GetAttribute("AI") == true local color = nil if isNPC then if ConfigState.RigHighlights.NPC then color = isEventNPC(model) and Color3.fromRGB(255, 255, 255) or Color3.fromRGB(255, 0, 0) end elseif isModelDownedRig(model) then if ConfigState.RigHighlights.Downed then color = Color3.fromRGB(255, 255, 0) end else if ConfigState.RigHighlights.Player then color = Color3.fromRGB(0, 255, 0) end end if color then local rig = findRigByTag(tag) if rig then wanted[rig] = color end end end end end for rig, highlight in pairs(ConfigState.RigHighlightCache) do if not wanted[rig] or not rig.Parent then highlight:Destroy() ConfigState.RigHighlightCache[rig] = nil end end for rig, color in pairs(wanted) do setRigHighlight(rig, color) end end function updateRigHighlightState() if ConfigState.RigHighlights.Player or ConfigState.RigHighlights.Downed or ConfigState.RigHighlights.NPC then if not ConfigState.RigHighlightConnection then ConfigState.RigHighlightConnection = RunService.RenderStepped:Connect(updateRigHighlights) end else if ConfigState.RigHighlightConnection then ConfigState.RigHighlightConnection:Disconnect() ConfigState.RigHighlightConnection = nil end clearAllRigHighlights() end end function getDistanceFromCamera(targetPosition) local camera = workspace.CurrentCamera if not camera then return 0 end return (targetPosition - camera.CFrame.Position).Magnitude end function calculateBoxScale(distance) if distance <= 17 then return 1 else local scale = 17 / distance return math.max(scale, 0.013) end end function getRootPart(model) if not model then return nil end local root = model:FindFirstChild("HumanoidRootPart") if root then return root end root = model.PrimaryPart if root then return root end return model:FindFirstChildWhichIsA("BasePart") end function createBillboardForModel(model, name, color) local existing = model:FindFirstChild("ESP_Billboard") if existing then existing:Destroy() end local rootPart = getRootPart(model) if not rootPart then return nil end local billboard = Instance.new("BillboardGui") billboard.Name = "ESP_Billboard" billboard.Adornee = rootPart billboard.Parent = rootPart billboard.AlwaysOnTop = true billboard.Size = UDim2.new(0, 200, 0, 50) billboard.StudsOffset = Vector3.new(0, 3, 0) billboard.ClipsDescendants = false billboard.ZIndexBehavior = Enum.ZIndexBehavior.Sibling billboard.Active = true local mainFrame = Instance.new("Frame") mainFrame.Name = "MainFrame" mainFrame.Size = UDim2.new(1, 0, 1, 0) mainFrame.BackgroundTransparency = 1 mainFrame.Parent = billboard local nameLabel = Instance.new("TextLabel") nameLabel.Name = "NameLabel" nameLabel.Size = UDim2.new(1, 0, 0, 20) nameLabel.Position = UDim2.new(0, 0, 0, 0) nameLabel.BackgroundTransparency = 1 nameLabel.Text = name nameLabel.TextColor3 = color nameLabel.TextSize = 14 nameLabel.Font = Enum.Font.GothamSemibold nameLabel.TextStrokeColor3 = Color3.fromRGB(0, 0, 0) nameLabel.TextStrokeTransparency = 0.3 nameLabel.TextXAlignment = Enum.TextXAlignment.Center nameLabel.TextYAlignment = Enum.TextYAlignment.Bottom nameLabel.Parent = mainFrame local distanceLabel = Instance.new("TextLabel") distanceLabel.Name = "DistanceLabel" distanceLabel.Size = UDim2.new(1, 0, 0, 16) distanceLabel.Position = UDim2.new(0, 0, 0, 20) distanceLabel.BackgroundTransparency = 1 distanceLabel.Text = "" distanceLabel.TextColor3 = color distanceLabel.TextSize = 12 distanceLabel.Font = Enum.Font.Gotham distanceLabel.TextStrokeColor3 = Color3.fromRGB(0, 0, 0) distanceLabel.TextStrokeTransparency = 0.3 distanceLabel.TextXAlignment = Enum.TextXAlignment.Center distanceLabel.TextYAlignment = Enum.TextYAlignment.Top distanceLabel.Parent = mainFrame return { billboard = billboard, nameLabel = nameLabel, distanceLabel = distanceLabel } end function updateBillboard(billboardData, name, distance, color) if not billboardData then return end if name then billboardData.nameLabel.Text = name billboardData.nameLabel.TextColor3 = color end if distance then billboardData.distanceLabel.Text = string.format("%.1f studs", distance) billboardData.distanceLabel.TextColor3 = color end billboardData.nameLabel.Visible = name ~= nil billboardData.distanceLabel.Visible = distance ~= nil end function create2DBoxForModel(model, color, scale) local rootPart = getRootPart(model) if not rootPart then return nil end local existing = model:FindFirstChild("ESP_2DBox") if existing then existing:Destroy() end local billboard = Instance.new("BillboardGui") billboard.Name = "ESP_2DBox" billboard.Adornee = rootPart billboard.Parent = rootPart billboard.AlwaysOnTop = true billboard.Size = UDim2.new(0, 80 * scale, 0, 100 * scale) billboard.StudsOffset = Vector3.new(0, 0, 0) billboard.ClipsDescendants = false local boxFrame = Instance.new("Frame") boxFrame.Name = "BoxFrame" boxFrame.Size = UDim2.new(1, 0, 1, 0) boxFrame.BackgroundTransparency = 1 boxFrame.BorderSizePixel = 0 boxFrame.Parent = billboard local uiStroke = Instance.new("UIStroke") uiStroke.Thickness = math.max(1.5 * scale, 1) uiStroke.Transparency = 0 uiStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border uiStroke.Color = color uiStroke.Parent = boxFrame return { billboard = billboard, boxFrame = boxFrame, stroke = uiStroke, scale = scale } end function update2DBox(boxData, color, scale) if boxData then if boxData.stroke then boxData.stroke.Color = color end if boxData.billboard then boxData.billboard.Size = UDim2.new(0, 80 * scale, 0, 100 * scale) end if boxData.stroke then boxData.stroke.Thickness = math.max(1.5 * scale, 1) end boxData.scale = scale end end function remove2DBox(model) local rootPart = getRootPart(model) if rootPart then local box = rootPart:FindFirstChild("ESP_2DBox") if box then box:Destroy() end end end function getBox3DBounds(model, rootPart) local rootCF = rootPart.CFrame local minV, maxV for _, part in ipairs(model:GetDescendants()) do if part:IsA("BasePart") and not part:FindFirstAncestorWhichIsA("Accessory") and not part:FindFirstAncestorWhichIsA("Tool") then local cf = rootCF:ToObjectSpace(part.CFrame) local half = part.Size / 2 for ix = -1, 1, 2 do for iy = -1, 1, 2 do for iz = -1, 1, 2 do local c = cf * Vector3.new(half.X * ix, half.Y * iy, half.Z * iz) if minV then minV = Vector3.new(math.min(minV.X, c.X), math.min(minV.Y, c.Y), math.min(minV.Z, c.Z)) maxV = Vector3.new(math.max(maxV.X, c.X), math.max(maxV.Y, c.Y), math.max(maxV.Z, c.Z)) else minV = c maxV = c end end end end end end if not minV then return {cf = CFrame.new(), size = rootPart.Size} end return {cf = CFrame.new((minV + maxV) / 2), size = maxV - minV} end function getFittedBox3DBounds(esp, model, rootPart) local config = ConfigState.ESPManager.Box3D local now = tick() if not esp.box3DBoundsStamp or now - esp.box3DBoundsStamp >= config.Refresh then esp.box3DBoundsStamp = now local fresh = getBox3DBounds(model, rootPart) local old = esp.box3DBounds if not old or (fresh.size - old.size).Magnitude > old.size.Magnitude * config.Tolerance or (fresh.cf.Position - old.cf.Position).Magnitude > old.size.Magnitude * config.Tolerance then esp.box3DBounds = fresh end end return esp.box3DBounds end function getBox3DCorners(size) local h = size / 2 local corners = {} for i = 0, 7 do corners[i + 1] = Vector3.new( (i % 2 == 1) and h.X or - h.X, (math.floor(i / 2) % 2 == 1) and h.Y or - h.Y, (math.floor(i / 4) % 2 == 1) and h.Z or - h.Z ) end return corners end function getBox3DEdges() local manager = ConfigState.ESPManager if not manager.Box3DEdges then local edges = {} for a = 0, 7 do for bit = 0, 2 do local step = 2 ^ bit if a % (step * 2) < step then table.insert(edges, {a + 1, a + step + 1}) end end end manager.Box3DEdges = edges end return manager.Box3DEdges end function isBox3DType(boxType) return type(boxType) == "string" and string.sub(boxType, 1, 2) == "3D" end function newBox3DAdornment(parent, rootPart, cframe, size, color, transparency) local adornment = Instance.new("BoxHandleAdornment") adornment.Adornee = rootPart adornment.Size = size adornment.CFrame = cframe adornment.Color3 = color adornment.Transparency = transparency adornment.ZIndex = 10 adornment.AlwaysOnTop = true adornment.Visible = true adornment.Parent = parent return adornment end function newBox3DSegment(parent, rootPart, bounds, from, to, thickness, color, transparency) local delta = to - from local extent = Vector3.new(math.abs(delta.X), math.abs(delta.Y), math.abs(delta.Z)) local adornment = newBox3DAdornment(parent, rootPart, bounds.cf * CFrame.new((from + to) / 2), Vector3.new(thickness, thickness, thickness) + extent, color, transparency) local config = ConfigState.ESPManager.Box3D config.Segments = config.Segments or setmetatable({}, {__mode = "k"}) config.Segments[adornment] = extent return adornment end function create3DBoxForModel(model, color, boxType, bounds) local rootPart = getRootPart(model) if not rootPart then return nil end local config = ConfigState.ESPManager.Box3D local folderName = "ESP_3DBox" local folder = model:FindFirstChild(folderName) if folder then folder:Destroy() end folder = Instance.new("Folder") folder.Name = folderName folder.Parent = model bounds = bounds or getBox3DBounds(model, rootPart) local size = bounds.size local thickness = math.max(math.min(size.X, size.Y, size.Z) * config.EdgeRatio, config.MinEdge) folder:SetAttribute("EdgeFloor", thickness) folder:SetAttribute("EdgeLast", thickness) local corners = getBox3DCorners(size) local edges = getBox3DEdges() local data = {} if boxType == "3D Billboard" then local canvas = math.max(size.Magnitude * config.BillboardScale, config.BillboardMin) local gui = Instance.new("BillboardGui") gui.Name = "ESP_3DBillboard" gui.Adornee = rootPart gui.AlwaysOnTop = true gui.LightInfluence = 0 gui.ResetOnSpawn = false gui.MaxDistance = math.huge gui.Size = UDim2.fromScale(canvas, canvas) gui.Parent = folder local lines = {} for i = 1, #edges do local frame = Instance.new("Frame") frame.AnchorPoint = Vector2.new(0.5, 0.5) frame.BackgroundColor3 = color frame.BorderSizePixel = 0 frame.Visible = false frame.Parent = gui lines[i] = frame end local localCorners = {} for i, corner in ipairs(corners) do localCorners[i] = bounds.cf * corner end data.lines = lines data.corners = localCorners data.canvas = canvas return folder, data end if boxType == "3D Filled" then newBox3DAdornment(folder, rootPart, bounds.cf, size, color, config.FillTransparency) end if boxType == "3D Corners" then for _, edge in ipairs(edges) do local a, b = corners[edge[1]], corners[edge[2]] local reach = (b - a) * config.CornerRatio newBox3DSegment(folder, rootPart, bounds, a, a + reach, thickness, color, config.Transparency) newBox3DSegment(folder, rootPart, bounds, b, b - reach, thickness, color, config.Transparency) end else for _, edge in ipairs(edges) do newBox3DSegment(folder, rootPart, bounds, corners[edge[1]], corners[edge[2]], thickness, color, config.Transparency) end end return folder, data end function update3DBillboardBox(data, rootPart) local cam = workspace.CurrentCamera if not cam or not data or not data.lines then return end local config = ConfigState.ESPManager.Box3D local camCF = cam.CFrame local camPos, look, right, up = camCF.Position, camCF.LookVector, camCF.RightVector, camCF.UpVector local rootCF = rootPart.CFrame local rootVec = rootCF.Position - camPos local rootDepth = rootVec:Dot(look) if rootDepth < 0.5 then for _, frame in ipairs(data.lines) do frame.Visible = false end return end local rootR, rootU = rootVec:Dot(right), rootVec:Dot(up) local points, valid = {}, {} for i, corner in ipairs(data.corners) do local v = rootCF * corner - camPos local depth = v:Dot(look) if depth > 0.1 then local k = rootDepth / depth points[i] = Vector2.new(v:Dot(right) * k - rootR, v:Dot(up) * k - rootU) valid[i] = true end end local thick = math.clamp(config.LineThickness * config.LineRefDistance / rootDepth, config.LineMin, config.LineMax) thick = math.floor(thick * 2 + 0.5) / 2 local canvas = data.canvas for i, edge in ipairs(getBox3DEdges()) do local frame = data.lines[i] if valid[edge[1]] and valid[edge[2]] then local a, b = points[edge[1]], points[edge[2]] local d = b - a local mid = (a + b) / 2 frame.Size = UDim2.new(d.Magnitude / canvas, 0, 0, thick) frame.Position = UDim2.fromScale(0.5 + mid.X / canvas, 0.5 - mid.Y / canvas) frame.Rotation = math.deg(math.atan2(- d.Y, d.X)) frame.Visible = true else frame.Visible = false end end end function update3DBoxThickness(folder, rootPart) local cam = workspace.CurrentCamera if not cam or not folder then return end local floor = folder:GetAttribute("EdgeFloor") if not floor then return end local depth = (rootPart.Position - cam.CFrame.Position):Dot(cam.CFrame.LookVector) local studsPerPixel = 2 * math.max(depth, 0.1) * math.tan(math.rad(cam.FieldOfView) / 2) / cam.ViewportSize.Y local target = math.max(floor, ConfigState.ESPManager.Box3D.LineThickness * studsPerPixel) local last = folder:GetAttribute("EdgeLast") or floor if math.abs(target - last) <= last * ConfigState.ESPManager.Box3D.Tolerance then return end folder:SetAttribute("EdgeLast", target) for _, item in ipairs(folder:GetChildren()) do local extent = ConfigState.ESPManager.Box3D.Segments and ConfigState.ESPManager.Box3D.Segments[item] if extent then item.Size = Vector3.new(target, target, target) + extent end end end function update3DBoxColor(model, color) local folder = model:FindFirstChild("ESP_3DBox") if folder then for _, item in ipairs(folder:GetDescendants()) do if item:IsA("BoxHandleAdornment") then item.Color3 = color elseif item:IsA("Frame") then item.BackgroundColor3 = color end end end end function remove3DBox(model) local folder = model:FindFirstChild("ESP_3DBox") if folder then folder:Destroy() end end function scanRigs() local rigs = {} local allDescendants = workspace:GetDescendants() for _, object in ipairs(allDescendants) do if string.find(object.Name, "Rigs") then if object:IsA("Model") then table.insert(rigs, object) elseif object:IsA("Folder") then for _, child in ipairs(object:GetChildren()) do if child:IsA("Model") then table.insert(rigs, child) end end end end end return rigs end function updateRigCache() ConfigState.ESPManager.RigOwner = {} ConfigState.ESPManager.PlayerRigs = {} ConfigState.ESPManager.RigCache = scanRigs() local players = Players:GetPlayers() for _, rig in ipairs(ConfigState.ESPManager.RigCache) do for _, player in ipairs(players) do if player.Name == rig.Name then ConfigState.ESPManager.RigOwner[rig] = player if not ConfigState.ESPManager.PlayerRigs[player] then ConfigState.ESPManager.PlayerRigs[player] = {} end table.insert(ConfigState.ESPManager.PlayerRigs[player], rig) break end end end end function createHighlightForModel(model, color) if not model then return nil end local existing = model:FindFirstChild("ESP_Highlight") if existing then existing.FillColor = color existing.OutlineColor = color return existing end local highlight = Instance.new("Highlight") highlight.Name = "ESP_Highlight" highlight.Parent = model highlight.FillColor = color highlight.OutlineColor = color highlight.FillTransparency = 0.5 highlight.OutlineTransparency = 0.3 highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop return highlight end function addHighlightForModel(model, color) if not model then return end if not ConfigState.ESPManager.HighlightCache[model] then ConfigState.ESPManager.HighlightCache[model] = createHighlightForModel(model, color) else local highlight = ConfigState.ESPManager.HighlightCache[model] highlight.FillColor = color highlight.OutlineColor = color end end function removeHighlightForModel(model) if not model then return end local highlight = ConfigState.ESPManager.HighlightCache[model] if highlight then highlight:Destroy() ConfigState.ESPManager.HighlightCache[model] = nil end end function removeAllHighlights() for model, highlight in pairs(ConfigState.ESPManager.HighlightCache) do highlight:Destroy() end ConfigState.ESPManager.HighlightCache = {} end function cleanupElements(elementsTable) for model, esp in pairs(elementsTable) do if esp.box2D then remove2DBox(model) end if esp.box3D then remove3DBox(model) end if esp.billboard then local rootPart = getRootPart(model) if rootPart then local bill = rootPart:FindFirstChild("ESP_Billboard") if bill then bill:Destroy() end end end removeHighlightForModel(model) end table.clear(elementsTable) end function cleanupESP() cleanupElements(ConfigState.ESPManager.AliveElements) cleanupElements(ConfigState.ESPManager.DownedElements) cleanupElements(ConfigState.ESPManager.NPCElements) cleanupElements(ConfigState.ESPManager.EventNPCElements) cleanupElements(ConfigState.ESPManager.TicketElements) cleanupElements(ConfigState.ESPManager.VehicleElements) removeAllHighlights() end function getESPRegistry() return ConfigState.ESPManager.Registry end function getESPTargetId(model) local registry = getESPRegistry() local id = registry.Ids[model] if not id then registry.NextId = registry.NextId + 1 id = registry.NextId registry.Ids[model] = id end return id end function trackESPModelConnection(model, connection) local registry = getESPRegistry() local list = registry.ModelConns[model] if not list then list = {} registry.ModelConns[model] = list end table.insert(list, connection) end function releaseESPModel(model) local registry = getESPRegistry() local list = registry.ModelConns[model] if list then for _, connection in ipairs(list) do connection:Disconnect() end registry.ModelConns[model] = nil end registry.Ids[model] = nil registry.Rigs[model] = nil registry.NPC[model] = nil registry.Players[model] = nil registry.Tagged[model] = nil registry.Ticket[model] = nil registry.Vehicle[model] = nil end function addESPSet(setName, model) if typeof(model) == "Instance" and model:IsA("Model") then getESPRegistry()[setName][model] = true getESPTargetId(model) trackESPModelConnection(model, model.AncestryChanged:Connect(function(_, parent) if not parent then releaseESPModel(model) end end)) end end function addESPRig(model) if not model:IsA("Model") then return end local registry = getESPRegistry() registry.Rigs[model] = true getESPTargetId(model) local function sync() registry.NPC[model] = model:GetAttribute("AI") == true or nil end sync() trackESPModelConnection(model, model:GetAttributeChangedSignal("AI"):Connect(sync)) trackESPModelConnection(model, model.AncestryChanged:Connect(function(_, parent) if not parent then releaseESPModel(model) end end)) end function bindESPContainer(getContainer, onAdded, onRemoved) local registry = getESPRegistry() local bound local function bind(container) if bound == container then return end bound = container for _, child in ipairs(container:GetChildren()) do onAdded(child) end table.insert(registry.Connections, container.ChildAdded:Connect(onAdded)) table.insert(registry.Connections, container.ChildRemoved:Connect(onRemoved)) end return bind end function bindESPNamedChild(parent, name, onAdded, onRemoved) local bind = bindESPContainer(nil, onAdded, onRemoved) local existing = parent:FindFirstChild(name) if existing then bind(existing) end table.insert(getESPRegistry().Connections, parent.ChildAdded:Connect(function(child) if child.Name == name then bind(child) end end)) end function bindESPPlayer(player) if player == LocalPlayer then return end local registry = getESPRegistry() local function onCharacter(character) registry.Players[character] = player getESPTargetId(character) trackESPModelConnection(character, character.AncestryChanged:Connect(function(_, parent) if not parent then releaseESPModel(character) end end)) end if player.Character then onCharacter(player.Character) end table.insert(registry.Connections, player.CharacterAdded:Connect(onCharacter)) table.insert(registry.Connections, player.CharacterRemoving:Connect(releaseESPModel)) end function setupESPRegistry() local registry = getESPRegistry() for _, connection in ipairs(registry.Connections) do connection:Disconnect() end registry.Connections = {} for _, player in ipairs(Players:GetPlayers()) do bindESPPlayer(player) end table.insert(registry.Connections, Players.PlayerAdded:Connect(bindESPPlayer)) table.insert(registry.Connections, Players.PlayerRemoving:Connect(function(player) if player.Character then releaseESPModel(player.Character) end end)) bindESPNamedChild(workspace, "Players", addESPRig, releaseESPModel) bindESPNamedChild(workspace, "Vehicles", function(model) addESPSet("Vehicle", model) end, releaseESPModel) local function bindTickets(effects) bindESPNamedChild(effects, "Tickets", function(model) addESPSet("Ticket", model) end, releaseESPModel) end local effects = workspace:FindFirstChild("Effects") if effects then bindTickets(effects) end table.insert(registry.Connections, workspace.ChildAdded:Connect(function(child) if child.Name == "Effects" then bindTickets(child) end end)) local CollectionService = game:GetService("CollectionService") local tagName = ConfigState.CatchTagName or "TouchReward" for _, instance in ipairs(CollectionService:GetTagged(tagName)) do addESPSet("Tagged", instance) end table.insert(registry.Connections, CollectionService:GetInstanceAddedSignal(tagName):Connect(function(instance) addESPSet("Tagged", instance) end)) table.insert(registry.Connections, CollectionService:GetInstanceRemovedSignal(tagName):Connect(function(instance) registry.Tagged[instance] = nil end)) end function updateGenericESP(targets, color, settings, elementsTable, skipHighlights) local currentTargets = {} for _, target in ipairs(targets) do local model = target.model if not model or not model.Parent then continue end local rootPart = getRootPart(model) if not rootPart then continue end currentTargets[model] = true if not elementsTable[model] then elementsTable[model] = {} end local esp = elementsTable[model] local dist = getDistanceFromCamera(rootPart.Position) local scale = calculateBoxScale(dist) if settings.Boxes then if isBox3DType(settings.BoxType) then local bounds = getFittedBox3DBounds(esp, model, rootPart) if esp.box3D and (esp.box3DType ~= settings.BoxType or esp.box3DBuiltBounds ~= bounds or not esp.box3D.Parent) then remove3DBox(model) esp.box3D = nil end if not esp.box3D then esp.box3D, esp.box3DData = create3DBoxForModel(model, color, settings.BoxType, bounds) esp.box3DType = settings.BoxType esp.box3DBuiltBounds = bounds else update3DBoxColor(model, color) end if esp.box3DType == "3D Billboard" then update3DBillboardBox(esp.box3DData, rootPart) else update3DBoxThickness(esp.box3D, rootPart) end if esp.box2D then remove2DBox(model) esp.box2D = nil end else if not esp.box2D then esp.box2D = create2DBoxForModel(model, color, scale) else update2DBox(esp.box2D, color, scale) end if esp.box3D then remove3DBox(model) esp.box3D = nil end end else if esp.box2D then remove2DBox(model); esp.box2D = nil end if esp.box3D then remove3DBox(model); esp.box3D = nil end end if settings.Names or settings.Distance then if not esp.billboard then esp.billboard = createBillboardForModel(model, target.name, color) end local showDist = settings.Distance and dist or nil updateBillboard(esp.billboard, settings.Names and target.name or nil, showDist, color) else if esp.billboard then local rootPart = getRootPart(model) if rootPart then local bill = rootPart:FindFirstChild("ESP_Billboard") if bill then bill:Destroy() end end esp.billboard = nil end end if not skipHighlights and settings.Highlights then addHighlightForModel(model, color) else removeHighlightForModel(model) end end for model, esp in pairs(elementsTable) do if not currentTargets[model] then if esp.box2D then remove2DBox(model) end if esp.box3D then remove3DBox(model) end if esp.billboard then local rootPart = getRootPart(model) if rootPart then local bill = rootPart:FindFirstChild("ESP_Billboard") if bill then bill:Destroy() end end end removeHighlightForModel(model) elementsTable[model] = nil end end end function updateESP() if not ConfigState.ESPManager.Rendering or not ConfigState.ESPManager.WindowFocused then return end if not workspace.CurrentCamera then return end if ConfigState.ESPManager.LastRigUpdate == 0 then updateRigCache() ConfigState.ESPManager.LastRigUpdate = tick() end local registry = getESPRegistry() local aliveTargets = {} local downedTargets = {} for char, player in pairs(registry.Players) do if not char.Parent then continue end local hum = char:FindFirstChild("Humanoid") if not hum then continue end if isPlayerDowned(player) then table.insert(downedTargets, { model = char, name = player.Name }) elseif hum.Health > 0 then table.insert(aliveTargets, { model = char, name = player.Name }) end end updateGenericESP( aliveTargets, Color3.fromRGB(0, 255, 0), ConfigState.ESPManager.Settings, ConfigState.ESPManager.AliveElements, true) updateGenericESP( downedTargets, Color3.fromRGB(255, 255, 0), ConfigState.ESPManager.DownedSettings, ConfigState.ESPManager.DownedElements, true) local NPCTargets = {} local EventNPCTargets = {} for model in pairs(registry.NPC) do local entry = { model = model, name = model.Name } if isEventNPC(model) then table.insert(EventNPCTargets, entry) else table.insert(NPCTargets, entry) end end for instance in pairs(registry.Tagged) do if instance:IsDescendantOf(workspace) and not registry.NPC[instance] then table.insert(EventNPCTargets, { model = instance, name = instance.Name }) end end updateGenericESP( NPCTargets, Color3.fromRGB(255, 0, 0), ConfigState.ESPManager.NPCSettings, ConfigState.ESPManager.NPCElements, true) updateGenericESP( EventNPCTargets, Color3.fromRGB(255, 255, 255), ConfigState.ESPManager.NPCSettings, ConfigState.ESPManager.EventNPCElements, true) local ticketTargets = {} for model in pairs(registry.Ticket) do table.insert(ticketTargets, { model = model, name = model.Name }) end updateGenericESP( ticketTargets, Color3.fromRGB(0, 150, 255), ConfigState.ESPManager.TicketSettings, ConfigState.ESPManager.TicketElements, false) local vehicleTargets = {} for model in pairs(registry.Vehicle) do table.insert(vehicleTargets, { model = model, name = model.Name }) end updateGenericESP( vehicleTargets, Color3.fromRGB(255, 105, 180), ConfigState.ESPManager.VehicleSettings, ConfigState.ESPManager.VehicleElements, false) if not ConfigState.ESPManager.TicketSettings.Highlights and not ConfigState.ESPManager.VehicleSettings.Highlights then if next(ConfigState.ESPManager.HighlightCache) ~= nil then removeAllHighlights() end end end function onRenderStepped() ConfigState.ESPManager.LastRenderTime = tick() ConfigState.ESPManager.Rendering = true updateESP() end function StartESP() StopESP() ConfigState.ESPManager.Enabled = true ConfigState.ESPManager.Connections.Render = RunService.RenderStepped:Connect(onRenderStepped) end function StopESP() ConfigState.ESPManager.Enabled = false if ConfigState.ESPManager.Connections.Render then ConfigState.ESPManager.Connections.Render:Disconnect() ConfigState.ESPManager.Connections.Render = nil end cleanupESP() end function setupWatchers() ConfigState.ESPManager.Connections.RigAdded = workspace.DescendantAdded:Connect(function(desc) if desc:IsA("Model") and string.find(desc.Name, "Rigs") then ConfigState.ESPManager.LastRigUpdate = 0 end end) ConfigState.ESPManager.Connections.RigRemoved = workspace.DescendantRemoving:Connect(function(desc) if desc:IsA("Model") and string.find(desc.Name, "Rigs") then local highlight = ConfigState.ESPManager.HighlightCache[desc] if highlight then highlight:Destroy() ConfigState.ESPManager.HighlightCache[desc] = nil end local owner = ConfigState.ESPManager.RigOwner[desc] if owner then ConfigState.ESPManager.RigOwner[desc] = nil if ConfigState.ESPManager.PlayerRigs[owner] then for i, rig in ipairs(ConfigState.ESPManager.PlayerRigs[owner]) do if rig == desc then table.remove(ConfigState.ESPManager.PlayerRigs[owner], i) break end end end end for i, rig in ipairs(ConfigState.ESPManager.RigCache) do if rig == desc then table.remove(ConfigState.ESPManager.RigCache, i) break end end end end) ConfigState.ESPManager.Connections.PlayerAdded = Players.PlayerAdded:Connect(function() ConfigState.ESPManager.LastRigUpdate = 0 end) ConfigState.ESPManager.Connections.PlayerRemoving = Players.PlayerRemoving:Connect(function(player) removeHighlightForModel(player.Character) ConfigState.ESPManager.PlayerRigs[player] = nil end) end setupWatchers() setupESPRegistry() RunService.RenderStepped:Connect(function() ConfigState.ESPManager.LastRenderTime = tick() ConfigState.ESPManager.Rendering = true end) ConfigState.ESPManager.Connections.RenderCheck = RunService.Heartbeat:Connect(function() local currentTime = tick() if currentTime - ConfigState.ESPManager.LastRenderTime > 1 then ConfigState.ESPManager.Rendering = false cleanupESP() end end) UserInputService.WindowFocusReleased:Connect(function() ConfigState.ESPManager.WindowFocused = false ConfigState.ESPManager.Rendering = false cleanupESP() end) UserInputService.WindowFocused:Connect(function() ConfigState.ESPManager.WindowFocused = true ConfigState.ESPManager.Rendering = true end) GuiService:GetPropertyChangedSignal("MenuIsOpen"):Connect(function() if GuiService.MenuIsOpen then ConfigState.ESPManager.Rendering = false cleanupESP() else ConfigState.ESPManager.Rendering = true end end) Players.PlayerRemoving:Connect(function(leavingPlayer) if leavingPlayer == Players.LocalPlayer then cleanupESP() StopESP() end end) Tabs.ESP:Section({ Title = "Player ESP", TextSize = 20 }) Tabs.ESP:Divider() PlayerNames = Tabs.ESP:Toggle({ Title = "Player Names", Flag = "PlayerNames", Value = false, }) PlayerNames.Callback = function(state) ConfigState.ESPManager.Settings.Names = state if state then StartESP() else updateESP() end end PlayerBoxes = Tabs.ESP:Toggle({ Title = "Player Boxes", Flag = "PlayerBoxes", Value = false, }) PlayerBoxes.Callback = function(state) ConfigState.ESPManager.Settings.Boxes = state if state then StartESP() else updateESP() end end Tabs.ESP:Dropdown({ Title = "Player Box Type", Flag = "PlayerBoxType", Values = {"2D", "3D", "3D Corners", "3D Filled", "3D Billboard"}, Value = "2D", Callback = function(value) ConfigState.ESPManager.Settings.BoxType = value if ConfigState.ESPManager.Settings.Boxes then updateESP() end end }) PlayerDistance = Tabs.ESP:Toggle({ Title = "Player Distance", Flag = "PlayerDistance", Value = false, }) PlayerDistance.Callback = function(state) ConfigState.ESPManager.Settings.Distance = state if state then StartESP() else updateESP() end end PlayerHighlights = Tabs.ESP:Toggle({ Title = "Player Highlights", Flag = "PlayerHighlights", Value = false, }) PlayerHighlights.Callback = function(state) ConfigState.RigHighlights.Player = state updateRigHighlightState() end PlayerTracerESP = Tabs.ESP:Toggle({ Title = "Tracer ESP", Flag = "PlayerTracerESP", Desc = "Warning: Enable this may lack of performance! This features will make your game unplayable or lagging.", Value = false, }) PlayerTracerESP.Callback = function(state) ConfigState.playerTracersEnabled = state if not tracerAnyEnabled() then cleanupTracerESP() end end Tabs.ESP:Divider() Tabs.ESP:Section({ Title = "Downed Player ESP", TextSize = 20 }) Tabs.ESP:Divider() DownedNames = Tabs.ESP:Toggle({ Title = "Downed Names", Flag = "DownedNames", Value = false, }) DownedNames.Callback = function(state) ConfigState.ESPManager.DownedSettings.Names = state if state then StartESP() else updateESP() end end DownedBoxes = Tabs.ESP:Toggle({ Title = "Downed Boxes", Flag = "DownedBoxes", Value = false, }) DownedBoxes.Callback = function(state) ConfigState.ESPManager.DownedSettings.Boxes = state if state then StartESP() else updateESP() end end Tabs.ESP:Dropdown({ Title = "Downed Box Type", Flag = "DownedBoxType", Values = {"2D", "3D", "3D Corners", "3D Filled", "3D Billboard"}, Value = "2D", Callback = function(value) ConfigState.ESPManager.DownedSettings.BoxType = value if ConfigState.ESPManager.DownedSettings.Boxes then updateESP() end end }) DownedDistance = Tabs.ESP:Toggle({ Title = "Downed Distance", Flag = "DownedDistance", Value = false, }) DownedDistance.Callback = function(state) ConfigState.ESPManager.DownedSettings.Distance = state if state then StartESP() else updateESP() end end DownedHighlights = Tabs.ESP:Toggle({ Title = "Downed Highlights", Flag = "DownedHighlights", Value = false, }) DownedHighlights.Callback = function(state) ConfigState.RigHighlights.Downed = state updateRigHighlightState() end DownedTracerESP = Tabs.ESP:Toggle({ Title = "Tracer ESP", Flag = "DownedTracerESP", Desc = "Warning: Enable this may lack of performance! This features will make your game unplayable or lagging.", Value = false, }) DownedTracerESP.Callback = function(state) ConfigState.downedTracersEnabled = state if not tracerAnyEnabled() then cleanupTracerESP() end end Tabs.ESP:Divider() Tabs.ESP:Section({ Title = "NPC ESP", TextSize = 20 }) Tabs.ESP:Divider() NPCNames = Tabs.ESP:Toggle({ Title = "NPC Names", Flag = "NPCNames", Value = false, }) NPCNames.Callback = function(state) ConfigState.ESPManager.NPCSettings.Names = state if state then StartESP() else updateESP() end end NPCBoxes = Tabs.ESP:Toggle({ Title = "NPC Boxes", Flag = "NPCBoxes", Value = false, }) NPCBoxes.Callback = function(state) ConfigState.ESPManager.NPCSettings.Boxes = state if state then StartESP() else updateESP() end end Tabs.ESP:Dropdown({ Title = "NPC Box Type", Flag = "NPCBoxType", Values = {"2D", "3D", "3D Corners", "3D Filled", "3D Billboard"}, Value = "2D", Callback = function(value) ConfigState.ESPManager.NPCSettings.BoxType = value if ConfigState.ESPManager.NPCSettings.Boxes then updateESP() end end }) NPCDistance = Tabs.ESP:Toggle({ Title = "NPC Distance", Flag = "NPCDistance", Value = false, }) NPCDistance.Callback = function(state) ConfigState.ESPManager.NPCSettings.Distance = state if state then StartESP() else updateESP() end end NPCHighlights = Tabs.ESP:Toggle({ Title = "NPC Highlights", Flag = "NPCHighlights", Value = false, }) NPCHighlights.Callback = function(state) ConfigState.RigHighlights.NPC = state updateRigHighlightState() end NPCTracerESP = Tabs.ESP:Toggle({ Title = "Tracer ESP", Flag = "NPCTracerESP", Desc = "Warning: Enable this may lack of performance! This features will make your game unplayable or lagging.", Value = false, }) NPCTracerESP.Callback = function(state) ConfigState.botTracersEnabled = state if not tracerAnyEnabled() then cleanupTracerESP() end end Tabs.ESP:Divider() Tabs.ESP:Section({ Title = "Ticket ESP", TextSize = 20 }) Tabs.ESP:Divider() TicketBoxes = Tabs.ESP:Toggle({ Title = "Ticket Boxes", Flag = "TicketBoxes", Value = false, }) TicketBoxes.Callback = function(state) ConfigState.ESPManager.TicketSettings.Boxes = state if state then StartESP() else updateESP() end end Tabs.ESP:Dropdown({ Title = "Ticket Box Type", Flag = "TicketBoxType", Values = {"2D", "3D", "3D Corners", "3D Filled", "3D Billboard"}, Value = "2D", Callback = function(value) ConfigState.