PManager.VehicleSettings.BoxType = value if ConfigState.ESPManager.VehicleSettings.Boxes then updateESP() end end }) VehicleDistance = Tabs.ESP:Toggle({ Title = "Vehicle Distance", Flag = "VehicleDistance", Value = false, }) VehicleDistance.Callback = function(state) ConfigState.ESPManager.VehicleSettings.Distance = state if state then StartESP() else updateESP() end end VehicleHighlights = Tabs.ESP:Toggle({ Title = "Vehicle Highlights", Flag = "VehicleHighlights", Value = false, }) VehicleHighlights.Callback = function(state) ConfigState.ESPManager.VehicleSettings.Highlights = state if state then StartESP() else updateESP() end end VehicleTracerESP = Tabs.ESP:Toggle({ Title = "Tracer ESP", Flag = "VehicleTracerESP", Desc = "Warning: Enable this may lack of performance! This features will make your game unplayable or lagging.", Value = false, }) VehicleTracerESP.Callback = function(state) ConfigState.vehicleTracersEnabled = state if not tracerAnyEnabled() then cleanupTracerESP() end end Tabs.Misc:Section({ Title = "Misc", TextSize = 20 }) Tabs.Misc:Divider() function GetSeatedVehicle() local char = LocalPlayer.Character local weld = char and char:FindFirstChild("SeatWeld") local seat = weld and weld:IsA("JointInstance") and weld.Part0 local vehicle = seat and seat.Parent and seat.Parent.Parent if vehicle and vehicle:IsA("Model") then return vehicle end return nil end function GetDrivenVehicle() local char = LocalPlayer.Character local weld = char and char:FindFirstChild("SeatWeld") local seat = weld and weld:IsA("JointInstance") and weld.Part0 if not seat or seat.Name ~= "Driver" then return nil end local vehicle = seat.Parent and seat.Parent.Parent if not (vehicle and vehicle:IsA("Model")) then return nil end local me = CharacterService:GetLocalCharacter() local seated = me and me.DataRegistry and me.DataRegistry:Get("Seated") if seated == 0 then return nil end return vehicle end Tabs.Misc:Button({ Title = "Hop in Random Vehicle", Callback = function() task.spawn(function() local folder = workspace:FindFirstChild("Vehicles") if not folder then return end local current = GetSeatedVehicle() if current then local currentTag = current:GetAttribute("Tag") if currentTag ~= nil then Interact:FireServer("Vehicle", currentTag) end local deadline = os.clock() + 2 while GetSeatedVehicle() and os.clock() < deadline do task.wait(0.05) end if GetSeatedVehicle() then return end task.wait(0.25) end local options = {} for _, vehicle in ipairs(folder:GetChildren()) do if vehicle ~= current and vehicle:GetAttribute("Tag") ~= nil then table.insert(options, vehicle) end end if #options == 0 then return end Interact:FireServer("Vehicle", options[math.random(#options)]:GetAttribute("Tag")) end) end }) Tabs.Misc:Space() AntiAfkToggle = Tabs.Misc:Toggle({ Title = "Anti AFK", Flag = "AntiAfkToggle", Value = false, }) AntiAfkToggle.Callback = function(s) if s then EnableAntiAFK() else DisableAntiAFK() end end Tabs.Misc:Space() Tabs.Misc:Button({ Title = "Redeem All code", Callback = function() local RemoteEvent = ReplicatedStorage.Shared.UserData.Remotes.RedeemCode local URL = "https://web-wacker.netlify.app/api/raw?url=https%3A%2F%2Fevade-nextbot.fandom.com%2Fwiki%2FCodes" local function getContent(url) local content = game:HttpGet(url, true) return content or nil end local function extractTRData(htmlContent) if not htmlContent then return {} end local tableRows = {} local trPattern = "<tr>(.-)</tr>" for trContent in htmlContent:gmatch(trPattern) do local rowData = {} local codePattern = "<td[^>]*>%s*<code[^>]*>(.-)</code>" local code = trContent:match(codePattern) if code then code = code:gsub("&lt;", "<") code = code:gsub("&gt;", ">") code = code:gsub("&amp;", "&") code = code:gsub("&quot;", '"') code = code:match("^%s*(.-)%s*$") or code rowData.code = code end local tdPattern = "<td[^>]*>(.-)</td>" local tdCount = 0 local tds = {} for tdContent in trContent:gmatch(tdPattern) do tdCount = tdCount + 1 local cleanContent = tdContent :gsub("<[^>]+>", "") :gsub("&lt;", "<") :gsub("&gt;", ">") :gsub("&amp;", "&") :gsub("&quot;", '"') :gsub("%s+", " ") :match("^%s*(.-)%s*$") or tdContent table.insert(tds, cleanContent) end if tdCount >= 2 and not rowData.code then rowData.code = tds[1] rowData.description = tdCount >= 2 and tds[2] or "" rowData.status = tdCount >= 3 and tds[3] or "" rowData.date = tdCount >= 4 and tds[4] or "" elseif rowData.code then rowData.description = tdCount >= 2 and tds[1] or "" rowData.status = tdCount >= 3 and tds[2] or "" rowData.date = tdCount >= 4 and tds[3] or "" end local statusPattern = "<b[^>]*>%s*<span[^>]*>([^<]+)</span>%s*</b>" local statusValue = trContent:match(statusPattern) if statusValue then statusValue = statusValue:lower():gsub("%s+", "") if statusValue == "true" or statusValue == "false" then rowData.spanStatus = statusValue end end if not rowData.spanStatus then local truePos = trContent:lower():find("true") local falsePos = trContent:lower():find("false") if truePos then rowData.spanStatus = "true" elseif falsePos then rowData.spanStatus = "false" end end if rowData.code and # rowData.code > 0 then table.insert(tableRows, rowData) end end return tableRows end local function useCodeWithFeedback(code) RemoteEvent:FireServer(code) FireClient( ReplicatedStorage.Remotes.UI.SharedUISetType, "Notification", "Message", "Code sent: " .. code, "Info") end local function run() FireClient( ReplicatedStorage.Remotes.UI.SharedUISetType, "Notification", "Message", "Starting code extraction...", "Info") local htmlContent = getContent(URL) if not htmlContent then FireClient( ReplicatedStorage.Remotes.UI.SharedUISetType, "Notification", "Message", "Failed to fetch our Wikipedia content", "Error") return end local tableRows = extractTRData(htmlContent) if # tableRows == 0 then FireClient( ReplicatedStorage.Remotes.UI.SharedUISetType, "Notification", "Message", "No table rows found", "Error") return end FireClient( ReplicatedStorage.Remotes.UI.SharedUISetType, "Notification", "Message", "Found " .. # tableRows .. " table rows", "Info") local trueCodes = {} local falseCodes = {} local unknownCodes = {} for _, row in ipairs(tableRows) do local status = row.spanStatus or "unknown" if status == "true" then table.insert(trueCodes, row.code) elseif status == "false" then table.insert(falseCodes, row.code) else table.insert(unknownCodes, row.code) end end FireClient( ReplicatedStorage.Remotes.UI.SharedUISetType, "Notification", "Message", "True codes: " .. # trueCodes, "Success") FireClient( ReplicatedStorage.Remotes.UI.SharedUISetType, "Notification", "Message", "False codes: " .. # falseCodes, "Error") FireClient( ReplicatedStorage.Remotes.UI.SharedUISetType, "Notification", "Message", "Unknown codes: " .. # unknownCodes, "ing") FireClient( ReplicatedStorage.Remotes.UI.SharedUISetType, "Notification", "Message", "Code Will be redeem in 5 Second", "Message") wait(5) local validCodes = {} for _, code in ipairs(trueCodes) do table.insert(validCodes, code) end for _, code in ipairs(unknownCodes) do table.insert(validCodes, code) end if # validCodes == 0 then FireClient( ReplicatedStorage.Remotes.UI.SharedUISetType, "Notification", "Message", "No valid codes to try", "Error") return end for i, code in ipairs(validCodes) do FireClient( ReplicatedStorage.Remotes.UI.SharedUISetType, "Notification", "Message", "Processing [" .. i .. "/" .. # validCodes .. "]: " .. code, "Info") useCodeWithFeedback(code) if i < # validCodes then wait(4) end end end run() end }) Tabs.Misc:Space() function teleportToDistance(root, dist, NPCPos) if not root then return nil end dist = tonumber(dist) or ConfigState.DistanceTeleport or 100 local from = NPCPos or root.Position local dir = Vector3.new(root.Position.X - from.X, 0, root.Position.Z - from.Z) if dir.Magnitude < 0.1 then dir = Vector3.new(0, 0, 1) end local pos = from + dir.Unit * dist pos = Vector3.new(pos.X, root.Position.Y, pos.Z) local params = RaycastParams.new() params.FilterType = Enum.RaycastFilterType.Exclude params.FilterDescendantsInstances = {Players.LocalPlayer.Character} local hit = workspace:Raycast(pos + Vector3.new(0, 200, 0), Vector3.new(0, -500, 0), params) if hit then pos = hit.Position + Vector3.new(0, 3, 0) end return CFrame.new(pos) end function getSafeCFrame(typ, root, tdist, NPCPos) if typ == "Safe Part" then teleportToSecurityPart(Vector3.new(0, 3, 0)) return nil elseif typ == "Spawn" then teleportToRandomSpawn(Vector3.new(0, 3, 0)) return nil elseif typ == "Distance" then return teleportToDistance(root, tdist, NPCPos) elseif typ == "Players" then teleportToRandomPlayer(Vector3.new(0, 3, 0)) return nil end return nil end function stopAntiNPC() if ConfigState.antiNPCConnection then ConfigState.antiNPCConnection:Disconnect() ConfigState.antiNPCConnection = nil end end function antiNPCFindNearest(folder, root, nearest, nearestDist) if not folder then return nearest, nearestDist end for _, v in ipairs(folder:GetChildren()) do if v:IsA("Model") and v:GetAttribute("AI") == true and v ~= root.Parent and not isEventNPC(v) then local hrp = v:FindFirstChild("HumanoidRootPart") if hrp and not table.find(ConfigState.innocentBots, v.Name) then local d = (root.Position - hrp.Position).Magnitude if d < ConfigState.AntiNPCDistance and d < nearestDist then nearest, nearestDist = hrp, d end end end end return nearest, nearestDist end function AntiNPCBlocksTeleport(pos) if not ConfigState.AntiNPCEnabled then return false end if os.clock() - (ConfigState.AntiNPCLastTrigger or 0) < 1 then return true end local char = Players.LocalPlayer.Character local root = char and char:FindFirstChild("HumanoidRootPart") if not root then return false end local gameFolder = workspace:FindFirstChild("Game") local probe = {Position = pos or root.Position, Parent = nil} local n = antiNPCFindNearest(workspace:FindFirstChild("Players"), probe, nil, math.huge) if not n then n = antiNPCFindNearest(gameFolder and gameFolder:FindFirstChild("Players"), probe, nil, math.huge) end return n ~= nil end function startAntiNPC() stopAntiNPC() if not ConfigState.AntiNPCEnabled then return end ConfigState.antiNPCConnection = RunService.Heartbeat:Connect(function() local char = Players.LocalPlayer.Character local root = char and char:FindFirstChild("HumanoidRootPart") if not root then return end local gameFolder = workspace:FindFirstChild("Game") local nearest, nearestDist = nil, math.huge nearest, nearestDist = antiNPCFindNearest(workspace:FindFirstChild("Players"), root, nearest, nearestDist) nearest, nearestDist = antiNPCFindNearest(gameFolder and gameFolder:FindFirstChild("Players"), root, nearest, nearestDist) if nearest then ConfigState.AntiNPCLastTrigger = os.clock() local target = getSafeCFrame(ConfigState.AntiNPCTeleportType, root, ConfigState.DistanceTeleport, nearest.Position) if target then root.CFrame = target end end end) end function stopAntiBotSpawnPoint() if ConfigState.antiNewSpawnConnection then ConfigState.antiNewSpawnConnection:Disconnect() ConfigState.antiNewSpawnConnection = nil end end function startAntiBotSpawnPoint() if ConfigState.AntiNewNPCSpawnEnabled then ConfigState.antiNewSpawnConnection = RunService.Heartbeat:Connect(function() local char = Players.LocalPlayer.Character if not char or not char:FindFirstChild("HumanoidRootPart") then return end local root = char.HumanoidRootPart local att = nil local terrain = Workspace:FindFirstChild("Terrain") if terrain then att = terrain:FindFirstChild("NextbotSpawnAttachment") end if not att then att = Workspace:FindFirstChild("NextbotSpawnAttachment") end if not att then local gameFolder = Workspace:FindFirstChild("Game") if gameFolder then att = gameFolder:FindFirstChild("NextbotSpawnAttachment") end end if not att then return end local spawnPos = att.WorldCFrame.Position if (root.Position - spawnPos).Magnitude >= ConfigState.AntiNewNPCSpawnDistance then return end local target = getSafeCFrame(ConfigState.AntiNewNPCSpawnTeleportType, root, ConfigState.AntiNewNPCSpawnTeleport, spawnPos) if target then root.CFrame = target end end) end end AntiNPCToggle = Tabs.Misc:Toggle({ Title = "Anti NPC", Flag = "AntiNPCToggle", Value = false, }) AntiNPCToggle.Callback = function(state) ConfigState.AntiNPCEnabled = state if state then startAntiNPC() else stopAntiNPC() end end AntiNPCTeleportTypeDropdown = Tabs.Misc:Dropdown({ Title = "Anti-NPC Teleport Type", Flag = "AntiNPCTeleportTypeDropdown", Desc = "Choose how to teleport when avoiding NPCs", Values = {"Players", "Spawn", "Distance", "Safe Part"}, Value = ConfigState.AntiNPCTeleportType, Callback = function(v) ConfigState.AntiNPCTeleportType = v end }) AntiNPCDistanceInput = Tabs.Misc:Input({ Title = "Anti-NPC Distance", Flag = "AntiNPCDistanceInput", Desc = "Distance threshold for NPC detection", Placeholder = tostring(ConfigState.AntiNPCDistance), NumbersOnly = true, Value = tostring(ConfigState.AntiNPCDistance), }) AntiNPCDistanceInput.Callback = function(v) n = tonumber(v) if n and n > 0 then ConfigState.AntiNPCDistance = n end end DistanceTeleportInput = Tabs.Misc:Input({ Title = "Distance Teleport", Flag = "DistanceTeleportInput", Desc = "How far to teleport when using Distance mode", Placeholder = tostring(ConfigState.DistanceTeleport), NumbersOnly = true, }) DistanceTeleportInput.Callback = function(v) n = tonumber(v) if n and n > 0 then ConfigState.DistanceTeleport = n end end Tabs.Misc:Space() AntiNewNPCSpawnToggle = Tabs.Misc:Toggle({ Title = "Anti New NPC Spawn", Flag = "AntiNewNPCSpawnToggle", Value = false, }) AntiNewNPCSpawnToggle.Callback = function(state) ConfigState.AntiNewNPCSpawnEnabled = state if state then startAntiBotSpawnPoint() else stopAntiBotSpawnPoint() end end AntiNewNPCSpawnTeleportTypeDropdown = Tabs.Misc:Dropdown({ Title = "Anti New Spawn Teleport Type", Flag = "AntiNewNPCSpawnTeleportTypeDropdown", Desc = "Choose teleport method for spawn avoidance", Values = {"Players", "Spawn", "Distance", "Safe Part"}, Value = ConfigState.AntiNewNPCSpawnTeleportType, Callback = function(v) ConfigState.AntiNewNPCSpawnTeleportType = v end }) AntiNewNPCSpawnDistanceInput = Tabs.Misc:Input({ Title = "New Spawn Distance", Flag = "AntiNewNPCSpawnDistanceInput", Desc = "Distance threshold for spawn detection", Placeholder = tostring(ConfigState.AntiNewNPCSpawnDistance), NumbersOnly = true, Value = tostring(ConfigState.AntiNewNPCSpawnDistance), }) AntiNewNPCSpawnDistanceInput.Callback = function(v) n = tonumber(v) if n and n > 0 then ConfigState.AntiNewNPCSpawnDistance = n end end AntiNewNPCSpawnTeleportInput = Tabs.Misc:Input({ Title = "New Spawn Teleport Distance", Flag = "AntiNewNPCSpawnTeleportInput", Desc = "How far to teleport in Distance mode for spawn", Placeholder = tostring(ConfigState.AntiNewNPCSpawnTeleport), NumbersOnly = true, }) AntiNewNPCSpawnTeleportInput.Callback = function(v) n = tonumber(v) if n and n > 0 then ConfigState.AntiNewNPCSpawnTeleport = n end end Tabs.Misc:Section({ Title = "Emote Crouch", TextSize = 20 }) Tabs.Misc:Divider() math.randomseed(tick()) local function getEmoteIDByName(name) local wanted = name:lower() for _, id in ipairs(ConfigState.PlayerData.OwnedIds()) do local config = ItemRegistry.GetConfig(id) if config and config.EquipInfo and config.EquipInfo.SlotType == "Emote" then local entry = ItemRegistry.TryGetById(id) local itemName = entry and entry.Module and entry.Module.Name local displayName = config.AppearanceInfo and config.AppearanceInfo.Name if (itemName and itemName:lower() == wanted) or (displayName and displayName:lower() == wanted) then return id end end end return nil end local function isEmoteOwned(emoteId) return ConfigState.PlayerData.Owns(emoteId) end local function setCrouching(state) SendKeybindInfo({ Key = "Crouching", Keybind = "Crouching", KeyCode = Enum.KeyCode.Unknown, GameProcessed = false, Down = state }) end for i = 1, 12 do ConfigState.emoteInputs[i] = Tabs.Misc:Input({ Title = "Emote" .. i, Placeholder = "Emote Name or ID", }) ConfigState.emoteInputs[i].Callback = function(value) ConfigState.EmoteFireServer["Emote" .. i] = value end end function triggerRandomEmote() local validEmotes = {} for i = 1, 12 do local emoteValue = ConfigState.EmoteFireServer["Emote" .. i] if emoteValue and emoteValue ~= "" then table.insert(validEmotes, emoteValue) end end if # validEmotes > 0 then math.randomseed(tick() + # validEmotes) setCrouching(true) local randomEmote = validEmotes[math.random(1, # validEmotes)] local emoteID = tonumber(randomEmote) if not emoteID then emoteID = getEmoteIDByName(randomEmote) end if emoteID and isEmoteOwned(emoteID) then pcall(function() ReplicatedStorage.Remotes.Character.CharacterTask:FireServer("Emote", emoteID) end) else WindUI:Notify({ Title = "Emote Error", Content = "Invalid emote or you do not own this emote: \"" .. tostring(emoteID or randomEmote) .. "\"", Duration = 4 }) end end end if ButtonLib and ButtonLib.Create then ButtonLib.Create:Button({ Text = "Emote Crouch", Flag = "EmoteCrouch", Visible = false, Callback = function() triggerRandomEmote() end }).Position = UDim2.new(0.5, - 125, 0.2, 0) end EmoteCrouchToggle = Tabs.Misc:Toggle({ Title = "Emote Crouch", Flag = "EmoteCrouchToggle", Desc = "Type emote name or ID - must be in your emote slot", Value = false, }) EmoteCrouchToggle.Callback = function(state) ConfigState.EmoteCrouchEnabled = state end ShowUIEmoteCrouchToggle = Tabs.Misc:Toggle({ Title = "Show UI Emote Crouch", Flag = "ShowUIEmoteCrouch", Value = false, }) ShowUIEmoteCrouchToggle.Callback = function(state) if ButtonLib and ButtonLib.EmoteCrouch then ButtonLib.EmoteCrouch:SetVisible(state) end end Tabs.Misc:Space() if UserInputService.TouchEnabled then local function carWallDy(i, depth, pressed) if not pressed then return i end return (depth - 2) + math.ceil(i * 2 / depth) end local function buildCarPedal(parent, kind) local isGas = kind == "gas" local baseSize = isGas and UDim2.new(0.34, 0, 0.58, 0) or UDim2.new(0.58, 0, 0.32, 0) local root = Instance.new("Frame") root.Name = "PedalIcon" root.AnchorPoint = Vector2.new(0.5, 0.5) root.Position = UDim2.new(0.5, 0, 0.5, 0) root.Size = baseSize root.Rotation = isGas and 8 or 0 root.BackgroundTransparency = 1 root.BorderSizePixel = 0 root.Parent = parent local shadow = Instance.new("Frame") shadow.Name = "Shadow" shadow.AnchorPoint = Vector2.new(0.5, 0.5) shadow.Position = UDim2.new(0.5, 0, 0.5, ConfigState.CarHudPedalDepth + 3) shadow.Size = UDim2.new(1, 0, 1, 0) shadow.BackgroundColor3 = Color3.new(0, 0, 0) shadow.BackgroundTransparency = 0.6 shadow.BorderSizePixel = 0 shadow.ZIndex = 1 shadow.Parent = root local shadowCorner = Instance.new("UICorner") shadowCorner.CornerRadius = UDim.new(0.2, 0) shadowCorner.Parent = shadow local pedalWalls = {} for i = ConfigState.CarHudPedalDepth, 1, - 1 do local t = ConfigState.CarHudPedalDepth > 1 and (i - 1) / (ConfigState.CarHudPedalDepth - 1) or 0 local wall = Instance.new("Frame") wall.Name = "Wall" .. i wall.AnchorPoint = Vector2.new(0.5, 0.5) wall.Position = UDim2.new(0.5, 0, 0.5, i) wall.Size = UDim2.new(1, 0, 1, 0) wall.BackgroundColor3 = ConfigState.CarHudPedalSideTop:Lerp(ConfigState.CarHudPedalSideBottom, t) wall.BorderSizePixel = 0 wall.ZIndex = 2 wall.Parent = root pedalWalls[i] = wall local wallCorner = Instance.new("UICorner") wallCorner.CornerRadius = UDim.new(0.2, 0) wallCorner.Parent = wall if i == ConfigState.CarHudPedalDepth then local wallStroke = Instance.new("UIStroke") wallStroke.Color = Color3.fromRGB(15, 15, 15) wallStroke.Thickness = 2 wallStroke.Parent = wall end end local body = Instance.new("Frame") body.Name = "Body" body.Size = UDim2.new(1, 0, 1, 0) body.Position = UDim2.new(0, 0, 0, 0) body.BackgroundColor3 = ConfigState.CarHudPedalColor body.BorderSizePixel = 0 body.ZIndex = 3 body.Parent = root local corner = Instance.new("UICorner") corner.CornerRadius = UDim.new(0.2, 0) corner.Parent = body local stroke = Instance.new("UIStroke") stroke.Color = Color3.fromRGB(15, 15, 15) stroke.Thickness = 2 stroke.Parent = body local gradient = Instance.new("UIGradient") gradient.Color = ColorSequence.new(Color3.new(1, 1, 1), Color3.fromRGB(196, 202, 212)) gradient.Rotation = 90 gradient.Parent = body local bevel = Instance.new("Frame") bevel.Name = "Bevel" bevel.AnchorPoint = Vector2.new(0.5, 0.5) bevel.Position = UDim2.new(0.5, 0, 0.5, 0) bevel.Size = UDim2.new(0.86, 0, 0.84, 0) bevel.BackgroundTransparency = 1 bevel.BorderSizePixel = 0 bevel.ZIndex = 4 bevel.Parent = body local bevelCorner = Instance.new("UICorner") bevelCorner.CornerRadius = UDim.new(0.16, 0) bevelCorner.Parent = bevel local bevelStroke = Instance.new("UIStroke") bevelStroke.Color = Color3.fromRGB(150, 156, 168) bevelStroke.Thickness = 1.5 bevelStroke.Transparency = 0.25 bevelStroke.Parent = bevel local slotCount = isGas and 5 or 3 for i = 1, slotCount do local slot = Instance.new("Frame") slot.Name = "Slot" .. i slot.AnchorPoint = Vector2.new(0.5, 0.5) slot.Position = UDim2.new(0.5, 0, i / (slotCount + 1), 0) slot.Size = UDim2.new(0.62, 0, isGas and 0.065 or 0.1, 0) slot.BackgroundColor3 = Color3.fromRGB(40, 44, 54) slot.BackgroundTransparency = 0.05 slot.BorderSizePixel = 0 slot.ZIndex = 5 slot.Parent = body local slotCorner = Instance.new("UICorner") slotCorner.CornerRadius = UDim.new(1, 0) slotCorner.Parent = slot end return { Root = root, Body = body, BaseSize = baseSize, Shadow = shadow, Depth = ConfigState.CarHudPedalDepth, Walls = pedalWalls } end local function setCarPedalPressed(parts, pressed) if not (parts and parts.Root and parts.Root.Parent) then return end local info = TweenInfo.new(0.08, Enum.EasingStyle.Quad, Enum.EasingDirection.Out) local size = parts.BaseSize if pressed then size = UDim2.new(size.X.Scale * 0.92, 0, size.Y.Scale * 0.92, 0) end TweenService:Create(parts.Root, info, { Size = size }):Play() TweenService:Create(parts.Body, info, { BackgroundColor3 = pressed and ConfigState.CarHudPedalColor:Lerp(Color3.new(0, 0, 0), 0.22) or ConfigState.CarHudPedalColor }):Play() if parts.Depth then TweenService:Create(parts.Body, info, { Position = UDim2.new(0, 0, 0, pressed and parts.Depth - 2 or 0) }):Play() for i, wall in pairs(parts.Walls) do if wall.Parent then TweenService:Create(wall, info, { Position = UDim2.new(0.5, 0, 0.5, carWallDy(i, parts.Depth, pressed)) }):Play() end end TweenService:Create(parts.Shadow, info, { Position = UDim2.new(0.5, 0, 0.5, pressed and parts.Depth + 1 or parts.Depth + 3) }):Play() end end local function buildCarPad(parent, baseSize) local root = Instance.new("Frame") root.Name = "ArrowIcon" root.AnchorPoint = Vector2.new(0.5, 0.5) root.Position = UDim2.new(0.5, 0, 0.5, 0) root.Size = baseSize root.BackgroundTransparency = 1 root.BorderSizePixel = 0 root.Parent = parent local shadow = Instance.new("Frame") shadow.Name = "Shadow" shadow.AnchorPoint = Vector2.new(0.5, 0.5) shadow.Position = UDim2.new(0.5, 0, 0.5, 3) shadow.Size = UDim2.new(1, 0, 1, 0) shadow.BackgroundColor3 = Color3.new(0, 0, 0) shadow.BackgroundTransparency = 0.6 shadow.BorderSizePixel = 0 shadow.ZIndex = 1 shadow.Parent = root local shadowCorner = Instance.new("UICorner") shadowCorner.CornerRadius = UDim.new(0.2, 0) shadowCorner.Parent = shadow local body = Instance.new("Frame") body.Name = "Body" body.Size = UDim2.new(1, 0, 1, 0) body.BackgroundColor3 = ConfigState.CarHudPedalColor body.BorderSizePixel = 0 body.ZIndex = 2 body.Parent = root local corner = Instance.new("UICorner") corner.CornerRadius = UDim.new(0.2, 0) corner.Parent = body local stroke = Instance.new("UIStroke") stroke.Color = Color3.fromRGB(15, 15, 15) stroke.Thickness = 2 stroke.Parent = body local gradient = Instance.new("UIGradient") gradient.Color = ColorSequence.new(Color3.new(1, 1, 1), Color3.fromRGB(196, 202, 212)) gradient.Rotation = 90 gradient.Parent = body local bevel = Instance.new("Frame") bevel.Name = "Bevel" bevel.AnchorPoint = Vector2.new(0.5, 0.5) bevel.Position = UDim2.new(0.5, 0, 0.5, 0) bevel.Size = UDim2.new(0.86, 0, 0.84, 0) bevel.BackgroundTransparency = 1 bevel.BorderSizePixel = 0 bevel.ZIndex = 3 bevel.Parent = body local bevelCorner = Instance.new("UICorner") bevelCorner.CornerRadius = UDim.new(0.16, 0) bevelCorner.Parent = bevel local bevelStroke = Instance.new("UIStroke") bevelStroke.Color = Color3.fromRGB(150, 156, 168) bevelStroke.Thickness = 1.5 bevelStroke.Transparency = 0.25 bevelStroke.Parent = bevel return root, body end local function buildCarArrow(parent, dir) local isLeft = dir == "left" local baseSize = UDim2.new(0.6, 0, 0.6, 0) local root, body = buildCarPad(parent, baseSize) local ratio = Instance.new("UIAspectRatioConstraint") ratio.AspectRatio = 1 ratio.Parent = root local tipX = 0.2 local depth = 0.26 local shaftEnd = 0.82 local shaftThick = 0.2 local baseX = tipX + depth local function makeArrowCopy(name, color, dy, z, transparency, overlap) local holder = Instance.new("Frame") holder.Name = name holder.Size = UDim2.new(1, 0, 1, 0) holder.Position = UDim2.new(0, 0, 0, dy) holder.BackgroundTransparency = 1 holder.BorderSizePixel = 0 holder.ZIndex = z holder.Parent = body local shaft = Instance.new("Frame") shaft.Name = "Shaft" shaft.AnchorPoint = Vector2.new(0.5, 0.5) local from = baseX - overlap local shaftCenter = (from + shaftEnd) / 2 shaft.Position = UDim2.new(isLeft and shaftCenter or (1 - shaftCenter), 0, 0.5, 0) shaft.Size = UDim2.new(shaftEnd - from, 0, shaftThick, 0) shaft.BackgroundColor3 = color shaft.BackgroundTransparency = transparency shaft.BorderSizePixel = 0 shaft.ZIndex = z shaft.Parent = holder local head = Instance.new("Frame") head.Name = "Head" head.AnchorPoint = Vector2.new(0, 0.5) head.Position = UDim2.new(isLeft and tipX or (1 - baseX), 0, 0.5, 0) head.Size = UDim2.new(depth, 0, depth * 2, 0) head.BackgroundTransparency = 1 head.BorderSizePixel = 0 head.ClipsDescendants = true head.ZIndex = z head.Parent = holder local tip = Instance.new("Frame") tip.Name = "HeadTip" tip.AnchorPoint = Vector2.new(0.5, 0.5) tip.Position = UDim2.new(isLeft and 1 or 0, 0, 0.5, 0) tip.Size = UDim2.new(math.sqrt(2), 0, math.sqrt(2) / 2, 0) tip.Rotation = 45 tip.BackgroundColor3 = color tip.BackgroundTransparency = transparency tip.BorderSizePixel = 0 tip.ZIndex = z tip.Parent = head return holder end local shadow = makeArrowCopy("ArrowShadow", Color3.new(0, 0, 0), ConfigState.CarHudArrowDepth + 3, 4, 0.55, 0) local sideWalls = {} for i = ConfigState.CarHudArrowDepth, 1, - 1 do local t = ConfigState.CarHudArrowDepth > 1 and (i - 1) / (ConfigState.CarHudArrowDepth - 1) or 0 sideWalls[i] = makeArrowCopy("ArrowSide" .. i, ConfigState.CarHudArrowSideTop:Lerp(ConfigState.CarHudArrowSideBottom, t), i, 5, 0, 0.02) end local rim = makeArrowCopy("ArrowRim", ConfigState.CarHudArrowRim, - 1, 6, 0, 0.02) local face = makeArrowCopy("ArrowFace", ConfigState.CarHudArrowFace, 0, 7, 0, 0.02) return { Root = root, Body = body, BaseSize = baseSize, Face = face, Rim = rim, Shadow = shadow, Walls = sideWalls } end local function setCarArrowPressed(parts, pressed) setCarPedalPressed(parts, pressed) if not parts then return end local info = TweenInfo.new(0.08, Enum.EasingStyle.Quad, Enum.EasingDirection.Out) local depthPx = ConfigState.CarHudArrowDepth local function sink(holder, dy) if holder and holder.Parent then TweenService:Create(holder, info, { Position = UDim2.new(0, 0, 0, dy) }):Play() end end sink(parts.Face, pressed and depthPx - 2 or 0) sink(parts.Rim, pressed and depthPx - 3 or - 1) for i, holder in pairs(parts.Walls or {}) do sink(holder, carWallDy(i, depthPx, pressed)) end sink(parts.Shadow, pressed and depthPx + 1 or depthPx + 3) end local function applyMovement() if not ConfigState.isMovementEnabled then setMovementVector(Vector3.new(0, 0, 0)) return end local x = 0 local z = 0 if ConfigState.activeDirections.left then x = x - 1 end if ConfigState.activeDirections.right then x = x + 1 end if ConfigState.activeDirections.up then z = z - 1 end if ConfigState.activeDirections.down then z = z + 1 end if x ~= 0 or z ~= 0 then local magnitude = math.sqrt(x * x + z * z) if magnitude > 1 then x = x / magnitude z = z / magnitude end setMovementVector(Vector3.new(x, 0, z)) else setMovementVector(Vector3.new(0, 0, 0)) end end function setMovementVector(direction) ConfigState.MOVE_DIRECTION = direction if ControlModule and not ConfigState.touchMoveHooked then ConfigState.touchMoveHooked = true local originalGetMove = ControlModule.GetMoveVector ControlModule.GetMoveVector = function(...) local input = originalGetMove(...) if input.Magnitude > 0.1 then return input end return ConfigState.MOVE_DIRECTION end end end local function resetAllDirections() ConfigState.activeDirections.left = false ConfigState.activeDirections.right = false ConfigState.activeDirections.up = false ConfigState.activeDirections.down = false ConfigState.activeTouches = {} applyMovement() end local function createTouchButton(config) local button = Instance.new("ImageButton") button.Name = config.Name button.ImageRectOffset = Vector2.new(1, 146) button.ImageRectSize = Vector2.new(144, 144) button.AutoButtonColor = false button.AnchorPoint = config.AnchorPoint or Vector2.new(0, 0.5) button.BackgroundColor3 = Color3.new(0, 0, 0) button.BackgroundTransparency = 0.5 button.Position = config.Position button.Size = config.Size button.Parent = config.Parent button.Visible = config.Visible ~= nil and config.Visible or false local corner = Instance.new("UICorner") corner.BottomLeftRadius = UDim.new(1, 0) corner.BottomRightRadius = UDim.new(1, 0) corner.TopLeftRadius = UDim.new(1, 0) corner.TopRightRadius = UDim.new(1, 0) corner.Parent = button local stroke = Instance.new("UIStroke") stroke.Color = Color3.new(1, 1, 1) stroke.Thickness = 3 stroke.Transparency = 0.8 stroke.Parent = button local innerFrame = Instance.new("Frame") innerFrame.AnchorPoint = Vector2.new(0.5, 0.5) innerFrame.BackgroundTransparency = 1 innerFrame.Position = UDim2.new(0.5, 0, 0.5, 0) innerFrame.Size = UDim2.new(1, 6, 1, 6) innerFrame.Parent = button local innerStroke = Instance.new("UIStroke") innerStroke.Thickness = 2 innerStroke.Transparency = 0.6 innerStroke.Parent = innerFrame local innerCorner = Instance.new("UICorner") innerCorner.BottomLeftRadius = UDim.new(1, 0) innerCorner.BottomRightRadius = UDim.new(1, 0) innerCorner.TopLeftRadius = UDim.new(1, 0) innerCorner.TopRightRadius = UDim.new(1, 0) innerCorner.Parent = innerFrame local pedalParts = nil local arrowParts = nil if config.Pedal then pedalParts = buildCarPedal(button, config.Pedal) elseif config.Arrow then arrowParts = buildCarArrow(button, config.Arrow) end local function handlePress() setCarPedalPressed(pedalParts, true) setCarArrowPressed(arrowParts, true) if ConfigState.isMovementEnabled and config.Callback then config.Callback(true) end end local function handleRelease() setCarPedalPressed(pedalParts, false) setCarArrowPressed(arrowParts, false) if ConfigState.isMovementEnabled and config.Callback then config.Callback(false) end end button.MouseButton1Down:Connect(handlePress) button.MouseButton1Up:Connect(handleRelease) button.MouseLeave:Connect(handleRelease) local function onTouchStart(input, processed) if processed then return end if input.UserInputType == Enum.UserInputType.Touch then local touchPos = input.Position local buttonSize = button.AbsoluteSize local buttonPos = button.AbsolutePosition if touchPos.X >= buttonPos.X and touchPos.X <= buttonPos.X + buttonSize.X and touchPos.Y >= buttonPos.Y and touchPos.Y <= buttonPos.Y + buttonSize.Y then if not ConfigState.activeTouches[input] then ConfigState.activeTouches[input] = true handlePress() end end end end local function onTouchEnd(input, processed) if input.UserInputType == Enum.UserInputType.Touch and ConfigState.activeTouches[input] then ConfigState.activeTouches[input] = nil handleRelease() end end UserInputService.InputBegan:Connect(onTouchStart) UserInputService.InputEnded:Connect(onTouchEnd) return button end local function updateMovementSystem() local shouldBeActive = GetDrivenVehicle() ~= nil local wasActive = ConfigState.isMovementEnabled ConfigState.isMovementEnabled = shouldBeActive if wasActive and not shouldBeActive then resetAllDirections() end for _, button in pairs(ConfigState.movementButtons) do if button and button.Parent and button.Visible ~= shouldBeActive then button.Visible = shouldBeActive end end end local function startDrivingWatch() if ConfigState.drivingLoop then ConfigState.drivingLoop:Disconnect() end ConfigState.drivingLoop = HeartbeatLoop(0.1, updateMovementSystem) updateMovementSystem() end local function CreateHUDButtons() if not PlayerGui then return end local gameGUI = PlayerGui:FindFirstChild("Game") if not gameGUI then return end local hud = gameGUI:FindFirstChild("HUD") if not hud then return end local mobile = hud:FindFirstChild("Mobile") if not mobile then return end local rightPanel = mobile:FindFirstChild("Right") if not rightPanel then return end local leftPanel = mobile:FindFirstChild("Left") if not leftPanel then return end local leftMobileFrame = leftPanel:FindFirstChild("Mobile") if not leftMobileFrame then return end local rightMobileFrame = rightPanel:FindFirstChild("Mobile") if not rightMobileFrame then return end for _, oldName in ipairs({"VUp", "VDown"}) do local old = rightPanel:FindFirstChild(oldName) if old then old:Destroy() end end if not rightMobileFrame:FindFirstChild("VUp") then ConfigState.movementButtons.VUp = createTouchButton({ Name = "VUp", Parent = rightMobileFrame, Pedal = ConfigState.CarHudPedals.VUp, Visible = false, Position = UDim2.new(-1.5, 0, -0.7, 0), Size = UDim2.new(1.39, 0, 1.39, 0), Callback = function(isPressed) if isPressed then ConfigState.activeDirections.up = true else ConfigState.activeDirections.up = false end applyMovement() end }) else ConfigState.movementButtons.VUp = rightMobileFrame.VUp end if not rightMobileFrame:FindFirstChild("VDown") then ConfigState.movementButtons.VDown = createTouchButton({ Name = "VDown", Parent = rightMobileFrame, Pedal = ConfigState.CarHudPedals.VDown, Visible = false, Position = UDim2.new(-3.2, 0, -0.7, 0), Size = UDim2.new(1.39, 0, 1.39, 0), Callback = function(isPressed) if isPressed then ConfigState.activeDirections.down = true else ConfigState.activeDirections.down = false end applyMovement() end }) else ConfigState.movementButtons.VDown = rightMobileFrame.VDown end if not leftMobileFrame:FindFirstChild("VLeft") then ConfigState.movementButtons.VLeft = createTouchButton({ Name = "VLeft", Parent = leftMobileFrame, Arrow = "left", Visible = false, Position = UDim2.new(0.4, 0, 0.66, 0), Size = UDim2.new(0.3, 0, 0.3, 0), Callback = function(isPressed) if isPressed then ConfigState.activeDirections.left = true else ConfigState.activeDirections.left = false end applyMovement() end }) else ConfigState.movementButtons.VLeft = leftMobileFrame.VLeft end if not leftMobileFrame:FindFirstChild("VRight") then ConfigState.movementButtons.VRight = createTouchButton({ Name = "VRight", Parent = leftMobileFrame, Arrow = "right", Visible = false, Position = UDim2.new(0.8, 0, 0.66, 0), Size = UDim2.new(0.3, 0, 0.3, 0), Callback = function(isPressed) if isPressed then ConfigState.activeDirections.right = true else ConfigState.activeDirections.right = false end applyMovement() end }) else ConfigState.movementButtons.VRight = leftMobileFrame.VRight end startDrivingWatch() end local function RemoveVehicleHUD() for name, button in pairs(ConfigState.movementButtons) do if button and button.Parent then button:Destroy() end end ConfigState.movementButtons = {} if ConfigState.drivingLoop then ConfigState.drivingLoop:Disconnect() ConfigState.drivingLoop = nil end ConfigState.isMovementEnabled = false resetAllDirections() end local function AddVehicleHUD() local function checkGameExists() if PlayerGui:FindFirstChild("Game") then CreateHUDButtons() else PlayerGui.ChildAdded:Connect(function(child) if child.Name == "Game" then CreateHUDButtons() end end) end end checkGameExists() end function ConfigState.AutoCam.IsButtonHeld() return ConfigState.isMovementEnabled == true and (ConfigState.activeDirections.left or ConfigState.activeDirections.right or ConfigState.activeDirections.up or ConfigState.activeDirections.down) and true or false end function ConfigState.AutoCam.Flat(v) local f = Vector3.new(v.X, 0, v.Z) if f.Magnitude < 0.001 then return nil end return f.Unit end function ConfigState.AutoCam.GetRoot(now) local root = ConfigState.AutoCam.RootPart if root and root.Parent and now - ConfigState.AutoCam.RootCheckedAt < 0.3 then return root end ConfigState.AutoCam.RootCheckedAt = now root = nil local seat = Humanoid and Humanoid.SeatPart if seat then root = seat.AssemblyRootPart or seat elseif HumanoidRootPart then local assemblyRoot = HumanoidRootPart.AssemblyRootPart if assemblyRoot and assemblyRoot ~= HumanoidRootPart then root = assemblyRoot else local folder = workspace:FindFirstChild("Vehicles") local bestDist = 40 if folder then for _, model in ipairs(folder:GetChildren()) do local part = nil if model:IsA("Model") then part = model.PrimaryPart or model:FindFirstChildWhichIsA("BasePart", true) elseif model:IsA("BasePart") then part = model end if part then local dist = (part.Position - HumanoidRootPart.Position).Magnitude if dist < bestDist then bestDist = dist root = part.AssemblyRootPart or part end end end end root = root or HumanoidRootPart end end ConfigState.AutoCam.RootPart = root return root end function ConfigState.AutoCam.GetHeading(root, now) local cf = root.CFrame local vel = root.AssemblyLinearVelocity local velFlat = Vector3.new(vel.X, 0, vel.Z) local speed = velFlat.Magnitude local cfg = ConfigState.AutoCam.Config if speed >= cfg.CalibrateSpeed and ConfigState.AutoCam.UpSince > 0 and now - ConfigState.AutoCam.UpSince >= cfg.CalibrateHold then local dir = velFlat.Unit local bestAxis, bestDot = nil, 0.8 for _, candidate in ipairs(ConfigState.AutoCam.Axes) do local world = ConfigState.AutoCam.Flat(cf:VectorToWorldSpace(candidate)) if world then local d = dir:Dot(world) if d > bestDot then bestAxis, bestDot = candidate, d end end end if bestAxis then ConfigState.AutoCam.ForwardAxis[root] = bestAxis end end local axis = ConfigState.AutoCam.ForwardAxis[root] or ConfigState.AutoCam.Axes[1] local forward = ConfigState.AutoCam.Flat(cf:VectorToWorldSpace(axis)) if not forward and speed > 1 then forward = velFlat.Unit end if cfg.ReverseFollow and forward and ConfigState.activeDirections.down and not ConfigState.activeDirections.up then local along = velFlat:Dot(forward) if ConfigState.AutoCam.Reversing then if along > -cfg.ReverseExit then ConfigState.AutoCam.Reversing = false end elseif along < -cfg.ReverseEnter then ConfigState.AutoCam.Reversing = true end else ConfigState.AutoCam.Reversing = false end if ConfigState.AutoCam.Reversing and forward then forward = Vector3.new(-forward.X, 0, -forward.Z) end return forward, speed end function ConfigState.AutoCam.ComputeYaw(err, dt, engage, speed) local cfg = ConfigState.AutoCam.Config local mag = math.abs(err) - cfg.Deadzone if mag <= 0 or engage <= 0 then return 0 end local sign = err > 0 and 1 or -1 local speedFactor = cfg.MinSpeedFactor + (1 - cfg.MinSpeedFactor) * (speed / cfg.FullSpeed) speedFactor = math.max(cfg.MinSpeedFactor, math.min(1, speedFactor)) local rate = math.min(mag * cfg.FollowGain, cfg.MaxRate) * speedFactor * engage return sign * math.min(rate * dt, mag) end function ConfigState.AutoCam.Step(dt) ConfigState.AutoCam.FrameYaw = 0 if not ConfigState.AutoCam.Enabled then ConfigState.AutoCam.Engage = 0 return end local cfg = ConfigState.AutoCam.Config local now = os.clock() local held = ConfigState.AutoCam.IsButtonHeld() if ConfigState.activeDirections.up and not ConfigState.activeDirections.down and held then if ConfigState.AutoCam.UpSince == 0 then ConfigState.AutoCam.UpSince = now end else ConfigState.AutoCam.UpSince = 0 end local camera = workspace.CurrentCamera if held and now >= ConfigState.AutoCam.ManualUntil and camera then ConfigState.AutoCam.Engage = math.min(1, ConfigState.AutoCam.Engage + dt / cfg.EngageTime) else ConfigState.AutoCam.Engage = math.max(0, ConfigState.AutoCam.Engage - dt / cfg.ReleaseTime) end if ConfigState.AutoCam.Engage <= 0 or not camera then return end local root = ConfigState.AutoCam.GetRoot(now) if not root then return end local heading, speed = ConfigState.AutoCam.GetHeading(root, now) local look = ConfigState.AutoCam.Flat(camera.CFrame.LookVector) if not heading or not look then return end local err = math.atan2(heading.X * -look.Z + heading.Z * look.X, heading.X * look.X + heading.Z * look.Z) local yaw = ConfigState.AutoCam.ComputeYaw(err, dt, ConfigState.AutoCam.Engage, speed) if ConfigState.AutoCam.SensitivityOuter then if ConfigState.MouseSensitivityEnabled and UserInputService.MouseEnabled then yaw = yaw / math.max(ConfigState.MouseSensitivityValue, 0.05) elseif ConfigState.TouchSensitivityEnabled and UserInputService.TouchEnabled then yaw = yaw / math.max(ConfigState.TouchSensitivityValue, 0.05) end end ConfigState.AutoCam.FrameYaw = yaw end function ConfigState.AutoCam.InstallHook() if ConfigState.AutoCam.Hooked then return true end if not (CameraInput and CameraInput.getRotation) then return false end local original = CameraInput.getRotation ConfigState.AutoCam.OriginalGetRotation = original ConfigState.AutoCam.SensitivityOuter = (ConfigState.cameraInputModule == nil) ConfigState.AutoCam.Hook = function(...) local rotation = original(...) if not ConfigState.AutoCam.Enabled then return rotation end local cfg = ConfigState.AutoCam.Config if rotation.Magnitude > cfg.ManualEpsilon then ConfigState.AutoCam.ManualUntil = os.clock() + cfg.ManualHold return rotation end local yaw = ConfigState.AutoCam.FrameYaw if yaw ~= 0 and os.clock() >= ConfigState.AutoCam.ManualUntil then return rotation + Vector2.new(yaw, 0) end return rotation end CameraInput.getRotation = ConfigState.AutoCam.Hook ConfigState.AutoCam.Hooked = true return true end function ConfigState.AutoCam.Start() if ConfigState.AutoCam.Enabled then return end if not ConfigState.AutoCam.InstallHook() then warn("[NEXRIFT] Auto camera turn: CameraInput.getRotation not found") return end ConfigState.AutoCam.Enabled = true ConfigState.AutoCam.Engage = 0 ConfigState.AutoCam.FrameYaw = 0 ConfigState.AutoCam.ManualUntil = 0 ConfigState.AutoCam.UpSince = 0 ConfigState.AutoCam.Reversing = false ConfigState.AutoCam.RootPart = nil pcall(RunService.UnbindFromRenderStep, RunService, "NexriftAutoCam") RunService:BindToRenderStep("NexriftAutoCam", Enum.RenderPriority.Camera.Value - 1, function(dt) local ok, err = pcall(ConfigState.AutoCam.Step, math.min(dt, 0.1)) if not ok and not ConfigState.AutoCam.Warned then ConfigState.AutoCam.Warned = true warn("[NEXRIFT] Auto camera turn error: " .. tostring(err)) end end) end function ConfigState.AutoCam.Stop() ConfigState.AutoCam.Enabled = false ConfigState.AutoCam.FrameYaw = 0 ConfigState.AutoCam.Engage = 0 pcall(RunService.UnbindFromRenderStep, RunService, "NexriftAutoCam") if ConfigState.AutoCam.Hooked and ConfigState.AutoCam.Hook and CameraInput.getRotation == ConfigState.AutoCam.Hook then CameraInput.getRotation = ConfigState.AutoCam.OriginalGetRotation ConfigState.AutoCam.Hooked = false ConfigState.AutoCam.Hook = nil end end function ConfigState.CarSteer.Install() if ConfigState.CarSteer.Hooked then return true end local okCar, Car = pcall(require, ReplicatedStorage.Objects.Game.Vehicle.DriverTypes.Car) if not okCar or type(Car) ~= "table" or type(Car.Update) ~= "function" or type(Car.SetSteer) ~= "function" then return false end local originalUpdate = Car.Update local originalSetSteer = Car.SetSteer ConfigState.CarSteer.Class = Car ConfigState.CarSteer.OriginalUpdate = originalUpdate ConfigState.CarSteer.OriginalSetSteer = originalSetSteer ConfigState.CarSteer.Update = function(self, dt, ...) if not (ConfigState.CarSteer.Hooked and self.Active and self.CanSteer) then return originalUpdate(self, dt, ...) end local okMove, move = pcall(ControlModule.GetMoveVector, ControlModule) local x = okMove and move and move.X or 0 x = math.clamp(x, -1, 1) self.NexriftSteerTarget = math.abs(x) < 0.04 and 0 or x self.NexriftSteerDt = dt local ok, err = pcall(originalUpdate, self, dt, ...) self.NexriftSteerTarget = nil if not ok then error(err, 0) end end ConfigState.CarSteer.SetSteer = function(self, value, ...) local target = self.NexriftSteerTarget if ConfigState.CarSteer.Hooked and target ~= nil then local current = self.Steer or 0 local rate = math.max(self.DriverConfig and self.DriverConfig.SteerRate or 0.2, 0.01) local step = (self.NexriftSteerDt or 0) / rate value = current + math.clamp(target - current, - step, step) end return originalSetSteer(self, value, ...) end Car.Update = ConfigState.CarSteer.Update Car.SetSteer = ConfigState.CarSteer.SetSteer ConfigState.CarSteer.Hooked = true return true end function ConfigState.CarSteer.Remove() local Car = ConfigState.CarSteer.Class if Car and ConfigState.CarSteer.Hooked then if Car.Update == ConfigState.CarSteer.Update then Car.Update = ConfigState.CarSteer.OriginalUpdate end if Car.SetSteer == ConfigState.CarSteer.SetSteer then Car.SetSteer = ConfigState.CarSteer.OriginalSetSteer end end ConfigState.CarSteer.Hooked = false end CarSteerUnhook = ConfigState.CarSteer.Remove CarsHUDShutdown = function() RemoveVehicleHUD() ConfigState.AutoCam.Stop() ConfigState.CarSteer.Remove() end AddVehicleHUD() ConfigState.AutoCam.Start() if not ConfigState.CarSteer.Install() then warn("[NEXRIFT] Car steering patch: Car driver module not found") end end Tabs.Misc:Space() AntiRagdoll = Tabs.Misc:Toggle({ Title = "Anti Ragdoll", }) AntiRagdoll.Callback = function(s) if s then StartAntiRagdoll() else StopAntiRagdoll() end end Tabs.Misc:Section({ Title = "TAS", TextSize = 20 }) Tabs.Misc:Divider() getChar = function() if Character then return Character else LocalPlayer.CharacterAdded:Wait() return getChar() end end StartTASRecording = function() ConfigState.Frames = {} ConfigState.Running = true ConfigState.TimeStart = tick() if RecordConnection then RecordConnection:Disconnect() end RecordConnection = game:GetService("RunService").Heartbeat:Connect(function() if not ConfigState.Running then return end Character = getChar() table.insert(ConfigState.Frames, { Character.HumanoidRootPart.CFrame, Character.Humanoid:GetState().Value, tick() - ConfigState.TimeStart }) end) end StopTASRecording = function() ConfigState.Running = false if RecordConnection then RecordConnection:Disconnect() RecordConnection = nil end end PlayTASRecording = function() Character = getChar() TimePlay = tick() FrameCount = # ConfigState.Frames OldFrame = 1 TASLoop = game:GetService("RunService").Heartbeat:Connect(function() CurrentTime = tick() if (CurrentTime - TimePlay) >= ConfigState.Frames[FrameCount][3] then TASLoop:Disconnect() return end for i = OldFrame, math.min(OldFrame + 60, FrameCount) do Frame = ConfigState.Frames[i] if Frame and Frame[3] <= (CurrentTime - TimePlay) then OldFrame = i Character.HumanoidRootPart.CFrame = Frame[1] Character.Humanoid:ChangeState(Frame[2]) end end end) end Tabs.Misc:Button({ Title = "Start recording", Color = Color3.fromHex("#30FF6A"), Callback = StartTASRecording }) Tabs.Misc:Button({ Title = "Stop recording", Color = Color3.fromHex("#ff4830"), Callback = StopTASRecording }) Tabs.Misc:Button({ Title = "Play", Color = Color3.fromHex("#30FF6A"), Callback = PlayTASRecording }) function ApplyTouchFlingVelocity() local chr = LocalPlayer.Character local hrp = chr and chr:FindFirstChild("HumanoidRootPart") if not hrp then return function() end end local state = 1 local vel = hrp.Velocity local conns = {} local function alive() return ConfigState.flingActive and chr and hrp and hrp.Parent end local function stop() for _, c in ipairs(conns) do c:Disconnect() end conns = {} end hrp.Velocity = vel * ConfigState.flingPower + Vector3.new(0, ConfigState.flingPower, 0) table.insert(conns, RunService.RenderStepped:Connect(function() if state ~= 1 then return end if not alive() then return stop() end hrp.Velocity = vel state = 2 end)) table.insert(conns, RunService.Stepped:Connect(function() if state ~= 2 then return end if not alive() then return stop() end hrp.Velocity = vel + Vector3.new(0, ConfigState.flingMoveDelta, 0) ConfigState.flingMoveDelta = - ConfigState.flingMoveDelta state = 3 end)) table.insert(conns, RunService.Heartbeat:Connect(function() if state ~= 3 then return end if not alive() then return stop() end vel = hrp.Velocity hrp.Velocity = vel * ConfigState.flingPower + Vector3.new(0, ConfigState.flingPower, 0) state = 1 end)) return stop end function EnableTouchFling() if ConfigState.flingStopFn then ConfigState.flingStopFn() ConfigState.flingStopFn = nil end ConfigState.flingActive = true ConfigState.flingStopFn = ApplyTouchFlingVelocity() end function DisableTouchFling() if ConfigState.flingStopFn then ConfigState.flingStopFn() ConfigState.flingStopFn = nil end ConfigState.flingActive = false local chr = LocalPlayer.Character if chr then local hrp = chr:FindFirstChild("HumanoidRootPart") if hrp then hrp.Velocity = Vector3.new(0, 0, 0) hrp.RotVelocity = Vector3.new(0, 0, 0) end end end function SyncTouchFlingState() if (ConfigState.hiddenfling or ConfigState.flingTargetEnabled) and not ConfigState.flingStopFn then EnableTouchFling() elseif not (ConfigState.hiddenfling or ConfigState.flingTargetEnabled) and ConfigState.flingStopFn then DisableTouchFling() end end function FindRandomFlingTargetHRP() local playersFolder = Workspace:FindFirstChild("Players") if not playersFolder then return nil end local models = playersFolder:GetChildren() local filtered = {} local count = 0 for i = 1, # models do local model = models[i] if model:IsA("Model") and model ~= LocalPlayer.Character then local modelName = model.Name local attrName = model:GetAttribute("Name") local attrTeam = model:GetAttribute("Team") local include = true if ConfigState.flingTeamAttribute and ConfigState.flingTeamAttribute ~= "" then if attrTeam ~= ConfigState.flingTeamAttribute then include = false end end if include and ConfigState.flingTargetName and ConfigState.flingTargetName ~= "" then local tn = ConfigState.flingTargetName if tn:sub(1, 1) == "!" then local excludePattern = tn:sub(2) local haystack = (modelName or "") .. " " .. (attrName or "") .. " " .. (attrTeam or "") if haystack:lower():find(excludePattern:lower(), 1, true) then include = false end elseif tn:sub(1, 2) == "==" then local exact = tn:sub(3) local lowerExact = exact:lower() if not (modelName:lower() == lowerExact or (attrName and attrName:lower() == lowerExact) or (attrTeam and attrTeam:lower() == lowerExact)) then include = false end else local pattern = tn:lower() local haystack = (modelName or "") .. " " .. (attrName or "") .. " " .. (attrTeam or "") if not haystack:lower():find(pattern, 1, true) then include = false end end end if include then local hrp = model:FindFirstChild("HumanoidRootPart") if hrp then count = count + 1 filtered[count] = hrp end end end end if count == 0 then return nil end return filtered[math.random(count)] end function SelectNewFlingTarget() ConfigState.flingCurrentTargetHRP = FindRandomFlingTargetHRP() ConfigState.flingTargetChangeTime = tick() end function SyncFlingTargetHeartbeat() if ConfigState.flingTargetEnabled then if not ConfigState.flingTargetHeartbeat then ConfigState.flingCurrentTargetHRP = nil ConfigState.flingTargetChangeTime = 0 ConfigState.flingTargetHeartbeat = RunService.Heartbeat:Connect(function() local chr = LocalPlayer.Character if not chr then return end local hrp = chr:FindFirstChild("HumanoidRootPart") if not hrp then return end if not ConfigState.flingCurrentTargetHRP or not ConfigState.flingCurrentTargetHRP.Parent or (tick() - ConfigState.flingTargetChangeTime >= 10) then SelectNewFlingTarget() end if ConfigState.flingCurrentTargetHRP then local offset = Vector3.new(0, math.random(- 5, 5), 0) local targetCFrame = ConfigState.flingCurrentTargetHRP.CFrame + offset teleportToCFrame(targetCFrame) end end) end else if ConfigState.flingTargetHeartbeat then ConfigState.flingTargetHeartbeat:Disconnect() ConfigState.flingTargetHeartbeat = nil end ConfigState.flingCurrentTargetHRP = nil ConfigState.flingTargetChangeTime = 0 end end function OnFlingCharacterAdded(character) if ConfigState.hiddenfling or ConfigState.flingTargetEnabled then task.wait(1) SyncTouchFlingState() SyncFlingTargetHeartbeat() else task.wait(0.5) local hrp = character:FindFirstChild("HumanoidRootPart") if hrp then hrp.Velocity = Vector3.new(0, 0, 0) hrp.RotVelocity = Vector3.new(0, 0, 0) end end end Tabs.Utility:Space() TouchFlingToggle = Tabs.Utility:Toggle({ Title = "Touch Fling", Desc = "You need to get in a vehicle to fling Bots or your stupid friend", Flag = "TouchFlingToggle", Value = false, }) TouchFlingToggle.Callback = function(state) ConfigState.hiddenfling = state if state then if not ConfigState.flingRespawnConn then ConfigState.flingRespawnConn = LocalPlayer.CharacterAdded:Connect(OnFlingCharacterAdded) end else if ConfigState.flingRespawnConn then ConfigState.flingRespawnConn:Disconnect() ConfigState.flingRespawnConn = nil end end SyncTouchFlingState() SyncFlingTargetHeartbeat() end FlingTargetToggle = Tabs.Utility:Toggle({ Title = "Fling Target", Flag = "FlingTargetToggle", Value = false, }) FlingTargetToggle.Callback = function(state) ConfigState.flingTargetEnabled = state SyncTouchFlingState() SyncFlingTargetHeartbeat() end TargetName = Tabs.Utility:Input({ Title = "Target name", Placeholder = "Enter target name (use ! to skip, == for exact)", }) TargetName.Callback = function(value) ConfigState.flingTargetName = value or "" end AttributeTeam = Tabs.Utility:Input({ Title = "Attribute Team", Placeholder = "Enter team attribute (optional)", }) AttributeTeam.Callback = function(value) ConfigState.flingTeamAttribute = value or "" end FlingPower = Tabs.Utility:Input({ Title = "Fling Power", Placeholder = "Enter fling power (default: 1e35)", }) FlingPower.Callback = function(value) if value and value ~= "" then ConfigState.flingPower = tonumber(value) or 1e35 end end Tabs.Utility:Space() InvisWallsCollide = Tabs.Utility:Toggle({ Title = "Invis Walls Collide", Value = true, }) InvisWallsCollide.Callback = function(state) local invisPartsFolder = workspace:FindFirstChild("Map") if invisPartsFolder then invisPartsFolder = invisPartsFolder:FindFirstChild("InvisParts") end if not invisPartsFolder then invisPartsFolder = workspace:FindFirstChild("Game") if invisPartsFolder then invisPartsFolder = invisPartsFolder:FindFirstChild("Map") if invisPartsFolder then invisPartsFolder = invisPartsFolder:FindFirstChild("InvisParts") end end end if invisPartsFolder then for _, obj in ipairs(invisPartsFolder:GetDescendants()) do if obj:IsA("BasePart") then obj.CanCollide = state end end end end Tabs.Utility:Space() TimeChangerInput = Tabs.Utility:Input({ Title = "Set Time", Value = "12:00", Flag = "TimeChangerInput", Placeholder = "HH:MM" }) TimeChangerInput.Callback = function(value) value = value:gsub("^%s*(.-)%s*$", "%1") local h_str, m_str = value:match("(%d+):(%d+)") if h_str and m_str then local h = tonumber(h_str) local m = tonumber(m_str) if h and m and h >= 0 and h <= 23 and m >= 0 and m <= 59 and # h_str <= 2 and # m_str <= 2 then local totalHours = h + (m / 60) Lighting.ClockTime = totalHours WindUI:Notify({ Title = "Time Updated", Content = "In-game time set to " .. string.format("%02d:%02d", h, m), Duration = 3 }) else WindUI:Notify({ Title = "Invalid Time", Content = "Please enter a valid time between 00:00 and 23:59.", Duration = 3 }) end else WindUI:Notify({ Title = "Invalid Format", Content = "Please use the HH:MM format (e.g., 14:30).", Duration = 3 }) end end function lag() local duration = ConfigState.lagDuration or 0.5 local method = ConfigState.lagMethod or "CPU Cycle" if method == "CPU Cycle" then pcall(setfflag, "MaxMissedWorldStepsRemembered", "1") local start = tick() local function spin() if tick() - start >= duration then return end local a = math.random(1, 1000000) * math.random(1, 1000000) a = a / math.random(1, 10000) return spin() end spin() elseif method == "OS.ClockFFlag" then pcall(setfflag, "MaxMissedWorldStepsRemembered", "10000001000000") local start = os.clock() local function spin() if os.clock() - start < duration then return spin() end end spin() end end function loadLagSystem() if ConfigState.lagSystemLoaded then return end ConfigState.lagSystemLoaded = true end function unloadLagSystem() if not ConfigState.lagSystemLoaded then return end ConfigState.lagSystemLoaded = false ConfigState.isLagActive = false end function checkLagState() local shouldLoad = ConfigState.lagSwitchEnabled if shouldLoad and not ConfigState.lagSystemLoaded then loadLagSystem() elseif not shouldLoad and ConfigState.lagSystemLoaded then unloadLagSystem() end end Tabs.Utility:Space() ButtonLib.Create:Button({ Text = "Lag Switch", Flag = "LagSwitch", Visible = false, Callback = function() ConfigState.isLagActive = task.spawn(lag) end }).Position = UDim2.new(0.5, - 125, 0.2, 0) LagSwitchToggle = Tabs.Utility:Toggle({ Title = "Lag Switch", Flag = "LagSwitchToggle", Icon = "zap", Value = false, }) LagSwitchToggle.Callback = function(state) ConfigState.lagSwitchEnabled = state checkLagState() end ShowUILagSwitchToggle = Tabs.Utility:Toggle({ Title = "Show UI Lag Switch", Flag = "ShowUILagSwitch", Value = false, }) ShowUILagSwitchToggle.Callback = function(state) if ButtonLib and ButtonLib.LagSwitch then ButtonLib.LagSwitch:SetVisible(state) end end LagMethodDropdown = Tabs.Utility:Dropdown({ Title = "Lag Method", Flag = "LagMethodDropdown", Values = {"CPU Cycle", "OS.ClockFFlag"}, Value = "CPU Cycle", Callback = function(value) ConfigState.lagMethod = value end }) LagDurationInput = Tabs.Utility:Input({ Title = "Lag Duration (seconds)", Flag = "LagDurationInput", Placeholder = "0.5", Value = tostring(ConfigState.lagDuration), NumbersOnly = true, }) LagDurationInput.Callback = function(text) local n = tonumber(text) if n and n > 0 then ConfigState.lagDuration = n end end Players.PlayerRemoving:Connect(function(leavingPlayer) if leavingPlayer == Players then unloadLagSystem() end end) checkLagState() Tabs.Utility:Space() ConfigState.originalGameGravity = workspace.Gravity ConfigState.GravityValue = workspace.Gravity GravityToggle = Tabs.Utility:Toggle({ Title = "Custom Gravity", Flag = "GravityToggle", Value = false, }) GravityToggle.Callback = function(state) ConfigState.CustomGravity = state if state then workspace.Gravity = ConfigState.GravityValue else workspace.Gravity = ConfigState.originalGameGravity end end ButtonLib.Create:Toggle({ Text = "Gravity", Flag = "GravityToggle", Default = false, Visible = false, Callback = function(s) if GravityToggle then GravityToggle:Set(s) end end }).Position = UDim2.new(0.5, - 125, 0.4, 0) ShowGravityButtonToggle = Tabs.Utility:Toggle({ Title = "Show UI Gravity", Flag = "ShowGravityButton", Value = false, }) ShowGravityButtonToggle.Callback = function(state) ConfigState.ShowGravityButton = state if ButtonLib and ButtonLib.GravityToggle then ButtonLib.GravityToggle:SetVisible(state) end end GravityInput = Tabs.Utility:Input({ Title = "Gravity Value", Flag = "GravityInput", Placeholder = tostring(ConfigState.originalGameGravity), Value = tostring(ConfigState.GravityValue), }) GravityInput.Callback = function(text) local num = tonumber(text) if num then ConfigState.GravityValue = num if ConfigState.CustomGravity then workspace.Gravity = num end end end if ConfigState.CustomGravity then workspace.Gravity = ConfigState.GravityValue else workspace.Gravity = ConfigState.originalGameGravity end Tabs.Utility:Space() ConfigState.originalUse = JumpPadModule.Use JumpPadToggle = Tabs.Utility:Toggle({ Title = "Jump Pad Bounce Modifier", Flag = "JumpPadToggle", Value = false, }) JumpPadToggle.Callback = function(state) if state then function JumpPadModule.Use(p1, p2) if p2 == nil or (p2 ~= Players.LocalPlayer.Character or p2:GetAttribute("JumpPadInEffect") == true) then return ConfigState.originalUse(p1, p2) end p1.Model.AnimationController:LoadAnimation(p1.Model.Animations.Use):Play(0.1) p1.Model.BoundingBox.Launch:Play() Players.LocalPlayer.Character.HumanoidRootPart:ApplyImpulse(Vector3.new(0, ConfigState.JumpPadValue, 0)) p2:SetAttribute("JumpPadInEffect", true) task.spawn(function() task.wait(1.5) p2:SetAttribute("JumpPadInEffect", nil) end) end else JumpPadModule.Use = ConfigState.originalUse end end JumpPadValueInput = Tabs.Utility:Input({ Title = "Jump Value", Flag = "JumpPadValueInput", Placeholder = "0", Value = "360", NumbersOnly = true, }) JumpPadValueInput.Callback = function(text) local num = tonumber(text) if num then ConfigState.JumpPadValue = num end end Tabs.Utility:Space() NoRenderToggle = Tabs.Utility:Toggle({ Title = "No Render", Flag = "NoRenderToggle", Desc = "Disable 3D rendering for performance", Value = false, }) NoRenderToggle.Callback = function(state) ConfigState.NoRender = state game:GetService("RunService"):Set3dRenderingEnabled(not state) if state then local gui = Instance.new("ScreenGui") gui.Name = "NoRenderBackground" gui.DisplayOrder = - 99999 gui.IgnoreGuiInset = true gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling gui.ResetOnSpawn = false local frame = Instance.new("Frame") frame.Size = UDim2.new(1, 0, 1, 0) frame.BackgroundColor3 = ConfigState.NoRenderColor frame.BorderSizePixel = 0 frame.Parent = gui gui.Parent = PlayerGui else local gui = PlayerGui:FindFirstChild("NoRenderBackground") if gui then gui:Destroy() end end end NoRenderColorPicker = Tabs.Utility:Colorpicker({ Title = "No Render Color", Flag = "NoRenderColorPicker", Desc = "Choose background color when No Render is enabled", Default = Color3.fromRGB(0, 0, 0), Transparency = 0, Callback = function(color) ConfigState.NoRenderColor = color if ConfigState.NoRender then local gui = PlayerGui:FindFirstChild("NoRenderBackground") if gui then local frame = gui:FindFirstChildOfClass("Frame") if frame then frame.BackgroundColor3 = color end end end end }) Tabs.Utility:Space() RemoveTexturesButton = Tabs.Utility:Button({ Title = "Remove Textures", Callback = function() for _, part in ipairs(workspace:GetDescendants()) do if part:IsA("BasePart") or part:IsA("MeshPart") or part:IsA("UnionOperation") or part:IsA("WedgePart") or part:IsA("CornerWedgePart") then part.Material = Enum.Material.SmoothPlastic if part:IsA("MeshPart") and part.TextureID ~= "" then part.TextureID = "" end for _, texture in ipairs(part:GetChildren()) do if texture:IsA("Texture") then texture.Texture = "rbxassetid://0" elseif texture:IsA("Decal") then texture.Texture = "rbxassetid://0" end end end end WindUI:Notify({ Title = "Textures Removed", Content = "All textures and materials have been removed", Duration = 3 }) end }) Tabs.Utility:Button({ Title = "Clear MaterialService", Desc = "Remove All Clear MaterialService Texture", Callback = function() for _, child in ipairs(MaterialService:GetChildren()) do child:Destroy() end WindUI:Notify({ Title = "MaterialService Cleared", Content = "All materials have been removed from MaterialService", Duration = 3 }) end }) Tabs.Utility:Space() LowQualityButton = Tabs.Utility:Button({ Title = "Low Quality", Desc = "Disable textures, effects, and optimize graphics", Callback = function() local ToDisable = { Textures = true, VisualEffects = true, Parts = true, Particles = true, Sky = true } local ToEnable = { FullBright = false } local Stuff = {} for _, v in next, game:GetDescendants() do if ToDisable.Parts then if v:IsA("Part") or v:IsA("UnionOperation") or v:IsA("BasePart") then v.Material = Enum.Material.SmoothPlastic table.insert(Stuff, 1, v) end end if ToDisable.Particles then if v:IsA("ParticleEmitter") or v:IsA("Smoke") or v:IsA("Explosion") or v:IsA("Sparkles") or v:IsA("Fire") then v.Enabled = false table.insert(Stuff, 1, v) end end if ToDisable.VisualEffects then if v:IsA("BloomEffect") or v:IsA("BlurEffect") or v:IsA("DepthOfFieldEffect") or v:IsA("SunRaysEffect") then v.Enabled = false table.insert(Stuff, 1, v) end end if ToDisable.Textures then if v:IsA("Decal") or v:IsA("Texture") then v.Texture = "" table.insert(Stuff, 1, v) end end if ToDisable.Sky then if v:IsA("Sky") then v.Parent = nil table.insert(Stuff, 1, v) end end end if ToEnable.FullBright then Lighting.FogColor = Color3.fromRGB(255, 255, 255) Lighting.FogEnd = math.huge Lighting.FogStart = math.huge Lighting.Ambient = Color3.fromRGB(255, 255, 255) Lighting.Brightness = 5 Lighting.ColorShift_Bottom = Color3.fromRGB(255, 255, 255) Lighting.ColorShift_Top = Color3.fromRGB(255, 255, 255) Lighting.OutdoorAmbient = Color3.fromRGB(255, 255, 255) Lighting.Outlines = true end end }) if not (LocalPlayer:GetAttribute("VIPCommandsAccess") == true) then else Tabs.Utility:Section({ Title = "VIP COMMAND", TextSize = 20 }) Tabs.Utility:Divider() Tabs.Utility:Button({ Title = "VIP CMD Macro", Icon = "rbxassetid://107814281854748", Callback = function() EvadeMacroVIPCmdGUI() end }) function isValidMap(mapName) local mapsFolder = ReplicatedStorage:FindFirstChild("Info") if mapsFolder then mapsFolder = mapsFolder:FindFirstChild("Maps") if mapsFolder then for _, map in ipairs(mapsFolder:GetChildren()) do if map.Name == mapName then return true end end end end return false end Tabs.Utility:Space() mapSettingsInput = Tabs.Utility:Input({ Title = "Set Map Settings", Flag = "MapSettingsInput", Placeholder = "Enter map name (e.g., BrickMaze)", Value = "BrickMaze", }) mapSettingsInput.Callback = function(value) ConfigState.SelectedMapSetting = value end Tabs.Utility:Button({ Title = "Add Map", Desc = "Add the specified map to rotation", Icon = "plus", Callback = function() local mapName = ConfigState.SelectedMapSetting or "BrickMaze" if mapName and mapName ~= "" then if isValidMap(mapName) then ReplicatedStorage.Remotes.Admin.VIPCommand:FireServer("AddMap", mapName) WindUI:Notify({ Title = "Custom Server", Content = "Added map: " .. mapName, Duration = 3 }) else WindUI:Notify({ Title = "Custom Server", Content = "Invalid map name: " .. mapName, Duration = 3 }) end end end }) Tabs.Utility:Button({ Title = "Remove Map", Desc = "Remove the specified map from rotation", Icon = "minus", Callback = function() local mapName = ConfigState.SelectedMapSetting or "BrickMaze" if mapName and mapName ~= "" then if isValidMap(mapName) then pcall(function() ReplicatedStorage.Remotes.Admin.VIPCommand:FireServer("RemoveMap", mapName) WindUI:Notify({ Title = "Custom Server", Content = "Removed map: " .. mapName, Duration = 3 }) end) else WindUI:Notify({ Title = "Custom Server", Content = "Invalid map name: " .. mapName, Duration = 3 }) end end end }) Tabs.Utility:Space() Tabs.Utility:Button({ Title = "Unlock VIP Commands", Desc = "Restore access to VIP commands if accidentally locked", Icon = "unlock", Callback = function() pcall(function() VIPMenu = PlayerGui.Shared.Popups.VIPMenu.Create.Frame VIPMenu.Commands.Visible = true VIPMenu.Locked.Visible = false end) end }) end Tabs.Utility:Space() Tabs.Teleport:Section({ Title = "Teleports", TextSize = 20 }) Tabs.Teleport:Divider() Tabs.Teleport:Space() Tabs.Teleport:Button({ Title = "Teleport to Spawn", Desc = "Teleport to a random spawn location", Icon = "home", Callback = function() teleportToRandomSpawn(Vector3.new(0, 3, 0)) end }) Tabs.Teleport:Space() Tabs.Teleport:Button({ Title = "Teleport to Random Player", Desc = "Teleport to a random online Players", Icon = "users", Callback = function() teleportToRandomPlayer(Vector3.new(0, 3, 0)) end }) Tabs.Teleport:Space() Tabs.Teleport:Button({ Title = "Teleport to Downed Player", Desc = "Teleport to a random Downed Players", Icon = "heart", Callback = function() teleportToRandomDowned(Vector3.new(0, 3, 0)) end }) Tabs.Teleport:Space() PlayerDropdown = Tabs.Teleport:Dropdown({ Title = "Select Player or NPC", Flag = "PlayerDropdown", Values = { { Title = "No players found", Desc = "", Icon = "user" } }, Value = "No players found", Callback = function(selectedOption) end }) function getNPCIcon(model) local hrp = model:FindFirstChild("HumanoidRootPart") if not hrp then return nil end local billboard = hrp:FindFirstChild("BillboardGui") if not billboard then return nil end local icon = billboard:FindFirstChild("Icon") if not icon then return nil end if icon:IsA("ImageLabel") or icon:IsA("ImageButton") then return icon.Image end return nil end function TeleportNotify(text) WindUI:Notify({ Title = "Teleport", Content = text, Duration = 3 }) end function TeleportGetRoot(model) if not model or not model.Parent then return nil end return model:FindFirstChild("HumanoidRootPart") or model.PrimaryPart or model:FindFirstChildWhichIsA("BasePart") end function TeleportThumb(userId) local cached = ConfigState.TeleportThumbs[userId] if cached then return cached end local ok, thumb = pcall(Players.GetUserThumbnailAsync, Players, userId, Enum.ThumbnailType.HeadShot, Enum.ThumbnailSize.Size150x150) if ok and thumb then ConfigState.TeleportThumbs[userId] = thumb return thumb end return "user" end function findWorkspaceCharacterForPlayer(plr) local ok, character = pcall(CharacterService.GetCharacterFromPlayer, CharacterService, plr) if ok and character and character.Model and character.Model.Parent then return character.Model end local playersFolder = workspace:FindFirstChild("Players") if not playersFolder then return nil end local byName = playersFolder:FindFirstChild(plr.Name) if byName and byName:IsA("Model") then return byName end for _, model in ipairs(playersFolder:GetChildren()) do if model:IsA("Model") then local userId = model:GetAttribute("UserId") or model:GetAttribute("PlayerUserId") if model:GetAttribute("Name") == plr.Name or model.Name == tostring(plr.UserId) or (typeof(userId) == "number" and userId == plr.UserId) then return model end end end if plr.Character and plr.Character.Parent == playersFolder then return plr.Character end return nil end function TeleportAddEntry(values, title, desc, icon, entry) local lookup = ConfigState.TeleportLookup local unique = title local count = 1 while lookup[unique] do count = count + 1 unique = title .. " #" .. count end lookup[unique] = entry table.insert(values, { Title = unique, Desc = desc, Icon = icon }) end function updatePlayerList() table.clear(ConfigState.TeleportLookup) local values = {} local listed = {} local mine = LocalPlayer.Character local myTag = mine and mine:GetAttribute("Tag") for _, plr in ipairs(Players:GetPlayers()) do if plr ~= LocalPlayer then local model = findWorkspaceCharacterForPlayer(plr) local desc = "No character (dead or not spawned) | @" .. plr.Name if model then listed[model] = true desc = "Team: " .. tostring(model:GetAttribute("Team") or "Unknown") .. " | @" .. plr.Name end TeleportAddEntry(values, plr.DisplayName, desc, TeleportThumb(plr.UserId), { kind = "player", player = plr }) end end local folder = workspace:FindFirstChild("Players") if folder then for _, model in ipairs(folder:GetChildren()) do local tag = model:GetAttribute("Tag") local isMine = model == mine or (myTag ~= nil and tag == myTag) if model:IsA("Model") and not listed[model] and not isMine and TeleportGetRoot(model) then local team = model:GetAttribute("Team") or "Unknown" local userId = model:GetAttribute("UserId") local icon = "user" local npcIcon = getNPCIcon(model) if npcIcon and npcIcon ~= "" then icon = npcIcon end if tostring(team) ~= "NPC" and typeof(userId) == "number" then icon = TeleportThumb(userId) end TeleportAddEntry(values, tostring(model:GetAttribute("Name") or model.Name), "Team: " .. tostring(team) .. " | " .. model.Name, icon, { kind = "character", tag = tag, model = model }) end end end if # values == 0 then values = { { Title = "No players found", Desc = "", Icon = "user" } } end PlayerDropdown:Refresh(values, true) end function TeleportResolveEntry(entry) if entry.kind == "player" then local plr = entry.player if not plr or plr.Parent ~= Players then return nil, "That player left the game" end local model = findWorkspaceCharacterForPlayer(plr) if not model then return nil, plr.DisplayName .. " has no character right now (dead or not spawned)" end return model end if entry.tag then local ok, character = pcall(CharacterService.GetCharacterFromTag, CharacterService, entry.tag) if ok and character and character.Model and character.Model.Parent then return character.Model end end local model = entry.model if model and model.Parent and model:GetAttribute("Tag") == entry.tag then return model end return nil, "That target does not exist anymore, hit Refresh" end function TeleportIsDead(model) local humanoid = model:FindFirstChildOfClass("Humanoid") if not humanoid or humanoid.Health > 0 then return false end local ok, character = pcall(CharacterService.GetCharacterFromTag, CharacterService, model:GetAttribute("Tag")) local registry = ok and character and character.DataRegistry return registry ~= nil and registry ~= false and not registry:Get("Downed") end function TeleportToSelected() local selected = PlayerDropdown.Value local title = type(selected) == "table" and selected.Title or selected local entry = title and ConfigState.TeleportLookup[title] if not entry then TeleportNotify("Pick someone first (hit Refresh if the list is old)") return end local model, reason = TeleportResolveEntry(entry) if not model then TeleportNotify(reason) return end if TeleportIsDead(model) then TeleportNotify("Target is dead, nothing to teleport to") return end local root = TeleportGetRoot(model) if not root then TeleportNotify("Target has no body to teleport to") return end teleportToCFrame(root.CFrame + Vector3.new(0, 3, 0)) end Tabs.Teleport:Button({ Title = "Refresh Player List", Desc = "Refresh Player and NPC list", Icon = "refresh-cw", Callback = updatePlayerList }) Tabs.Teleport:Space() Tabs.Teleport:Button({ Title = "Teleport to Selected", Desc = "Teleport to selected player or NPC", Icon = "user", Callback = TeleportToSelected }) Tabs.Teleport:Space() Tabs.Teleport:Button({ Title = "Teleport to Ticket", Desc = "Teleport to a random ticket", Icon = "ticket", Callback = function() teleportToRandomTicket(Vector3.new(0, 3, 0)) end }) Tabs.Teleport:Space() Tabs.Teleport:Button({ Title = "Teleport to NPC", Desc = "Teleport to a random NPC", Icon = "ghost", Callback = function() teleportToRandomNPC(Vector3.new(0, 10, 0)) end }) Tabs.Teleport:Space() Tabs.Teleport:Button({ Title = "Teleport to SecurityPart", Icon = "shield", Callback = function() teleportToSecurityPart(Vector3.new(0, 3, 0)) end }) local objectiveDropdown local refreshButton function updateObjectiveDropdown() if tick() - ConfigState.lastUpdateTime < ConfigState.updateCooldown then return end ConfigState.lastUpdateTime = tick() ConfigState.objectives = getObjectives() if not objectiveDropdown then return end if # ConfigState.objectives > 0 then local objectiveNames = {} for _, obj in ipairs(ConfigState.objectives) do if obj and obj.Name then table.insert(objectiveNames, obj.Name) end end if # objectiveNames > 0 then objectiveDropdown:Refresh(objectiveNames, objectiveNames[1]) else objectiveDropdown:Refresh({ "No valid objectives" }, "No valid objectives") end else objectiveDropdown:Refresh({ "No objectives found" }, "No objectives found") end end Tabs.Teleport:Space() objectiveDropdown = Tabs.Teleport:Dropdown({ Title = "Select Objective", Flag = "objectiveDropdown", Values = {""}, Value = "", Enabled = true, Callback = function(value) end }) teleportButton = Tabs.Teleport:Button({ Title = "Teleport to Objective", Icon = "navigation", Enabled = false, Callback = function() local selectedName = objectiveDropdown.Value if selectedName == "No objectives found" or selectedName == "" then return end teleportToObjective(selectedName, Vector3.new(0, 5, 0)) end }) refreshButton = Tabs.Teleport:Button({ Title = "Refresh Objectives", Icon = "refresh-cw", Callback = function() updateObjectiveDropdown() end }) ConfigState.lastRoundStatusObj = ServerStateRegistryService.Registry.RoundStatus ConfigState.loopupdateObjectiveDropdown = RunService.Heartbeat:Connect(function() if not objectiveDropdown or not Tabs.Teleport then if ConfigState.loopupdateObjectiveDropdown then ConfigState.loopupdateObjectiveDropdown:Disconnect() ConfigState.loopupdateObjectiveDropdown = nil end print("UI Not found: Successfully stopped heartbeat loop.") return end local success, err = pcall(function() local currentRoundStatus = ServerStateRegistryService.Registry.RoundStatus if currentRoundStatus ~= ConfigState.lastRoundStatusObj then ConfigState.lastRoundStatusObj = currentRoundStatus task.wait(1) updateObjectiveDropdown() end end) if not success then task.spawn(function() error("⚠ Error 404: Can not Auto Update Objective Dropdown Because You closed wind ui. Auto disconnecting...") end) if ConfigState.loopupdateObjectiveDropdown then ConfigState.loopupdateObjectiveDropdown:Disconnect() ConfigState.loopupdateObjectiveDropdown = nil print("Successfully Stopped loop") end end end) Tabs.Teleport:Section({ Title = "Teleport to Coordinates", TextSize = 20 }) CoordTeleInput = Tabs.Teleport:Input({ Title = "Target Coordinates", Flag = "CoordTeleInput", Placeholder = "X Y Z", Value = "", }) CoordTeleInput.Callback = function(value) ConfigState.teleInputValue = value end Tabs.Teleport:Button({ Title = "Teleport NOW!!! >:(", Icon = "target", Callback = function() local function parseCoordinate(token, current) if not token or token == "" then return nil end token = token:gsub("%s+", "") local num = tonumber(token) if num then return num end if token:sub(1, 1) == "~" then local rest = token:sub(2) if rest == "" then return current end local op = rest:sub(1, 1) local valuePart = rest:sub(2) if op == "+" or op == "-" or op == "*" then local val = tonumber(valuePart) if val then if op == "+" then return current + val elseif op == "-" then return current - val elseif op == "*" then return current * val end end else local val = tonumber(rest) if val then return current + val end end end return nil end local tokens = {} for token in string.gmatch(ConfigState.teleInputValue, "%S+") do table.insert(tokens, token) end if # tokens < 3 then WindUI:Notify({ Title = "Invalid Input", Content = "Please enter three values for X, Y, Z separated by spaces", Duration = 3 }) return end local character = LocalPlayer.Character if not character then WindUI:Notify({ Title = "Error", Content = "Character not found", Duration = 3 }) return end local root = character:FindFirstChild("HumanoidRootPart") if not root then WindUI:Notify({ Title = "Error", Content = "HumanoidRootPart not found", Duration = 3 }) return end local currentPos = root.Position local x = parseCoordinate(tokens[1], currentPos.X) local y = parseCoordinate(tokens[2], currentPos.Y) local z = parseCoordinate(tokens[3], currentPos.Z) if x == nil or y == nil or z == nil then WindUI:Notify({ Title = "Invalid Expression", Content = "One or more coordinates could not be parsed", Duration = 3 }) return end root.CFrame = CFrame.new(x, y, z) end }) if shopPanel and type(shopPanel._startHold) == "function" then if setreadonly then setreadonly(shopPanel, false) end local originalStartHold = shopPanel._startHold shopPanel._startHold = function(self) if ConfigState.purchaseHoldDelay == ConfigState.defaultHoldDelay then return originalStartHold(self) end if self._holdTween ~= nil or self._isBusy or not self._holdsToBuy then return end if ConfigState.purchaseHoldDelay <= 0 then self._holdInput = nil self:_purchase() return end local hold = self.Frame.Buy.Hold hold.Size = UDim2.fromScale(0, 1) hold.Visible = true local tween = TweenService:Create(hold, TweenInfo.new(ConfigState.purchaseHoldDelay, Enum.EasingStyle.Linear), { Size = UDim2.fromScale(1, 1) }) self._holdTween = tween tween.Completed:Once(function(state) if self._holdTween == tween and state == Enum.PlaybackState.Completed then self._holdTween = nil self._holdInput = nil self:_purchase() hold.Visible = false end end) tween:Play() end end PurchaseHoldDelay = Tabs.Shop:Input({ Title = "Purchase Hold Delay", Desc = "Seconds to hold the purchase button. 0 buys instantly, 0.35 is the game default", Flag = "PurchaseHoldDelay", Placeholder = "0.35", Value = "0.35", }) PurchaseHoldDelay.Callback = function(value) local n = tonumber(value) if n and n >= 0 then ConfigState.purchaseHoldDelay = n end end LoadAutoShop = Tabs.Shop:Button({ Title = "Load Shop Automation", Callback = function() pcall(function() LoadAutoShop:Destroy() local loops = {} local function startLoop(key, action) if loops[key] then loops[key]() loops[key] = nil end local conn = HeartbeatLoop(0.4, function() pcall(action) end) loops[key] = function() conn:Disconnect() end end local function stopLoop(key) if loops[key] then loops[key]() loops[key] = nil end end local function configOf(key) local id = tonumber(key) if not id then return nil end return ItemRegistry.GetConfig(id) end local function nameOf(key) local config = configOf(key) if config and config.AppearanceInfo and config.AppearanceInfo.Name then return config.AppearanceInfo.Name end local entry = ItemRegistry.TryGetById(tonumber(key)) if entry and entry.Module then return entry.Module.Name end return "Item " .. key end local function isMultiple(key) local config = configOf(key) return config ~= nil and config.PurchaseInfo ~= nil and config.PurchaseInfo.OwnershipType == "Multiple" end local function playerLevel() local ok, progress = pcall(ConfigState.PlayerData.Progression) if ok and type(progress) == "table" then return tonumber(progress.Level) or 0 end return 0 end local function levelRequirementOf(key) local config = configOf(key) local purchase = config and config.PurchaseInfo return tonumber(purchase and purchase.LevelRequirement) or 0 end local function meetsLevel(key) return playerLevel() >= levelRequirementOf(key) end local function overviewOf(key) local config = configOf(key) local ui = config and config.UIInfo return tostring(ui and ui.Overview or "Other") end local function ownedCountOf(key) local id = tonumber(key) local function try(fn) local ok, value = pcall(fn) if ok and type(value) == "number" then return value end return nil end local record = ConfigState.PlayerData.StockRecord(key) if type(record) == "table" then for _, field in ipairs({"OwnedAmount", "OwnedCount", "Owned", "Count", "Amount"}) do if type(record[field]) == "number" then return record[field] end end end if id then local inventory = CosmeticModules.InventoryService for _, method in ipairs({"Count", "GetCount", "Amount", "GetAmount", "Quantity", "GetQuantity"}) do local fn = inventory and inventory[method] if type(fn) == "function" then local value = try(function() return fn(id) end) if value then return value end end end end return ConfigState.PlayerData.OwnsStock(key) and 1 or 0 end local eventMeta = {} local function buyTierItem(key) local meta = eventMeta[key] local id = tonumber(key) if not meta or not id or meta.State == "Locked" or meta.Owned or ConfigState.PlayerData.Owns(id) then return false end if not meta.Price or ConfigState.PlayerData.Tickets() < meta.Price then return false end return ConfigState.PlayerData.Purchase(id) end local function buyUnit(key, wantedUnits) if not meetsLevel(key) then return false end local record = ConfigState.PlayerData.StockRecord(key) if not record then return buyTierItem(key) end if record.Currency == "Robux" then return false end if ConfigState.PlayerData.OwnsStock(key) and not isMultiple(key) then return false end local price = ConfigState.PlayerData.PriceOf(key) if not price then return false end local increment = record.Increment or 1 local units = wantedUnits or record.MinAmount or 1 if ConfigState.PlayerData.Balance(record.Currency) < price * units then return false end return ConfigState.PlayerData.Buy(key, increment * units) end local function slotItemKeys(shopName) local keys, seen = {}, {} local shop = ConfigState.PlayerData.Shop(shopName) if not shop or type(shop.Slots) ~= "function" then return keys end local slots = shop.Slots() if type(slots) ~= "table" then return keys end local slotNumbers = {} for slotNum in pairs(slots) do table.insert(slotNumbers, slotNum) end table.sort(slotNumbers) for _, slotNum in ipairs(slotNumbers) do local slot = slots[slotNum] local itemId = slot and slot.itemId if itemId ~= nil then local key = tostring(itemId) if not seen[key] then seen[key] = true table.insert(keys, key) end end end return keys end local function tokenItemKeys() local keys = {} local ids = ItemRegistry.Query():Include(function(entry) local config = ItemRegistry.GetConfig(entry.Id) return config ~= nil and config.PurchaseInfo ~= nil and config.PurchaseInfo.Currency == "Tokens" and config.PurchaseInfo.AppearsIn == "Shop" end):Ids() for _, id in ipairs(ids) do local key = tostring(id) if ConfigState.PlayerData.StockRecord(key) then table.insert(keys, key) end end return keys end local function eventItemKeys() local keys, seen = {}, {} table.clear(eventMeta) local function add(key) key = tostring(key) if not seen[key] then seen[key] = true table.insert(keys, key) end end for _, key in ipairs(slotItemKeys("Event")) do add(key) end for _, tier in ipairs(ConfigState.PlayerData.EventTiers()) do for _, item in ipairs(tier.Items or {}) do if item.ItemId ~= nil then local key = tostring(item.ItemId) eventMeta[key] = { Tier = tier.Index, Price = item.Price, Owned = item.Owned, State = tier.State } add(key) end end end return keys end local function buildOptions(keys, liveSet) if # keys == 0 then return { { Title = "No items available", Desc = "Check back later or refresh", Value = "none" } } end local options = {} for _, key in ipairs(keys) do local record = ConfigState.PlayerData.StockRecord(key) or {} local meta = eventMeta[key] local purchase = (configOf(key) or {}).PurchaseInfo or {} local desc if next(record) == nil and meta then local owned = meta.Owned or ConfigState.PlayerData.Owns(tonumber(key)) desc = string.format("Tier %s | Price: %s Tickets | Status: %s | %s", tostring(meta.Tier), tostring(meta.Price or "?"), owned and "OWNED" or "NOT OWNED", tostring(meta.State or "?")) else local price = ConfigState.PlayerData.PriceOf(key) or purchase.Price or "?" local currency = record.Currency or purchase.Currency or "" local status = ConfigState.PlayerData.OwnsStock(key) and "OWNED" or "NOT OWNED" if isMultiple(key) then status = "Owned x" .. tostring(ownedCountOf(key)) end local requirement = levelRequirementOf(key) if requirement > 0 then status = status .. (meetsLevel(key) and (" | Lv " .. requirement .. " OK") or (" | LOCKED: needs Lv " .. requirement)) end if next(record) == nil then status = status .. " | Not on sale right now" elseif liveSet and not liveSet[key] then status = status .. " | Not in current lineup" end desc = string.format("Price: %s %s | Status: %s", tostring(price), tostring(currency), status) end table.insert(options, { Title = nameOf(key), Desc = desc, Value = key }) end return options end local refreshAll local function makeSubSection(parent, title) local ok, sub = pcall(function() return parent:Section({ Title = title }) end) if ok and sub then return sub end return parent end local function makeShopSection(title, side, getKeys, getLiveKeys, parent, opts) local section if parent then section = makeSubSection(parent, title) else section = Tabs.Shop:Section({ Title = title, Side = side }) end local selected = {} local dropdown local lastSignature = nil local optionsFn = opts and opts.options or buildOptions local buyFn = opts and opts.buy or buyUnit local function liveSetOf() if not getLiveKeys then return nil end local set = {} for _, key in ipairs(getLiveKeys()) do set[key] = true end return set end local function signatureOf(options) local parts = {} for _, option in ipairs(options) do table.insert(parts, option.Value .. "|" .. option.Desc) end return table.concat(parts, "\n") end local function refreshShopDropdownOptions() local options = optionsFn(getKeys(), liveSetOf()) local signature = signatureOf(options) if signature == lastSignature then return end lastSignature = signature local valueSet = {} for _, option in ipairs(options) do valueSet[option.Value] = true end local valid = {} for _, value in ipairs(selected) do if valueSet[value] then table.insert(valid, value) end end selected = valid if dropdown then dropdown.Refresh(dropdown, options, valid) end end local api = { refresh = function() refreshShopDropdownOptions() end, getSelected = function() return selected end } if opts and opts.setup then opts.setup(section, api) end local initialOptions = optionsFn(getKeys(), liveSetOf()) lastSignature = signatureOf(initialOptions) dropdown = section:Dropdown({ Title = "Select " .. title .. " Items", SearchBarEnabled = true, Values = initialOptions, Multi = true, AllowNone = true, Callback = function(choices) selected = {} for _, choice in ipairs(choices or {}) do if choice.Value and choice.Value ~= "none" then table.insert(selected, choice.Value) end end end }) section:Button({ Title = "Refresh " .. title, Callback = function() if refreshAll then refreshAll() else refreshShopDropdownOptions() end end }) local AutoBuyAllItems = section:Toggle({ Title = "Auto Buy All " .. title .. " Items", Value = false, }) AutoBuyAllItems.Callback = function(state) if state then startLoop(title .. "_all", function() for _, key in ipairs(getKeys()) do buyFn(key) end end) else stopLoop(title .. "_all") if opts and opts.onAutoStop then opts.onAutoStop() end end end local AutoBuySelectedItems = section:Toggle({ Title = "Auto Buy Selected " .. title .. " Items", Value = false, }) AutoBuySelectedItems.Callback = function(state) if state then startLoop(title .. "_selected", function() getKeys() for _, key in ipairs(selected) do buyFn(key) end end) else stopLoop(title .. "_selected") if opts and opts.onAutoStop then opts.onAutoStop() end end end return { refresh = refreshShopDropdownOptions } end local daily = makeShopSection("Daily Shop", "Left", function() return slotItemKeys("Daily") end) task.wait() local function notify(title, content) pcall(function() WindUI:Notify({ Title = title, Content = content, Duration = 3 }) end) end local function makeMultiShop(parent) local MIN_AMOUNT, MAX_AMOUNT, MAX_QUEUE, QUEUE_DELAY = 1, 100, 20, 0.5 local amount = MIN_AMOUNT local queueEnabled = true local queue, pending, queueConn = {}, {}, nil local function multiKeys() local keys = {} for _, key in ipairs(tokenItemKeys()) do if isMultiple(key) then table.insert(keys, key) end end return keys end local function clampAmount(value) local n = tonumber(value) if not n or n ~= n then return nil end return math.clamp(math.floor(n), MIN_AMOUNT, MAX_AMOUNT) end local function multiOptions(keys) if # keys == 0 then return { { Title = "No items available", Desc = "Check back later or refresh", Value = "none" } } end local options = {} for _, key in ipairs(keys) do local record = ConfigState.PlayerData.StockRecord(key) or {} local purchase = (configOf(key) or {}).PurchaseInfo or {} local unit = ConfigState.PlayerData.PriceOf(key) or purchase.Price local currency = record.Currency or purchase.Currency or "" local parts = {} if unit then table.insert(parts, string.format("Price: %s x %d = %s %s", tostring(unit), amount, tostring(unit * amount), currency)) else table.insert(parts, "Not on sale right now") end table.insert(parts, "Owned: " .. tostring(ownedCountOf(key))) local requirement = levelRequirementOf(key) if requirement > 0 then table.insert(parts, meetsLevel(key) and ("Lv " .. requirement .. " OK") or ("LOCKED: needs Lv " .. requirement)) end table.insert(options, { Title = nameOf(key), Desc = table.concat(parts, " | "), Value = key }) end return options end local sectionApi local function stopQueue() if queueConn then queueConn:Disconnect() queueConn = nil end end local function clearAutoJobs() for index = # queue, 1, - 1 do local job = queue[index] if not job.manual then pending[job.key] = nil table.remove(queue, index) end end if # queue == 0 then stopQueue() end end local function processQueue() if queueConn then return end queueConn = HeartbeatLoop(QUEUE_DELAY, function() local job = table.remove(queue, 1) if not job then stopQueue() return end pcall(buyUnit, job.key, job.amount) pending[job.key] = nil if sectionApi then sectionApi.refresh() end if # queue == 0 then stopQueue() end end) end local function multiBuy(key, manual) if not meetsLevel(key) then return false end if not queueEnabled then return buyUnit(key, amount) end if pending[key] or # queue >= MAX_QUEUE then return false end pending[key] = true table.insert(queue, { key = key, amount = amount, manual = manual }) processQueue() return true end sectionApi = makeShopSection("Multiple Item Shop", "Right", multiKeys, nil, parent, { options = function(keys) return multiOptions(keys) end, buy = multiBuy, onAutoStop = clearAutoJobs, setup = function(section, api) local amountInput = section:Input({ Title = "Buy Amount (" .. MIN_AMOUNT .. "-" .. MAX_AMOUNT .. ")", Desc = "Invalid values are reset automatically", Flag = "MultiShopAmount", Placeholder = tostring(MIN_AMOUNT), Value = tostring(MIN_AMOUNT), NumbersOnly = true, }) amountInput.Callback = function(value) local n = clampAmount(value) if not n then n = amount end amount = n if tostring(value) ~= tostring(n) then pcall(function() amountInput:Set(tostring(n)) end) end api.refresh() end local queueCheckbox = section:Toggle({ Title = "Buy Queue", Desc = "Purchases run one at a time to prevent spam", Flag = "MultiShopQueue", Type = "Checkbox", Value = true, }) queueCheckbox.Callback = function(state) queueEnabled = state end section:Button({ Title = "Buy Selected Amount", Callback = function() local chosen = api.getSelected() if # chosen == 0 then notify("No item", "Select a Multiple item first") return end for _, key in ipairs(chosen) do if not meetsLevel(key) then notify("Locked", nameOf(key) .. " requires level " .. levelRequirementOf(key)) elseif not multiBuy(key, true) then notify("Not bought", nameOf(key) .. " is already queued, or balance is too low") end end api.refresh() end }) end }) return sectionApi end local tokenParent = Tabs.Shop:Section({ Title = "Token Shop", Side = "Right" }) local multiShop = makeMultiShop(tokenParent) local tokenSections = {} local function ensureTokenOverviewSections() for _, key in ipairs(tokenItemKeys()) do local overview = overviewOf(key) if not tokenSections[overview] then tokenSections[overview] = makeShopSection("Token " .. overview, "Right", function() local keys = {} for _, k in ipairs(tokenItemKeys()) do if overviewOf(k) == overview then table.insert(keys, k) end end return keys end, nil, tokenParent) end end end ensureTokenOverviewSections() local tokens = { refresh = function() ensureTokenOverviewSections() for _, sectionApi in pairs(tokenSections) do sectionApi.refresh() end multiShop.refresh() end } task.wait() local event = nil local function ensureEventSection() if event ~= nil then return true end if not task.spawn(ConfigState.PlayerData.EventActive) then return false end event = makeShopSection("Event Shop", "Left", eventItemKeys, function() return slotItemKeys("Event") end) return true end ensureEventSection() task.wait() refreshAll = function() daily.refresh(); tokens.refresh() if ensureEventSection() then event.refresh() end end end) end }) Tabs.Shop:Section({ Title = "Auto Exchange", TextSize = 20 }) Tabs.Shop:Divider() function AutoExchangePrettyNumber(n) if n ~= math.floor(n) then return tostring(n) end local formatted = tostring(math.floor(n)):reverse():gsub("(%d%d%d)", "%1,"):reverse() return (formatted:gsub("^,", "")) end function AutoExchangeCurrencyLabel(to) return ConfigState.currencyLabels[to] or tostring(to) end AutoExchangeBuildOptions = function() ConfigState.exchangeOptions = {} ConfigState.exchangeLabels = {} local top = math.max(ConfigState.PlayerData.Tickets(), 100) for _, entry in ipairs(ConfigState.PlayerData.EventExchanges) do if type(entry) ~= "table" or entry.To == nil or type(entry.Rate) ~= "number" then continue end local name = AutoExchangeCurrencyLabel(entry.To) for power = 0, math.floor(math.log10(top)) do local amount = 10 ^ power local label = string.format("%s %s [%s Ticket%s]", AutoExchangePrettyNumber(entry.Rate * amount), name, AutoExchangePrettyNumber(amount), amount == 1 and "" or "s") ConfigState.exchangeOptions[label] = { to = entry.To, amount = amount } table.insert(ConfigState.exchangeLabels, label) end local allLabel = string.format("%s %s per Ticket [All Tickets]", AutoExchangePrettyNumber(entry.Rate), name) ConfigState.exchangeOptions[allLabel] = { to = entry.To, all = true } table.insert(ConfigState.exchangeLabels, allLabel) end if # ConfigState.exchangeLabels == 0 then ConfigState.exchangeLabels = {"No exchange available"} end if not ConfigState.exchangeOptions[ConfigState.selectedExchange] then ConfigState.selectedExchange = ConfigState.exchangeLabels[1] end end function AutoExchangeRefreshDropdown() task.spawn(AutoExchangeBuildOptions) if ConfigState.exchangeDropdown then ConfigState.exchangeDropdown:Refresh(ConfigState.exchangeLabels, ConfigState.selectedExchange) end end function AutoExchangeNotify(content) WindUI:Notify({ Title = "Auto Exchange", Content = content, Duration = 5 }) end function AutoExchangeRunOnce() if ConfigState.exchangePending then return end local choice = ConfigState.exchangeOptions[ConfigState.selectedExchange] if not choice then return end local tickets = ConfigState.PlayerData.Tickets() local amount = choice.all and tickets or choice.amount if tickets <= 0 or tickets < amount then return end ConfigState.exchangePending = true ConfigState.PlayerData.Exchange(choice.to, amount) task.delay(1.5, function() ConfigState.exchangePending = false if ConfigState.PlayerData.Tickets() >= tickets then ConfigState.exchangeFailures = ConfigState.exchangeFailures + 1 if ConfigState.exchangeFailures >= 3 and ConfigState.autoExchangeToggle then ConfigState.exchangeFailures = 0 ConfigState.autoExchangeToggle:Set(false) AutoExchangeNotify("The server did not take the exchange (event phase: " .. tostring(ConfigState.PlayerData.EventPhase()) .. "). Stopped.") end else ConfigState.exchangeFailures = 0 end end) end function StopAutoExchange() if ConfigState.exchangeConn then ConfigState.exchangeConn:Disconnect() ConfigState.exchangeConn = nil end ConfigState.exchangePending = false ConfigState.exchangeFailures = 0 end function StartAutoExchange() StopAutoExchange() AutoExchangeRefreshDropdown() ConfigState.exchangeConn = HeartbeatLoop(ConfigState.exchangeDelay, AutoExchangeRunOnce) end task.spawn(AutoExchangeBuildOptions) ConfigState.exchangeDropdown = Tabs.Shop:Dropdown({ Title = "Exchange Option", Desc = "Read from the game: what each exchange gives for how many Tickets", Flag = "AutoExchangeOption", Values = ConfigState.exchangeLabels, Value = ConfigState.selectedExchange, Callback = function(value) if ConfigState.exchangeOptions[value] then ConfigState.selectedExchange = value end end }) Tabs.Shop:Button({ Title = "Refresh Exchange List", Icon = "refresh-cw", Callback = function() AutoExchangeRefreshDropdown() if ConfigState.exchangeOptions[ConfigState.selectedExchange] then AutoExchangeNotify("Loaded " .. # ConfigState.exchangeLabels .. " exchange options (event phase: " .. tostring(ConfigState.PlayerData.EventPhase()) .. ")") else AutoExchangeNotify("No exchange is available right now (event phase: " .. tostring(ConfigState.PlayerData.EventPhase()) .. ")") end end }) AutoExchangeDelay = Tabs.Shop:Input({ Title = "Exchange Delay", Desc = "Seconds between exchange attempts", Flag = "AutoExchangeDelay", Placeholder = "2", Value = "2", }) AutoExchangeDelay.Callback = function(value) local n = tonumber(value) if n and n >= 0.5 then ConfigState.exchangeDelay = n if ConfigState.exchangeConn then StartAutoExchange() end end end ConfigState.autoExchangeToggle = Tabs.Shop:Toggle({ Title = "Auto Exchange", Desc = "Exchanges your Tickets with the selected option whenever you have enough", Flag = "AutoExchangeToggle", Value = false, }) ConfigState.autoExchangeToggle.Callback = function(state) if state then StartAutoExchange() else StopAutoExchange() end end Tabs.Shop:Space() Tabs.Settings:Section({ Title = "Settings", TextSize = 40 }) NexriftAutoApplyToggle = Tabs.Settings:Toggle({ Title = "Auto Apply On Spawn", Desc = "Otomatis apply ulang SEMUA setting (toggle ON + slider/input/dropdown) tiap spawn (respawn / round baru / balik lobby), + backup tiap round selesai", Flag = "NexriftAutoApplyAfterRound", Value = true, }) NexriftAutoApplyToggle.Callback = function(state) NexriftAutoApplyEnabled = state end Tabs.Settings:Section({ Title = "Config Manager", TextSize = 20 }) Tabs.Settings:Divider() local ConfigManager = Window.ConfigManager function FileExists(path) if isfile then return isfile(path) end return false end function WriteFile(path, content) if writefile then writefile(path, content) return true end return false end function ReadFile(path) if readfile then return readfile(path) end return "" end function loadAutoLoadSettings() local autoLoadFile = "Nexrift/Evade/AutoLoad.json" if FileExists(autoLoadFile) then local content = ReadFile(autoLoadFile) if content ~= "" then local data = HttpService:JSONDecode(content) if data then ConfigState.AutoLoadConfig = data.configName or "default" ConfigState.AutoLoadEnabled = data.enabled or false return true end end end ConfigState.AutoLoadConfig = "default" ConfigState.AutoLoadEnabled = false return false end function saveAutoLoadSettings() local autoLoadFile = "Nexrift/Evade/AutoLoad.json" if makefolder then makefolder("Nexrift") makefolder("Nexrift/Evade") end local data = { enabled = ConfigState.AutoLoadEnabled, configName = ConfigState.AutoLoadConfig } local json = HttpService:JSONEncode(data) WriteFile(autoLoadFile, json) end loadAutoLoadSettings() ConfigNameInput = Tabs.Settings:Input({ Title = "Config Name", Flag = "ConfigNameInput", Desc = "Name for your config file", Icon = "file-cog", Placeholder = "default", Value = ConfigState.CurrentConfigName, }) ConfigNameInput.Callback = function(value) if value ~= "" then ConfigState.CurrentConfigName = value end end Tabs.Settings:Space() AutoLoadToggle = Tabs.Settings:Toggle({ Title = "Auto Load", Flag = "AutoLoadToggle", Desc = "Automatically load this config when script starts", Value = ConfigState.AutoLoadEnabled, }) AutoLoadToggle.Callback = function(state) ConfigState.AutoLoadEnabled = state if state then ConfigState.AutoLoadConfig = ConfigState.CurrentConfigName WindUI:Notify({ Title = "Auto-Load", Content = "Config '" .. ConfigState.CurrentConfigName .. "' will load automatically on startup", Duration = 3 }) end saveAutoLoadSettings() end AutoSaveToggle = Tabs.Settings:Toggle({ Title = "Auto Save", Flag = "AutoSaveToggle", Desc = "Automatically save changes to config every second", Value = ConfigState.AutoSaveEnabled, }) AutoSaveToggle.Callback = function(state) ConfigState.AutoSaveEnabled = state if ConfigState.AutoSaveConnection then ConfigState.AutoSaveConnection:Disconnect() ConfigState.AutoSaveConnection = nil end if state then WindUI:Notify({ Title = "Auto-Save", Content = "Config will save automatically every second", Duration = 2 }) ConfigState.AutoSaveConnection = game:GetService("RunService").Heartbeat:Connect(function() if ConfigState.AutoSaveEnabled and ConfigState.CurrentConfigName ~= "" then task.spawn(function() Window.CurrentConfig = ConfigManager:Config(ConfigState.CurrentConfigName) Window.CurrentConfig:Save() end) end task.wait(1) end) else WindUI:Notify({ Title = "Auto-Save", Content = "Auto-save disabled", Duration = 2 }) end end Tabs.Settings:Space() function refreshConfigList() local allConfigs = ConfigManager:AllConfigs() or {} if not table.find(allConfigs, "default") then local defaultConfig = ConfigManager:Config("default") if defaultConfig and defaultConfig.Save then defaultConfig:Save() end table.insert(allConfigs, 1, "default") end table.sort(allConfigs, function(a, b) return a:lower() < b:lower() end) local defaultValue = table.find(allConfigs, ConfigState.CurrentConfigName) and ConfigState.CurrentConfigName or "default" if ConfigState.ConfigListDropdown and ConfigState.ConfigListDropdown.Refresh then ConfigState.ConfigListDropdown:Refresh(allConfigs, defaultValue) end end ConfigState.ConfigListDropdown = Tabs.Settings:Dropdown({ Title = "Existing Configs", Flag = "ConfigListDropdown", Desc = "Select from saved configs", Values = {"default"}, Value = "default", Callback = function(value) ConfigState.CurrentConfigName = value ConfigNameInput:Set(value) if ConfigState.AutoLoadEnabled then ConfigState.AutoLoadConfig = value saveAutoLoadSettings() end local config = ConfigManager:GetConfig(value) if config then WindUI:Notify({ Title = "Config Selected", Content = "Config '" .. value .. "' selected", Duration = 2 }) end end }) Tabs.Settings:Space() SaveConfigButton = Tabs.Settings:Button({ Title = "Save Config", Desc = "Save current settings to config", Icon = "save", Callback = function() if ConfigState.CurrentConfigName == "" then WindUI:Notify({ Title = "Error", Content = "Please enter a config name", Duration = 3 }) return end Window.CurrentConfig = ConfigManager:Config(ConfigState.CurrentConfigName) local success = Window.CurrentConfig:Save() if success then WindUI:Notify({ Title = "Config Saved", Content = "Config '" .. ConfigState.CurrentConfigName .. "' saved successfully", Duration = 3 }) if ConfigState.AutoLoadEnabled then ConfigState.AutoLoadConfig = ConfigState.CurrentConfigName saveAutoLoadSettings() end task.wait(0.5) refreshConfigList() else WindUI:Notify({ Title = "Error", Content = "Failed to save config", Duration = 3 }) end end }) Tabs.Settings:Space() LoadConfigButton = Tabs.Settings:Button({ Title = "Load Config", Desc = "Load settings from selected config", Icon = "folder-open", Callback = function() if ConfigState.CurrentConfigName == "" then WindUI:Notify({ Title = "Error", Content = "Please enter a config name", Duration = 3 }) return end Window.CurrentConfig = ConfigManager:CreateConfig(ConfigState.CurrentConfigName) local success = Window.CurrentConfig:Load() if success then WindUI:Notify({ Title = "Config Loaded", Content = "Config '" .. ConfigState.CurrentConfigName .. "' loaded successfully", Duration = 3 }) if ConfigState.AutoLoadEnabled then ConfigState.AutoLoadConfig = ConfigState.CurrentConfigName saveAutoLoadSettings() end else WindUI:Notify({ Title = "Error", Content = "Config '" .. ConfigState.CurrentConfigName .. "' not found or empty", Duration = 3 }) end end }) Tabs.Settings:Space() DeleteConfigButton = Tabs.Settings:Button({ Title = "Delete Config", Desc = "Delete selected config", Icon = "trash-2", Color = Color3.fromHex("#ff4830"), Callback = function() if ConfigState.CurrentConfigName == "default" then WindUI:Notify({ Title = "Error", Content = "Cannot delete default config", Duration = 3 }) return end local success = ConfigManager:DeleteConfig(ConfigState.CurrentConfigName) if success then WindUI:Notify({ Title = "Config Deleted", Content = "Config '" .. ConfigState.CurrentConfigName .. "' deleted", Duration = 3 }) ConfigState.CurrentConfigName = "default" ConfigNameInput:Set("default") if ConfigState.AutoLoadEnabled then ConfigState.AutoLoadConfig = "default" saveAutoLoadSettings() end task.wait(0.5) refreshConfigList() else WindUI:Notify({ Title = "Error", Content = "Failed to delete config or config doesn't exist", Duration = 3 }) end end }) Tabs.Settings:Space() RefreshConfigButton = Tabs.Settings:Button({ Title = "Refresh Config List", Desc = "Update the list of available configs", Icon = "refresh-cw", Callback = function() refreshConfigList() WindUI:Notify({ Title = "Config List Refreshed", Content = "Config list updated", Duration = 2 }) end }) task.spawn(function() task.wait(0.5) refreshConfigList() ConfigNameInput:Set("default") if ConfigState.AutoLoadEnabled then ConfigState.CurrentConfigName = ConfigState.AutoLoadConfig ConfigNameInput:Set(ConfigState.CurrentConfigName) task.wait(1) Window.CurrentConfig = ConfigManager:Config(ConfigState.CurrentConfigName) if Window.CurrentConfig:Load() then WindUI:Notify({ Title = "Auto-Loaded", Content