alue = "", Callback = PlayTASRecording }) Tabs.Settings:Space() EmoteCrouchKeybind = Tabs.Settings:Keybind({ Title = "Trigger Random Emote", Desc = "Keybind to trigger random emote with crouch", Value = "J", Flag = "EmoteCrouchKeybind", Callback = function(v) if ConfigState.EmoteCrouchEnabled then triggerRandomEmote() end end }) SuperBounceKeybind = Tabs.Settings:Keybind({ Title = "Trigger Super Bounce", Desc = "Keybind to trigger super bounce", Value = "N", Flag = "SuperBounceKeybind", Callback = function(v) if ConfigState.SuperBounceEnabled then TriggerSuperBounce() end end }) Tabs.Settings:Section({ Title = "Player Tabs Keybinds" }) Tabs.Settings:Space() FlyTogglekeybind = Tabs.Settings:Keybind({ Title = "Fly Toggle", Desc = "Keybind to toggle Fly", Value = "", Flag = "FlyTogglekeybind", Callback = function(v) FlyToggle:Set(not FlyToggle.Value) end }) Tabs.Settings:Space() InfSlidekeybind = Tabs.Settings:Keybind({ Title = "InfSlide Toggle", Desc = "Keybind to toggle Slide", Value = "", Flag = "InfSlidekeybind", Callback = function(v) InfiniteSlideToggle:Set(not InfiniteSlideToggle.Value) end }) Tabs.Settings:Section({ Title = "Auto Tabs Keybinds" }) Tabs.Settings:Keybind({ Title = "Self Revive", Desc = "Keybind to revive yourself", Value = "", Flag = "SelfReviveKeybind", Callback = SelfReviveNow }) Tabs.Settings:Keybind({ Title = "Force Respawn", Desc = "Keybind to force respawn", Value = "", Flag = "ForceRespawnKeybind", Callback = ForceRespawnNow }) Tabs.Settings:Keybind({ Title = "Kill Aura Toggle", Desc = "Keybind to toggle Kill Aura", Value = "", Flag = "KillAuraKeybind", Callback = KillAuraToggleKey }) Tabs.Settings:Keybind({ Title = "Toggle Auto Spam Keybind", Value = "", Callback = function(value) SpamKeybindToggle:Set(not SpamKeybindToggle.Value) end }) Tabs.Settings:Space() BhopKeybind = Tabs.Settings:Keybind({ Title = "Bhop Toggle Key", Desc = "Keybind to toggle Bhop", Value = "B", Flag = "BhopKeybind", Callback = function(v) BhopToggle:Set(not BhopTog