Callback = function(state) if FPSCounter then FPSCounter.Enabled = state end end end Tabs.Settings:Section({ Title = "Sensitivity Controls", TextSize = 20 }) Tabs.Settings:Divider() function setupSensitivityHook() if ConfigState.cameraInputModule then return true end success = false cameraModule = PlayerModule:FindFirstChild("CameraModule") if cameraModule then cameraInput = cameraModule:FindFirstChild("CameraInput") if cameraInput then ConfigState.cameraInputModule = require(cameraInput) if ConfigState.cameraInputModule and ConfigState.cameraInputModule.getRotation then originalGetRotation = ConfigState.cameraInputModule.getRotation ConfigState.cameraInputModule.getRotation = function(disableRotation) rotation = originalGetRotation(disableRotation) if ConfigState.MouseSensitivityEnabled and UserInputService.MouseEnabled then return rotation * ConfigState.MouseSensitivityValue elseif ConfigState.TouchSensitivityEnabled and UserInputService.TouchEnabled then return rotation * ConfigState.TouchSensitivityValue end return rotation end success = true end end end return success end MouseSensitivityToggle = Tabs.Settings:Toggle({ Title = "Mouse Sensitivity", Flag = "MouseSensitivityToggle", Desc = "Adjust mouse sensitivity", Value = false, }) MouseSensitivityToggle.Callback = function(state) ConfigState.MouseSensitivityEnabled = state if state then if not setupSensitivityHook() then WindUI:Notify({ Title = "Mouse Sensitivity", Content = "Failed to hook system. Try rejoining.", Duration = 3 }) MouseSensitivityToggle:Set(false) ConfigState.MouseSensitivityEnabled = false end end end MouseSensitivitySlider = Tabs.Settings:Slider({ Title = "Mouse Sensitivity Value", Flag = "MouseSensitivitySlider", Desc = "Lower = slower, Higher = faster (Max: 20)", Value = { Min = 0.1, Max = 20, Default = 1.0 }, Step = 0.1, }) MouseSensitivitySlider.Callback = function(value) ConfigState.MouseSensitivityValue = value end Tabs.Settings:Space() TouchSensitivityToggle = Tabs.Settings:Toggle({ Title = "Touch Sensitivity", Flag = "TouchSensitivityToggle", Desc = "Adjust touch/mobile sensitivity", Value = false, }) TouchSensitivityToggle.Callback = function(state) ConfigState.TouchSensitivityEnabled = state if state then if not setupSensitivityHook() then WindUI:Notify({ Title = "Touch Sensitivity", Content = "Failed to hook system. Try rejoining.", Duration = 3 }) TouchSensitivityToggle:Set(false) ConfigState.TouchSensitivityEnabled = false end end end TouchSensitivitySlider = Tabs.Settings:Slider({ Title = "Touch Sensitivity Value", Flag = "TouchSensitivitySlider", Desc = "Lower = slower, Higher = faster (Max: 20)", Value = { Min = 0.1, Max = 20, Default = 1.0 }, Step = 0.1, }) TouchSensitivitySlider.Callback = function(value) ConfigState.TouchSensitivityValue = value end Tabs.Settings:Space() Tabs.Settings:Section({ Title = "Reset Controls", TextSize = 20 }) Tabs.Settings:Divider() Tabs.Settings:Button({ Title = "Reset Sensitivity Settings", Desc = "Reset both mouse and touch sensitivity to defaults", Icon = "refresh-cw", Color = Color3.fromHex("#FF3030"), Callback = function() ConfigState.MouseSensitivityEnabled = false ConfigState.MouseSensitivityValue = ConfigState.defaultSensitivity ConfigState.TouchSensitivityEnabled = false ConfigState.TouchSensitivityValue = ConfigState.defaultSensitivity ConfigState.cameraInputModule = nil ConfigState.mouseHookActive = false ConfigState.touchHookActive = false if MouseSensitivityToggle then MouseSensitivityToggle:Set(false) end if MouseSensitivitySlider then MouseSensitivitySlider:Set(1.0) end if TouchSensitivityToggle then TouchSensitivityToggle:Set(false) end if TouchSensitivitySlider then TouchSensitivitySlider:Set(1.0) end WindUI:Notify({ Title = "Sensitivity Reset", Content = "All sensitivity settings reset to default", Duration = 3 }) end }) socialsModule = loadstring(game:HttpGet(BaseURL .. "/Module/info.lua"))() socialsModule(Tabs) local unlockAllOriginalGet = InventoryStore and InventoryStore.Get function UnlockAllBuildBits() local bits = buffer.create(0) local ids = ItemRegistry.Query():Include(function() return true end):Ids() for _, id in ipairs(ids) do if type(id) == "number" and id >= 0 and id <= 1048575 then bits = OwnedBitset.Add(bits, id) end end return bits end function UnlockAllMergeBits(real) if real == ConfigState.unlockAllLastReal and ConfigState.unlockAllLastMerged then return ConfigState.unlockAllLastMerged end local realLength = real and buffer.len(real) or 0 local allLength = buffer.len(ConfigState.unlockAllBits) local length = math.max(realLength, allLength) local merged = buffer.create(length) for i = 0, length - 1 do local a = i < realLength and buffer.readu8(real, i) or 0 local b = i < allLength and buffer.readu8(ConfigState.unlockAllBits, i) or 0 buffer.writeu8(merged, i, bit32.bor(a, b)) end ConfigState.unlockAllLastReal = real ConfigState.unlockAllLastMerged = merged return merged end function UnlockAllSet(state) if not (InventoryStore and OwnedBitset and unlockAllOriginalGet) then WindUI:Notify({ Title = "Larp", Content = "Inventory store not found", Duration = 4 }) return end ConfigState.unlockAllEnabled = state ConfigState.unlockAllLastReal = nil ConfigState.unlockAllLastMerged = nil if state then ConfigState.unlockAllBits = UnlockAllBuildBits() InventoryStore.Get = function(self, key) local value = unlockAllOriginalGet(self, key) if ConfigState.unlockAllEnabled and key == "OwnedBits" then return UnlockAllMergeBits(value) end return value end else InventoryStore.Get = nil end end LarpUnlockAllItems = Tabs.Larp:Toggle({ Title = "Unlock All Items", Desc = "Fine you all want me to add this, it's basically useless", Flag = "LarpUnlockAllItems", Value = false, }) LarpUnlockAllItems.Callback = UnlockAllSet Tabs.Larp:Section({ Title = "Fake Stats", TextSize = 20 }) Tabs.Larp:Divider() function FakeStatsFormat(n) if formatUtil and formatUtil.Number then local text = formatUtil.Number(n) return text end return tostring(n) end function FakeStatsHookField(tbl, key, builder) if not tbl or type(tbl[key]) ~= "function" then return end if setreadonly then setreadonly(tbl, false) end local original = tbl[key] table.insert(ConfigState.fakeHooks, { tbl = tbl, key = key, original = original }) tbl[key] = builder(original) end function FakeStatsWithOverrides(map, name, value) if ConfigState.fakeEnabled and map[name] ~= nil then return map[name] end return value end function FakeStatsCloneWithOverrides(source, map) local copy = table.clone(source) if ConfigState.fakeEnabled then for name, value in pairs(map) do copy[name] = value end end return copy end function FakeStatsInstallHooks() FakeStatsHookField(currencyService, "Balance", function(original) return function(name) return FakeStatsWithOverrides(ConfigState.fakeCurrencies, name, original(name)) end end) FakeStatsHookField(currencyService, "All", function(original) return function() return FakeStatsCloneWithOverrides(original(), ConfigState.fakeCurrencies) end end) FakeStatsHookField(currencyService, "ObserveBalance", function(original) return function(name, callback) return original(name, function(value) callback(FakeStatsWithOverrides(ConfigState.fakeCurrencies, name, value)) end) end end) FakeStatsHookField(counterService, "Get", function(original) return function(name) return FakeStatsWithOverrides(ConfigState.fakeCounters, name, original(name)) end end) FakeStatsHookField(counterService, "All", function(original) return function() return FakeStatsCloneWithOverrides(original(), ConfigState.fakeCounters) end end) FakeStatsHookField(counterService, "ObserveCounter", function(original) return function(name, callback) return original(name, function(value) callback(FakeStatsWithOverrides(ConfigState.fakeCounters, name, value)) end) end end) FakeStatsHookField(progressionService, "Level", function(original) return function() return FakeStatsWithOverrides(ConfigState.fakeProgress, "Level", original()) end end) FakeStatsHookField(progressionService, "XP", function(original) return function() return FakeStatsWithOverrides(ConfigState.fakeProgress, "XP", original()) end end) FakeStatsHookField(progressionService, "Get", function(original) return function() return FakeStatsCloneWithOverrides(original(), ConfigState.fakeProgress) end end) FakeStatsHookField(progressionService, "Progress", function(original) return function() local level = progressionService.Level() local required = progressionService.RequiredXP(level) if required <= 0 then return 1 end return math.clamp(progressionService.XP() / required, 0, 1) end end) FakeStatsHookField(eventService, "Balance", function(original) return function(...) if ConfigState.fakeEnabled and ConfigState.fakeTickets ~= nil then return ConfigState.fakeTickets end return original(...) end end) end function FakeStatsRemoveHooks() for _, hook in ipairs(ConfigState.fakeHooks) do hook.tbl[hook.key] = hook.original end ConfigState.fakeHooks = {} end function FakeStatsGetHomeBottom() local home = PlayerGui and PlayerGui:FindFirstChild("HomePage") local root = home and home:FindFirstChild("Root") return root and root:FindFirstChild("Bottom") end function FakeStatsBindLabel(label, getText) if not label then return end local text = getText() if text and label.Text ~= text then label.Text = text end if not ConfigState.boundLabels[label] then ConfigState.boundLabels[label] = label:GetPropertyChangedSignal("Text"):Connect(function() if not ConfigState.fakeEnabled then return end local wanted = getText() if wanted and label.Text ~= wanted then label.Text = wanted end end) label.Destroying:Once(function() if ConfigState.boundLabels[label] then ConfigState.boundLabels[label]:Disconnect() ConfigState.boundLabels[label] = nil end end) end end function FakeStatsProgressTexts() local level = progressionService.Level() local xp = progressionService.XP() local required = progressionService.RequiredXP(level) return level, xp, required end function RefreshFakeStatsUI() local bottom = FakeStatsGetHomeBottom() if not bottom then return end local left = bottom:FindFirstChild("Left") if left then local rows = { Tokens = function() return currencyService.Balance("Tokens") end, Points = function() return currencyService.Balance("Points") end, Vouchers = function() return currencyService.Balance("Vouchers") end, Survivals = function() return counterService.Get("Survivals") end, Streak = function() return counterService.Get("Streak") end, Tickets = function() return eventService.Balance() end } for name, getValue in pairs(rows) do local frame = left:FindFirstChild(name) local amount = frame and frame:FindFirstChild("Amount", true) if amount then local value = getValue() if type(value) == "number" then local isFake = ConfigState.fakeEnabled and (ConfigState.fakeCurrencies[name] ~= nil or ConfigState.fakeCounters[name] ~= nil or (name == "Tickets" and ConfigState.fakeTickets ~= nil)) if isFake then FakeStatsBindLabel(amount, function() local current = getValue() return FakeStatsFormat(current) or nil end) else amount.Text = FakeStatsFormat(value) end if name ~= "Tickets" then local plus = frame:FindFirstChild("Plus") frame.Visible = value > 0 or (plus ~= nil and plus.Visible) end end end end end local levelFrame = bottom:FindFirstChild("Level") if levelFrame then local levelLabel = levelFrame:FindFirstChild("Level") local xpLabel = levelFrame:FindFirstChild("Experience") local bar = levelFrame:FindFirstChild("Bar") local isFake = ConfigState.fakeEnabled and (ConfigState.fakeProgress.Level ~= nil or ConfigState.fakeProgress.XP ~= nil) local function applyBar() local _, xp, required = FakeStatsProgressTexts() if bar then bar.Size = UDim2.fromScale(required > 0 and math.clamp(xp / required, 0, 1) or 0, 1) end end local function levelText() local level = FakeStatsProgressTexts() return ("LEVEL %*"):format(level) end local function xpText() local _, xp, required = FakeStatsProgressTexts() return ("%*/%*"):format(FakeStatsFormat(xp), FakeStatsFormat(required)) end if isFake then FakeStatsBindLabel(levelLabel, levelText) FakeStatsBindLabel(xpLabel, function() applyBar() return xpText() end) elseif levelLabel and xpLabel then levelLabel.Text = levelText() xpLabel.Text = xpText() end applyBar() end end function StartFakeStats() if ConfigState.fakeEnabled then return end ConfigState.fakeEnabled = true FakeStatsInstallHooks() RefreshFakeStatsUI() end function StopFakeStats() ConfigState.fakeEnabled = false FakeStatsRemoveHooks() RefreshFakeStatsUI() end function FakeStatsNumberOrNil(text) return tonumber((tostring(text):gsub("[%s,]", ""))) end FakeStatsToggle = Tabs.Larp:Toggle({ Title = "Fake Stats", Desc = "Client-side only. Changes what the game UI shows, not your real data", Flag = "FakeStatsToggle", Value = false, }) FakeStatsToggle.Callback = function(state) if state then StartFakeStats() else StopFakeStats() end end function FakeStatsInput(title, flag, onChange) Element_2 = Tabs.Larp:Input({ Title = title, Flag = flag, Placeholder = "Leave empty to show the real value", }) Element_2.Callback = function(text) onChange(FakeStatsNumberOrNil(text)) RefreshFakeStatsUI() end end FakeStatsInput("Fake Streak", "FakeStreakInput", function(v) ConfigState.fakeCounters.Streak = v end) FakeStatsInput("Fake Survivals", "FakeSurvivalsInput", function(v) ConfigState.fakeCounters.Survivals = v end) FakeStatsInput("Fake Tokens", "FakeTokensInput", function(v) ConfigState.fakeCurrencies.Tokens = v end) FakeStatsInput("Fake Points", "FakePointsInput", function(v) ConfigState.fakeCurrencies.Points = v end) FakeStatsInput("Fake Vouchers", "FakeVouchersInput", function(v) ConfigState.fakeCurrencies.Vouchers = v end) FakeStatsInput("Fake Tickets", "FakeTicketsInput", function(v) ConfigState.fakeTickets = v end) FakeStatsInput("Fake Level", "FakeLevelInput", function(v) ConfigState.fakeProgress.Level = v end) FakeStatsInput("Fake XP", "FakeXPInput", function(v) ConfigState.fakeProgress.XP = v end) Window:SelectTab(1) UniverseScriptsStuff = loadstring(game:HttpGet(BaseURL .. "/Module/More-Scripts.Lua"))() UniverseScriptsStuff(Tabs) Instance.new("Sound", game).SoundId = "rbxassetid://115778296381875" game.Sound:Play() game.Sound.Ended:Connect(function() game.Sound:Destroy() end) LocalPlayer.CharacterAdded:Connect(function() NexriftScheduleAutoApply() end) task.spawn(function() local lastStatus = nil pcall(function() lastStatus = ServerStateRegistryService.Registry.RoundStatus end) while true do task.wait(0.5) local ok, cur = pcall(function() return ServerStateRegistryService.Registry.RoundStatus end) if ok then if lastStatus == 2 and (cur == 1 or cur == 0) then lastStatus = cur NexriftScheduleAutoApply() else lastStatus = cur end end end end)
